/* 平成13年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h13.committeeSessions.push(...[{"id":"h13-20010830-14","meetingId":"h13-cm08","date":"2001年8月30日","dateIso":"2001-08-30","committee":"行財政改革特別委員会","time":"午後 １時１２分～午後 ４時２８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"相談の内容によってどこの課かなと悩むんですけれども、特にこの間二つほど経験したことをご紹介して、ちょっと見解を求めたいんです。その辺は課題になっていないんですけれども、課題にしてもらいたいというふうに思うんですけれども、いかがか尋ねました。","respondent":"桑村政策担当課長","answer":"確かに、そういうことで私どももフロアマネージャーということで３階では私もしましたけれども、なかなかわかりずらい部分があろうかと思います。名前がなくて、そのときは街路立体化とかいろんなことを考えたんですけれども…","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望ですけれども、今、入り口の３階にというお話なんですけれども、直接にエレベーターに行く人もいるので、ぜひ一年間ぐらいでも経過的でいいんですけれども、わかりやすいように表示をぜひしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ですから、例えばどうしても機械に対応していくわけですから、コンピューターが３台しかないところ、四つの窓口を築くというわけにいかない。これはまるっきり４月以降になって部になったから、議論が運んでという──どんな感じなんですか、何か運営の仕方が変わったのか。","respondent":"市岡企画財政課長","answer":"どうしても経営方針の確認のような、よくありがちですけれども、そういう色彩がなくもなかった。その結果、非常に活発な議論が行れておりまして、私も進行役として時間をいつも気にしながら関わっているとこういう状況です。","id":"exchange-003"},{"speaker":"辻副委員長","kind":"意見","question":"この辺については担当課長というのは１４でしたか、課長補佐が１１、４６課というと数はどういう感じに。４６課と担当課長とそのほかに課長とか何かあるのとの意見を述べました。","respondent":"桑村政策担当課長","answer":"中身のところを説明しなくて申し訳ございませんでした。担当課長については１４人、課長補佐については１１人、いわゆる下なり横なりという形でいるです。","id":"exchange-004"},{"speaker":"鶴委員","kind":"質問","question":"課長補佐という呼称ですけれども、「ああ、担当課長」とか、みんな職員同士で言っているわけですか。通称は何て呼んでいるんですか、「担当課長」と言っているのか「課長」と言っているのか。","respondent":"桑村政策担当課長","answer":"課長補佐につきましては、私などはなるべくその言葉を使うようにしておりますので、「何々課長補佐さん」というような形でお話ししています。ちょっとほかの部署を全部調べているわけではございませんので、話はちょっとわかりませんけれども…","id":"exchange-005"},{"speaker":"鶴委員","kind":"質問","question":"ちょっと教えてほしいんですが、警部補といるでしょう、あれは何かの略ですか。そのほうがいいというふうに、僕の考えでは思ったものですから質問したり、参考意見を述べさせていただきました。","respondent":"古川人事課長","answer":"課長補佐という呼称を用いることができるというような形で、平成１１年度に２３区の中で一定の考え方を整理した経緯があります。課長補佐については、一定２３区の中で全体として認識のできる名称としては一応統一的に使われていると、こういう内容です。","id":"exchange-006"},{"speaker":"菅家委員","kind":"質問","question":"それから予算執行の問題にしても、部長にすべての権限が一括委任されるというシステムになるわけでしょうから、こういう認識でよろしいのかどうか。こういう答弁だったけれども、ちょっと今さらという感じがしないでもないんだけれども、これらに対する基本的な考え方について聞かせてほしい。","respondent":"桑村政策担当課長","answer":"の各係長なりに職員をまとめていただくという役割を発揮していただける係長というようなことでの位置づけもできないかということを考えております。それを課長補佐会なり何なりの形のそういう意味での意識改革…","id":"exchange-007"},{"speaker":"菅家委員","kind":"意見","question":"その上に立つ人たちが、その辺の建前の上からいっても矛盾点があるので、そういう面はどういうふうな判断をしていけばいいのか。でも、それはむしろ係長のほうがふさわしいんじゃないかと思うんだけれども、その辺の扱い方はどういうふうな理解をすべきなのかとの意見を述べました。","respondent":"中尾根企画部長","answer":"お話がありましたように、それぞれ全庁的な共通した課題について検討し、各事業部にいろいろこの間どうだというアンケートを取りました。どうしても従来の総括係長という認識のとらえ方のほうが強く、そこを払拭していかなければならない課題ということで載せさせていただきまし…","id":"exchange-008"},{"speaker":"菅家委員","kind":"質問","question":"素晴らしい答弁が出てくるのかと思って期待して、新鋭の課長を配置しますなんていう答弁が来るんじゃないかと思って期待していたんだけれども、それもなさそうですからやめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"よりわかりやすくするためにお伺いしたいんですが、内容的に定性的な評価と言うのでしょうか、これを例えば数字化した定数評価と言うのでしょうか。今後の対応の２番目にも、今回の組織替えということを評価の対象にされていらっしゃるのかどうかをお伺いいたします。","respondent":"桑村政策担当課長","answer":"なかなか定数化というのは、非常に難しいと思うんです。事業部としては順調に行っているということで、今後はこれからの事業としての成果がどういうふうに上がってくるかということだろうと思ってあります。","id":"exchange-010"},{"speaker":"金高委員","kind":"質問","question":"その一歩下の部会議と言うのですか、今までの３月までの時点と４月以降の流れ、どのような形で変わってきたかとなると思うんです。その前の段階の組織の運営、中間でどのぐらいの会議の状況でどういうふうになっているか、状況で結構ですからお知らせ願います。","respondent":"桑村政策担当課長","answer":"通常であれば週１回なり、あるいは隔週なり定例的な会議を持って、各課長の調整をやっているのが通例だと思われます。その意味では、中での運営方法というのは、その中ではそれほど変わっていないのではないかというふうに思います。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"あるいは先ほどの表現力、言葉的なといいますか、定性的なといいますかどういう形での効果が出てくるのかということが１点。これは議運マターになってしまうのかもしれないんですが、議会側のシステム化ということはどうなんか尋ねました。","respondent":"田中情報システム課長","answer":"横須賀市ですと、品川区はちょっと違いますので、どのぐらいになるのか実際のところ定量的な効果について出しております。こういう人たちが要らなくなりますので、そういう点で定数減等を含めまして、費用対効果を出していくということになると思います。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"相当な投資額になりますので、それに見合うという言いますか、それ以上の効果が上がるように、ぜひ引き続きご努力をほしいと求めました。議会側の例えば議事録の検索ですとか、視野に入れたシステム化はぜひ議会側もともに投資をしてほしいと求めましたが。","respondent":"福田区議会事務局長","answer":"議長からも既に区議会事務局は検討を命じられておりますので、議運の中で十分に検討をさせていただきまして、できるだけ早期に結論を得、立ち上げたいと考えております。","id":"exchange-013"},{"speaker":"辻副委員長","kind":"意見","question":"１回目に買うときにそろえて、全部ともかく、ソフト代というのがものすごくかかってくるわけですね。そこの部分の費用というのは庁内にこれだけ入ってきたら、その辺の費用というのは、どの辺まで頭に入っているのかとの意見を述べました。","respondent":"田中情報システム課長","answer":"２３区と東京都で一つでユニットを組んでおりまして、ほぼ市価の４０％程度でライセンスを購入するということで、２３区と東京都はしております。品川区で音頭を取りまして、２３区と東京都にお話しをして…","id":"exchange-014"},{"speaker":"辻副委員長","kind":"質問・要望","question":"これは一般区民と同じような扱いでしなきゃいけない、どうやってネットを組んでやるのか。そこの部分の縦分けというものは、どういうように考えていったらいいのかなと。","respondent":"田中情報システム課長","answer":"そこから出ていくときには、ファイヤーウォール等を設置しておりまして、外から入れないような形に、権限のない人はないようにしてあります。検索エンジンと言いますか、区民の方やユーザーの方が見るときに…","id":"exchange-015"},{"speaker":"辻副委員長","kind":"質問・要望","question":"要望で終わりますけれども、あんまり急いで変なものにしてもしようがないなという思いもあるんです。だから、そこのところひとつ急いでもらいたいんだけれども、あんまりばたばたじゃないようなやつをやっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"桜井委員","kind":"提案","question":"今の確認の件ですけれども、文教委員会にも提案がされて、ちょっといかがなものかと思っています。文教委員会の中でも、一応各委員の中で出た意見を申し伝えるという形を取っておりましたので、そうしていただければありがたいというふうに思いますとの意見を述べました。","respondent":"塚本委員長","answer":"どのような形でお答えをするかと、委員会の意志という形でするのか、それはしばらく検討させていただきたいと思います。○午後 ４時２８分閉会","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503251?Template=document&Id=5690#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":22391,"voices":45}},{"id":"h13-20010921-4","meetingId":"h13-c-settlement","date":"2001年9月21日","dateIso":"2001-09-21","committee":"決算特別委員会","time":"午後４時１４分～午後４時２４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/321088?Template=document&Id=1178#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":2790,"voices":18}},{"id":"h13-20010925-6","meetingId":"h13-cm09","date":"2001年9月25日","dateIso":"2001-09-25","committee":"区民委員会","time":"午前１０時０６分～午後４時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を99件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"平成１３年度に繰り入れた部分があると思うんですが、都の補助金から4,８１０万円がきておりますので、トータルで出ていると思います。この時点で結構ですから説明を求めました。","respondent":"宮地区民課長","answer":"こちらの内訳ですが、１億8,７３４万3,０００円は、もともと当初予算を差し引いたものですので、全体が２億２９９万6,０００円となっています。そのうちの7,８３１万5,０００が東京都からの都市計画交付金ですので、それを差し引いた金額が自主財源ということになりま…","id":"exchange-001"},{"speaker":"原委員","kind":"意見","question":"これは今年度ですよね。これから後の財調にもかかってくると思いますが、それぞれの割合で分担されるのかどうかについてお尋ねいたしますとの意見を述べました。","respondent":"宮地区民課長","answer":"とりあえず都市計画交付金が今年度は１５％という形で計上させていただいたものです。地方債の返還分も含めまして、それを計算しますと、２億2,２００万円が自主財源から将来的にわたって出る部分です。","id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"７０％要求が、結果的には５０％ということですけれども、単価は幾らだったのか。もう一度各区の負担割合はどういうふうになっているのか説明を求めました。","respondent":"宮地区民課長","answer":"目黒区が7.６５％、大田区が４6.８５％、世田谷区が１6.５５％です。５区ですから、２０％ずつ、そういった形になってあります。","id":"exchange-003"},{"speaker":"本田委員","kind":"質問","question":"今の割合で、金額、土地の負担割合、その他の管理費については、当面は均等割ということです。平成１６年度開設に向けて、平成１３年度は実施設計をするというふうに計画しておりますが、進捗はどういう具合か尋ねました。","respondent":"宮地区民課長","answer":"順調に進捗してございまして、定例的な会議の中で、部長会、課長会があります。その中でも今詰めているところですので、予定どおり進みまして、平成１６年度開場に間に合う予定です。","id":"exchange-004"},{"speaker":"金高委員","kind":"意見","question":"先ほどの説明で、助成事業の補助形態と、コミュニティ以外での補助金申請というのもあるのか。その辺をお聞かせ願いたいと思いますとの意見を述べました。","respondent":"長田地域活動課長","answer":"平成１２年度につきましては、清掃との関係で、折り畳み式のアルミのリヤカーを買ってあります。それから、青少年のほうでは、平成１２年に中学生の主張大会で補助金申請をして、一定額をいただいた経過があります。","id":"exchange-005"},{"speaker":"金高委員","kind":"質問","question":"もう１点、利用団体として、町会、自治会、地区委員会、高齢者クラブ、ＰＴＡ等というお話がありましたけれども、これを購入されて、地域センターのほうにお配りしていると思うんですが、団体に対して、貸し出しができますというＰＲ方法は具体的にどういう形でやっておるんか尋ねました。","respondent":"長田地域活動課長","answer":"それから、区で用意をしている備品につきましてもお貸ししている部分もありますから、すでに地域の方々はその制度というのはご存じかと思います。そういった意味で、備品としてワイヤレスマイク等を買うわけですから…","id":"exchange-006"},{"speaker":"堺委員","kind":"質問・要望","question":"それを確認の意味で教えてほしいと求めました。その割合を確認の意味でお願いいたします。","respondent":"宮地区民課長","answer":"当初予算に計上してある部分につきましては、前年度からの実施設計の部分の委託費関係です。それの初年度分として今年度１５％を財源で組んでおるわけです。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"全体が４３億円、そのうちの７割が交付金、そういう考え方でいいんですか。ちょっと金額が違うのではないか尋ねました。","respondent":"宮地区民課長","answer":"トータルしまして２億2,２００万円ですので、純粋に区が最後まで支払いを終わって負担する部分というのは２億2,２００万円。７億3,８５８万9,０００円のうち、最終的な数字が、現在分かっているところで２億2,２００万円です。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"そうすると、さっき約７億4,０００万円のうち５億2,０００万円ぐらいは交付金でくる。だから、２億2,０００万円が区の持ち出し、一般財源負担ですよという理解でいいんか尋ねました。","respondent":"宮地区民課長","answer":"それのうちの、平成１３年度負担分を１億9,０００万円を計上させていただきまして、利子も含めまして、２億２９９万6,０００円を負担する。当初予算の部分につきましては、用地費ではございませんが、総トータルの中での計上ですので、それを差し引かせていただいたです。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問","question":"品川区の負担率は１7.２％ですか、さっきの約７億4,０００万円という、１7.２％という考え方なのか。その分が１7.２％ということか尋ねました。","respondent":"宮地区民課長","answer":"ただ、一遍で見ていただけるわけではありませんので、大体５年間ぐらいの間に少しずつ入ってくるわけです。平成１３年度は１５％しか入ってきませんので、平成１３年度負担は、２億２９９万６,０００円と言うことになります。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"こういうのは向こうのほうから、「こういうのがあるけれども、申請をしてみませんか」というふうな内諾があるんですか。その辺の絡みも含めて、今回の２３０万円のことについてちょっと教えてほしいと求めました。","respondent":"長田地域活動課長","answer":"助成金の種類につきましては、さっき一般コミュニティ助成、緑化推進コミュニティ、青少年健全育成助成と３種類あるというふうに説明申し上げました。１件当たり５０万円から２００万円まで、１件当たり３０万円から１００万円まで、これが限度額です。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"一般コミュニティ助成、緑化推進コミュニティ、青少年健全育成、３種類、それぞれ所管のほうから申請している。そうすると、コミュニティおよびその他、同じ区で３種類の申請があっても交付がされるということか尋ねました。","respondent":"長田地域活動課長","answer":"この制度自体が３種類の構造形態を想定していますから、基本的には可能です。私どもで言えば、コミュニティの役に立てていく、こういうことです。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"精いっぱい補助金を申請して、いただけるようにお願いしたいと思います。３種類も可能だということであるならば、それぞれが申請して、いいような気がしたので、今年はこういう３種類はそれぞれ申請したのか尋ねました。","respondent":"長田地域活動課長","answer":"先ほど条件の話を申し上げましたけれども、なかなか条件が厳しいために、申請をしたくてもできないようなところもあるのかと思います。ただ、先ほども申し上げましたとおり、条件がなかなか厳しいというのはお聞きしています。","id":"exchange-013"},{"speaker":"石田副委員長","kind":"質問","question":"２億2,０００万円の中の財源がくるんだと。５区でどういう話をされているのか、そこら辺をちょっと説明を求めました。","respondent":"宮地区民課長","answer":"今のところこれといった補助制度がありませんので、さらに、とにかくいただけるものは何でもいただきたいということで交渉をしていく予定でおります。その結果はまたご報告をさせていただきたいと思います。","id":"exchange-014"},{"speaker":"石田副委員長","kind":"質問・要望","question":"もう１点、どれぐらい要望があって、地域活動課で動こうかと思われる判断というのがあると思うんです。こういう要望があるから、ひどいなと思って、その判断をどこでされているかというのをちょっとお聞きしたいと思います。","respondent":"長田地域活動課長","answer":"区としても、１００％に近い補助金ですので、区側のほうで実際に地域に何が必要かということで判断をする場合もあります。いずれにしても、その両方を加味しながら、最終的に品物を決定していく、こういうような手続きをとってあります。","id":"exchange-015"},{"speaker":"石田副委員長","kind":"質問・要望","question":"本当に地区から上がってきた要望なのか、そこら辺は非常に難しいところだと思いますが、そこら辺の情報収集をぜひやっていただきたい。これは要望にしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"本田委員","kind":"質問・要望","question":"要望ですけれども、５区が主張をしていた根拠は何かということは、当局がやる仕事ではないのかというのがいろいろな場面で説明をされてきました。要望だけでなくて、ご見解をお聞きしておきたいと思います。","respondent":"宮地区民課長","answer":"５区の区長が副知事に会いに行ったとときも、管理者の最終的な判断で５割減額等々がこの間出てきたわけです。執行機関と区議会の両方で取り組んできたもともとの根拠から入りまして、５区ということで、物が言えるような形ではやっていきたいと考えております。","id":"exchange-017"},{"speaker":"南委員長","kind":"確認","question":"この根拠となったのを改めて確認しておきたいと思うんです。その辺、区長会として７割だというふうに主張してきたのを、５割でやむを得ないというふうに判断されたそこのところを改めて伺いたいと思います。","respondent":"宮地区民課長","answer":"実施設計に移るところですし、そのまま５割減額ということではなく、５割でということにしたものです。それから、都市計画交付金の対象範囲を６割から７割へ面積を減してやられたところですし、その判断のもとに５割もやむを得ないです。","id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"今お話の中で繰り上げ返還の話が出たんですけれども、返還の利用方法というんですか、その辺のところはどうつかんでいるのか。短くすることによって、より返還ができなくなってしまうという部分も出てくると思うんですが、その辺の兼ね合いはどうか尋ねました。","respondent":"宮地区民課長","answer":"いずれにいたしましても、滞納が出るというのは、どうしても発生せざるを得ないので、これについては、滞納をさせない取り組みをやっていく。あるいは連絡がつく、その期間というのも必要であろうという判断のもとに、変えさせていただきたいです。","id":"exchange-019"},{"speaker":"原委員","kind":"質問","question":"１２％の滞納というのは、推移でいくと、毎年このぐらいの人数で出るんでしょうか。９区が１０年、ここのところの各区は、奨学金に対してのお支払いいただけない部分、滞納の率はどのぐらいになっているのか分かりますか。","respondent":"宮地区民課長","answer":"例えば１０年間とっているところで、安いから１０年間で払えるのではないかということがありますが、滞納率も高い状況です。１カ月でも滞納しますと、現在も取り組んでおりますが、訪問督促の取り組みなどをしています。","id":"exchange-020"},{"speaker":"原委員","kind":"質問・要望","question":"金額的に少ないと見ているんですけれども、でも、払い出す時期はその人にとってかなり負担の額なんです。これは要望ですけれども、負担がかかるわけですから、その辺をお考えほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問・要望","question":"その間内容証明を通知しているということを伺っているんですけれども、これまでそれ以外の法的な措置というのは行われたことがあるのかどうか。1,７００万円とか1,９００万円ぐらいで行き詰まっているけれども、今の取り組みと、以前の取り組みの違いを教えてほしいと求めました。","respondent":"宮地区民課長","answer":"納付書が１回きりですので、どこかへいってしまったとかというのが一つ考えられますが、３月末にもう一度お送りするわけです。これから上げていきたいというふうに思っておりますので、そういうのも合わせて、今後取り組んでいきたいというふうに考えております。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"そのときの時代背景で多少強弱というか、変わりがあるのかどうか、ちょっとお聞きしたいと思います。","respondent":"宮地区民課長","answer":"今までは保証人のところまでは直接取りに行くということはありませんでしたが、電話での問い合わせはしています。そして家族という形で取り組んでまいりますので、支払い計画を立てるように、まずはお話をします。","id":"exchange-023"},{"speaker":"菊地委員","kind":"意見","question":"そもそもの奨学金の本来でき上がってきた経過を見れば、教育そのものをみんなが受けられる体制にさせるためにできたものだと思うんです。品川区が２０年から１５年にしたということで、決して５年間を縮めていくところが、どうなのかなという気がするんですけれどもとの意見を述べました。","respondent":"宮地区民課長","answer":"年間の取り組み方で返還金額を上げることはできると考えています。年間６万円から８万円、両方相まっていい形になるのではないかと考えていますので、短縮をさせたほうがメリットが大きいというふうに考えてあります。","id":"exchange-024"},{"speaker":"金高委員","kind":"質問","question":"１２％の方のうち、最もペナルティの重い、そういうのは何かあるんか尋ねました。","respondent":"宮地区民課長","answer":"給与所得のある人につきましては、４分の１の課徴金、それが今のところは一番重いものです。","id":"exchange-025"},{"speaker":"金高委員","kind":"質問・要望","question":"結局なし崩し的になってしまってうまうわけですから、そういう面では税金の一部が使われているわけですから、その辺のところをもっと厳しく考えてほしいと求めました。","respondent":"宮地区民課長","answer":"今この時点でどういう取り組みをしたらいいかということになると思うんですけれども、今のところ夏を中心に訪問督促をやっております。９月末で一通りそれが終わりますので、また再度こういう形で直接行って、そういう形で強力に取り組んでいくつもりです。","id":"exchange-026"},{"speaker":"金高委員","kind":"質問・要望","question":"例えば計算違いでもって1,０００円を納付してもらうというときに、伺ったり、あるいは調査の費用が莫大かかったんだというような話も聞きます。無駄だというような形も出てくる例もあると思いますが、その辺も考慮しながら、ぜひ頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"本田委員","kind":"質問","question":"事業概要では、平成１３年度ベースでは１０１名となっていますけれども、申請はどれぐらいあったのでしょうか。利用するというのも増えていくのかなとも感じているんですが、その辺はどう評価するのか、お尋ねしたいと思います。","respondent":"宮地区民課長","answer":"貸付が１１４人ということになっておりますので、１００％ではないんですけれども、人数的にも応募は増えてきているというのが実情です。ちょっと検討をするところがあろうかと思います。","id":"exchange-028"},{"speaker":"本田委員","kind":"質問・要望","question":"１００名とか１２０名とかと決めて、私のほうで行政主体への要望は、本来の趣旨に合致した制度運行がされると。事業概要で１０１名と書いてあったものですから、今１１４名というふうに言われて、考え方だけ教えてほしいと求めました。","respondent":"宮地区民課長","answer":"何をやっているんだということになりますので、きちんと返ってくる仕組みと、それを埋める努力をしませんと難しいかなと考えております。まずそちらを努力していきたいというように考えております。","id":"exchange-029"},{"speaker":"本田委員","kind":"質問・要望","question":"その辺は理解します。新しくするというような、奨学金制度というものがどういうふうに利用され、予算を含めて努力をお願いしたいというふうに要望をしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"堺委員","kind":"質問","question":"奨学金が私立の入学準備金が２０万円、在学資金が２万8,０００円。公立が入学準備金が７万円、在学資金が１万3,０００円となっていますが、これはいつ頃からこの金額になったんか尋ねました。","respondent":"宮地区民課長","answer":"さかのぼって今ちょっとお答えできないんですけれども、私立は平成１１年の見直しで、適用が平成１２年４月からということになっております。公立については今資料がないものでわかりません。","id":"exchange-031"},{"speaker":"堺委員","kind":"意見","question":"その内訳ですけれども、私立何名、公立何名、あるいは私立の中で、区外という、１回も返していない人が２９名、そのうち沖縄の人がいる。1,０５３名の内訳で、私立が何名、公立が何名、そのうち私立で区外の人が何名、区内が何名なのかとの意見を述べました。","respondent":"宮地区民課長","answer":"そこら辺までは掌握していないんですけれども、1,０５３名のうち半数が区外です。一番古い人は昭和４２年度貸付の人なので、すでに区外に出られている方がかなり多くて、半数ぐらいは区外の方です。","id":"exchange-032"},{"speaker":"堺委員","kind":"質問・要望","question":"単純に、返還中の人が1,０５３名ということですから、1,０５３名の人たちの残高が５億5,３００万円ということになってくる。それまでの大変さから言うと、大丈夫なんですかという感じがするんですけど、いかがか尋ねました。","respondent":"宮地区民課長","answer":"それは期間というよりも、こちらをきっちりいただく仕組みと、収納の進行管理をするということに尽きるのではないかというふうに考えております。ハードですが、きちんと入ってくるように日々努力するということになろうかと思います。","id":"exchange-033"},{"speaker":"堺委員","kind":"質問・要望","question":"結果が生まれるように、ご努力は大変だと思いますけれども、お願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"私立の在学資金が２万8,０００円ですが、これは一律に２万8,０００円なんですか。それと、基本的なことになってしまうんですけれども、契約者は、入る本人なのか、それとも未成年なので、親御さんがなるのか。","respondent":"宮地区民課長","answer":"２万5,０００円、２万円8,０００円ではちょっと不足なんですけれども、そこら辺は家庭から出していただくというような形になっております。基本的にはまだ未成年ですので、本人の契約者の当事者にはなれないんですけれども、一応保証人２名と本人という形で契約しています。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"保証人２名というのは、ただの保証人なのか、それとも連帯保証人なのかということと、あと、お借りした額に関して、金利はどうなっているんか尋ねました。","respondent":"宮地区民課長","answer":"１名は、親ですので、親権者という形になります。それから、これは金利は無利子です。","id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"もう一回確認させていただきたいんですが、未納率１２％というのは、返せる金額の総額の１２％なのか、それとも1,０５３名の１２％なのか。それとの兼ね合いで、例えばダブルに受けることがあるのか、あるいはどういうふうになっているのか、それをちょっと説明を求めました。","respondent":"宮地区民課長","answer":"ほかの奨学金があるんですけれども、基本的にはダブルではいけないようになっております。それから、滞納ですけれども、今の時点で1,０５３人返還中で、２９５人が滞納しているということですので、実際には人数の割でなくて、金額です。","id":"exchange-037"},{"speaker":"原委員","kind":"質問","question":"そうすると、人数の割合でいくと、３割近くになる。２９５名が滞納しているわけですから。","respondent":"宮地区民課長","answer":"全体の人数です。人数の割で１2.５％です。","id":"exchange-038"},{"speaker":"原委員","kind":"意見","question":"それにしても、１００名以上が滞納をしているということは、大変な額が未納で、しかも、年数が減ってくるということになっていますが、どういう意図で年数を減らしたのかよくわかりませんけれども、その辺が裏腹のような感じがしてしっくりこないんですけれども…","respondent":"宮地区民課長","answer":"期間を２０年から１０年というのは、一挙に短くなり過ぎるので、１５年ぐらいではどうかというような意見もございました。滞納率を下げる努力をしませんと、これはますますふくれ上がってきますので、その努力をしたいと思います。","id":"exchange-039"},{"speaker":"原委員","kind":"意見","question":"このような形でいこうかというようになったと思うんですけれども、その辺のところはもうちょっと、有効にやらざるをえなかったかなと思います。いずれ私としてはそれは認めますけれども、何かもう一工夫があってもいいかなという意見を付しておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"石田副委員長","kind":"質問・要望","question":"あれなんですが、一つお聞きしたいのは、中央区と豊島区が制度がない理由が分かれば教えていただきたい。そこら辺のところまで踏み込んで考えられるのかどうかという、法的な、そこら辺をちょっと教えてほしいと求めました。","respondent":"宮地区民課長","answer":"月々のではなくて、支度金だけがあったわけですけれども、それをなくしたというふうに聞いてあります。ポイントで２０点満点という形でやっているというふうになっておりますが、今の方法、またご相談をさせていただきたいというふうに考えております。","id":"exchange-041"},{"speaker":"石田副委員長","kind":"質問・要望","question":"もともとない理由というのか、やらないで、ほかのもので何か、いろいろそういうものがあるならそれを教えていただきたいという１点。実質収入の部分に、もし給与所得が違う方面からの手を入れるという場合は、これは品川区で全部条例で決めればＯＫだという理解でいいんか尋ねました。","respondent":"宮地区民課長","answer":"それは区独自の奨学金制度ですので、それは可能です。中央区につきましては、何で初めからないのかについては、ちょっと調べさせていただきたいと思います。","id":"exchange-042"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そうなると、品川区でいろいろ貸付と、これは貸付制度ですよという捉え方の中で、実質収入を入れているという形をとっているわけですね。私のちょうど生まれる頃の制度ですから、どこでどういうふうに仕分けをしていったかというのが、その理由が分かれば教えいただきたい。","respondent":"宮地区民課長","answer":"日本育英会の見直しを進めているということですので、実態に合った変更等、採用方法というのは必要かと思います。は給与所得で考えているということであれば、そこら辺も検討の材料になろうかと思いますので、調べさせていただきたいと思います。","id":"exchange-043"},{"speaker":"石田副委員長","kind":"質問・要望","question":"日本育英会からの、例えば参考にこういう制度ができたということであるなら、その考え方を教えていただきたい。まとめたものとか、調べたものを、資料を後でいただければと思うし、そこら辺の考え方を整理をしていただきたいなというのを要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"南委員長","kind":"質問・要望","question":"私も二つお伺いしたいと思うんですけれども、先ほど教えていただけたんですけれども、ちょっと分かるように教えていただきたい。もしそれが可能であれば、どういう状況になっていたのか教えてほしいと求めました。","respondent":"宮地区民課長","answer":"柔軟にこの辺はやっておりますし、今後とも少しでも返していただくようでしたら、柔軟に対応してまいりたいというふうに考えております。そういう傾向にあります。","id":"exchange-045"},{"speaker":"原委員","kind":"質問","question":"そういう金額はどのぐらいになっているんですか。そして、取れないところはどういう処理をしているのか。","respondent":"宮地区民課長","answer":"２０年経過しても取っています。２０年というふうに返還期間は取れないわけですけれども、やはり２０年を過ぎましても返し切れていない、返していただくまでは何回でも。","id":"exchange-046"},{"speaker":"原委員","kind":"質問","question":"たまっていく金額がどんどん増えてくるということですか。そうすると、どこかの時点で何とか処理をしなければならない面が出てきますね。","respondent":"宮地区民課長","answer":"最終の２０年で返還期間が終わって、その後１０年間１回も支払われない、住所不定の場合は不納欠損で処理をします。というような処理をしておりますが、それからさらに１０年間という形になりますので、基本的には不納欠損で落とすということはめったにありません。","id":"exchange-047"},{"speaker":"菊地委員","kind":"質問","question":"そういう経過をもっと見つつ、期間の問題について考えるべきではないかなという気がするんです。ですから、私としては現時点で今の不況の中で期間を２０年から１５年と短縮することについては、反対したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"本田委員","kind":"質問・要望","question":"ぜひそれはやってほしいと求めました。やっていただきたいということを要望いたしますが、今度の改正を契機に減少するように努力をしていただきたいということを要望したわけですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"原委員","kind":"質問・要望","question":"先ほど私のほうからの何点か質問をさせていただきました。基本的にはこれからいろいろ要望をされるようですし、効率的な運用がされるようなことを努力いただくという意見を付して、賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"金高委員","kind":"質問・要望","question":"それを追いかけながら、システムを変えながら、徴収する。何回も請求する努力、何だというような目で見るところもあると思うんですけれども、そういうところも乗り越えてぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"堺委員","kind":"質問・要望","question":"先ほどもわからない点を教えていただいた、奨学金貸付そのものは進学資金ということであるが、結論的には有能な人材育成の事業です。そういう方向で努力されることを要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"奨学金を貸し付ける目的として、有用な人材育成することが目的となっていますので、借りたものは返す。借りたものは、うまいことすれば返さなくてもいいというような人材を育成しないようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"}]},{"id":"topic-02","title":"第７３号議案 品川区生活安全条例","agenda":"第７３号議案 品川区生活安全条例","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"生活安全協議会の中に所轄の警察の方は入るんか尋ねました。","respondent":"長田地域活動課長","answer":"この条例の細部につきましては、規則に委ねるというようなことで第５条に位置づけをしていますけれども、今後規則について制定をしてまいります。ただ、当然そういった連携という部分も含めまして、警察の実際に犯罪の予防に係わる部署の代表者を委員の中に入れる予定です。","id":"exchange-054"},{"speaker":"金高委員","kind":"質問・要望","question":"それから、第３条関係ですけれども、区が行う施策の実施に協力と責務という、要するに、区民に責任がありますよという、その辺のところです。それを責務とするというところの意味合いが、もう少し具体的にどういうことを意図しているかということを教えてほしいと求めました。","respondent":"長田地域活動課長","answer":"支援の問題ですけれども、広く防犯という意味では、今までもかなり区として実施をしてきた部分があります。警察にお任せをするだけでは解決をしない問題もあるということで、区民総ぐるみで犯罪の防止に努めていきましょうというのが、この３条の内容です。","id":"exchange-055"},{"speaker":"金高委員","kind":"意見","question":"ちょっと路地裏に行きますと、そういうものも環境整備の中に当然整備の問題がかかってくると思いますけれども、入ってくるのかどうか。その辺でもし何かあれば、お聞かせ願いたいと思いますとの意見を述べました。","respondent":"長田地域活動課長","answer":"そちらのほうの連合会で１３地域、最近は健全図書とビデオテープの自動販売機に加えまして、最近コンビニがかなり増えてきてあります。壁１枚といいますか、区画一つで区画をされているというようなことがあって、そういった部分の環境整備についても今併せて行っているところで…","id":"exchange-056"},{"speaker":"金高委員","kind":"質問・要望","question":"総合調整の場となりますと、それ以外に総合調整の場ということですから、ほかに何か区民委員会とはまた別の委員会が所管する何かありますか。そういったものが何かありましたら教えてほしいと求めました。","respondent":"長田地域活動課長","answer":"それぞれそこで決まった内容を、それぞれの団体に持ち帰って、それを実施をしていただくというようなことで考えてあります。品川区は品川区でその協議会で決定をいただいた内容、品川区がやるべきことがあれば、それはきちんとやるべきだろうというふうに思ってあります。","id":"exchange-057"},{"speaker":"本田委員","kind":"意見","question":"今の協議会のことですけれども、それぞれの団体が持ち帰って生かしていくということですが、それぞれの団体というのはどういう団体か。警察とか、防犯協会とか、いろいろな団体が生まれていくと思うんですけれども、その構成という部分では、どのくらいの規模を考えていますかとの意見を述べました。","respondent":"長田地域活動課長","answer":"施行が平成１４年４月１日になるわけですから、それに向けて規則の制定を行っていきたいというのが基本的な考え方です。は基本的には行政機関の代表ということで、実際にはおそらくもうちょっと少なくて済むだろうというふうに考えております。","id":"exchange-058"},{"speaker":"本田委員","kind":"質問","question":"この制定の理由や目的にかなったものにどうしていくかということを、ある意味では方向付ける日常の活動のものになるといいですよね。その辺をどういうふうに、私は広く組織をつくったほうがい良いと思うんですが、いかがか尋ねました。","respondent":"長田地域活動課長","answer":"最大で３０名ということで予定をしていますけれども、もっと大きく、概ね今想定しているものですと３０名に満たないかなというふうに思ってあります。その辺は意見としてお聞きをしまして、今後の構成をどうするか決めていきたい、このように考えてあります。","id":"exchange-059"},{"speaker":"本田委員","kind":"提案","question":"その辺は十分ご検討されて、この条例はご提案されているんだと思います。区の当局としてはそういう問題についてはどういうご認識でやっておられるんか尋ねました。","respondent":"長田地域活動課長","answer":"３条関係は、私どもは３条関係、区民および関係団体の責務というようなことで説明をさせていただきましたけれども。そういった意味で、そういった懸念をされるのはもちろん、それに対応していくこともあらかじめ想定をすることは必要かと思いますけれども。","id":"exchange-060"},{"speaker":"本田委員","kind":"質問・要望","question":"１万人近くが生活をされているわけでして、こういう条例が、逆にお互いにプラスに作用するような内容でないと大変困る問題にいきかねないですね。逆にマイナスを起きては困るわけですから、その辺は要望にしておきますけれども、こういう基本的条例の提起ですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"原委員","kind":"質問・要望","question":"さらに警察等が集めているそういった幾つかの関係を持っている団体との調整はどういうふうにしているんですか。そういう部分で、お考えをお持ちの部分があったらお知らせほしいと求めました。","respondent":"長田地域活動課長","answer":"それから地域ですでにパトロール活動等を実施をしているところがあるということでございまして、実は池田小学校の事件以来、それぞれのＰＴＡ。来年早々、５月ぐらいには第１回を開催をしたいというふうに思っている部分もありますし、このように考えているところです。","id":"exchange-062"},{"speaker":"原委員","kind":"質問","question":"今お話を伺っていて、実際これから立ち上げていくわけですけれども、２つ問題があると思うんです。現実の中にどう生かしていくかというのが一番大事なところだと思うんですが、そのところの生かし方は、何か規則が考えられているんか尋ねました。","respondent":"長田地域活動課長","answer":"警察法の第２条に、被疑者の対応、こういうことが位置づけられております。ですから、そういう意味では、議題を決めまして、一つずつ効果が出るような形に協議会の運営はしていきたい、このように考えております。","id":"exchange-063"},{"speaker":"原委員","kind":"意見","question":"当委員会の意向につながるような形のもので、警察のほうと係わり合いのある形で考えていってほしいと思います。警察の協議会もそうだし、防犯もそうですし、意見交換みたいなものもありますし、そういう係わり合いは特に調整をするということは考えておりますかとの意見を述べました。","respondent":"長田地域活動課長","answer":"規則を決める中で、その辺の必要に応じて委員を増やすことももちろん可能ですので、そういった中で決めさせていただきたい。実効のあるような協議がなされるべきであろうし、そうしていきたいということで、考えているところです。","id":"exchange-064"},{"speaker":"菊地委員","kind":"質問","question":"私はどうも、新たな条例の制定との関連というのが明確になっていないものですから、その辺でお聞きしたいと思います。","respondent":"長田地域活動課長","answer":"ただ、こういった部分の検討というのが十分されていなかったという部分の中で、そういったご発言をしたものだというふうに思います。ですから、そういった中で効果を出すというのは、原委員からもご指摘いただいたように、難しい部分というのは確かにあります。","id":"exchange-065"},{"speaker":"菊地委員","kind":"質問","question":"本田委員が言われていた、実際に区民が区民を監視するかのような体制というのは、いやも応もなくできてしまうのではないでしょうか。その辺で、今課長が言われた話の内容だけでは、協議会そのものがどうも見えてこないような気がしています。","respondent":"長田地域活動課長","answer":"例えばノウハウを持っている警察、あるいは防犯協会、こういったところで意見を言ってもらうというようなことは十分考えられることだと思います。くれぐれも、その協議会の委員長がその辺の部分はきちっとお考えを持った上で運営をされていくべきだろう…","id":"exchange-066"},{"speaker":"石田副委員長","kind":"質問","question":"具体的にお伺いをしたいのは、今度の生活安全協議会に出てきたときに、区も一緒になって今も活動をしていますよね。変わらないんじゃないのかなというところが疑問なんですけれども、そこら辺のところはどうお考えか尋ねました。","respondent":"長田地域活動課長","answer":"今ご指摘をいただいた部分大変難しい問題だと思っています。これは、同じように時間がかかることかなというふうに、私ども末永い、息の長い発言をしていきたいというふうに思ってあります。","id":"exchange-067"},{"speaker":"石田副委員長","kind":"質問・要望","question":"この会は形式だけで出て、話だけ聞いてこようということで、意味のない会になってしまう可能性があると思うんです。そういうことのないようにやっていただきたいという要望も含めて、ご見解をちょっとお聞きしたいと思います。","respondent":"長田地域活動課長","answer":"というのは、ＰＴＡですとか、教育関係者とか、道路管理者が行っても、なかなかそこへ設置してあるものをはがして持ってこれない。これから委員の選定を行っていきますので、ご意見等々はその運営の中で生かせればと、こういうふうに思ってあります。","id":"exchange-068"},{"speaker":"菊地委員","kind":"質問","question":"先ほど、区民が区民を見張る体制というのが結果的には生まれてきてしまうのではないかというような考えを持っています。ですから、それを条例化するということについては反対いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"本田委員","kind":"質問","question":"先ほど懸念すべき問題点を質問をしました。品川区が定めた区民憲章の精神が日々の生活の中に生かされていくということであってほしいということを願って、この条例については、見守りながら。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"原委員","kind":"質問","question":"質問をさせていただいて、この条例を契機に皆さんで努力をしなければいけないという部分で、私は賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"金高委員","kind":"質問","question":"私どもも賛成することを表明いたします。３条それぞれ区の責務、この場においては総合調整の場でもって生活安全協議会をつくるということですから、賛成をします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"堺委員","kind":"質問・要望","question":"ややもすると、皆さんが先ほど言いましたご意見を踏まえて、くれぐれもそういうことがないように対応をしてほしいと求めました。基本的にはこの条例に賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"藤原委員","kind":"質問","question":"私自身も一般質問とかで区民に一番近い条例ですと、警察との関係がどのようになっていくんだという中で質問をさせていただきました。今回、警察署と緊密な連携を図るということで、本当に期待しておりますので賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"}]},{"id":"topic-03","title":"引き続き第７４号議案 品川区特別区税条例の一部を改正する条例","agenda":"引き続き第７４号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"本田委員","kind":"質問","question":"実際に品川区の住民税にどういう影響があるかというのは、それも正確にはわからないということですから、融資できなくなる。これはできるだけ控えるべきだし、また、そういう点はこの施策では区としてはどんなふうに捉えておりますか。","respondent":"松崎税務課長","answer":"2,０００円の住民税を品川区がもらうことになりますので、そういう意味では譲渡益の要因にもなる。特にこの制度について国からの補てんがあるとか、控除があるというものはございません。","id":"exchange-075"},{"speaker":"本田委員","kind":"質問","question":"そういう点では品川区も例外にもれず、財源の問題というのは大変厳しいわけです。どう自治体においても確保するかということをなお一層していかなければならないわけですから、改正につきましては、これは改正に伴う改正ですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"藤原委員","kind":"質問","question":"改正後に、６月中旬なんですけれども、シミュレーションをしたということなんですけれども、株ですから、上がるときもありますし、きのうみたいに下がってしまうと利益が出ませんので、どういう条件で地方拡散するのか。","respondent":"松崎税務課長","answer":"平成１３年度の１００万円以下で申告分離課税をされた方の数字をベースに、その方々の税金がすべてゼロになったとすれば、幾らかというのが一つ。その両方を合算して約７００万円から６５０万円の益になるのではないかというシミュレーションをしております。","id":"exchange-077"},{"speaker":"藤原委員","kind":"質問","question":"その財源というか、株が上下しますから、株の上下で、利益が出なければしようがないということか尋ねました。","respondent":"松崎税務課長","answer":"それらも考慮に入れるかどうかということのシミュレーションができない。その１００万円に対して1.０５税金がかかりますから、その1.０５をかけられる方が、申告の形態にも係わってまいります。","id":"exchange-078"},{"speaker":"原委員","kind":"意見","question":"私も当然地球温暖化に対してはいろいろな形で手を打っていくべきだろうと思うし、今後も厳しくしていかなければいけない問題だろうと思います。その辺のところを踏まえて、ちゃんとした形で委員会としてどうするかというのをみんなで勉強する必要があると思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"本田委員","kind":"提案","question":"しないかというような議論の中で、主要議決宣言までに提案を具体的にアメリカが出して、国際交渉に参加すべきだという決議を全会一致で採択をした。どういう文書にするかはお互いに意見を出し合って、ちょうどいい機会ですから、態度を明確にするというふうにしたいなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"原委員","kind":"意見","question":"それはそれなりの順序を踏んで、議会としての形をつくっていくべきだと思います。今日早急に採決しろとか何とかじゃなくて、その前にやるべきことがあるでしょうということなんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"菊地委員","kind":"意見","question":"ＣＯＰ３の話を出しておられましたけれども、中身を見ると、日本向けというのは大幅に取り入れた内容になっていますよね。意見を表明したいなと思いますけれども、僕自身、この請願については、採択したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"原委員","kind":"質問","question":"ですから、ですから、言っています。別に、これを色分けとか何とかという話でなくて、委員会としてはきちっとした形をつくるべきだろうということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"金高委員","kind":"質問・要望","question":"衆参両院において４月に政府に対して京都議定書を早期に率先して批准することを求める決議が全会一致で採択されているというのが出ておりまして。この請願でも地球温暖化防止策が出てくるわけですから、意見書として出すことも一つの方法だと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"本田委員","kind":"提案","question":"ですから、しかるべき対応をするというのは、そうだと思います。区民委員会の委員全員が案文の提案者となって、勉強会を１回持って入れて、私はここのところは硬直した考えは持っておりませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"原委員","kind":"質問","question":"報道されているもので満たされている内容でもって簡単に意見書を出して、こうしてくださいというのは済まないのではないかと言っているんです。特に大事な問題ですから、これから環境行政をどうしていくかという非常に大きな役割を持つ審議ですから、そういう意味では。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"堺委員","kind":"質問","question":"ですから、そういう方向でどうなのなかなと、そんな気がします。ですから、その間に、改めて我々も京都議定書の中身について勉強していく。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"原委員","kind":"確認","question":"ちょっと確認しておく都合がある。出した人に質問するべきなんでしょうけれども、抜本的な推進というのは、課長の考えではどういうものか分かりますか。","respondent":"金井環境課長","answer":"国の抜本的な政策をやるのはなかなか難しいんですが、ご案内のとおり、地球温暖化は現在の世界の化石燃料をほとんど使って、先進諸国が発展していく。１億2,０００万人の国民を支えながら発展をしながら、産業構造を変えていくとなりますと、抜本的というのは大変難しいかなと。","id":"exchange-088"},{"speaker":"原委員","kind":"意見","question":"それを政策を推進していくということになると、じゃ、この京都議定書の中身は何なのかということも絡んでくるわけです。そういうことを考えて、意見書はちょっと待ってほしいんだけど、その前にやることがあるんじゃないかなというのが、私の意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"本田委員","kind":"質問","question":"こういう請願が出たわけですから、先ほど堺委員のほうでおっしゃいましたけれども、マスコミなどでは報道されております。日本政府、品川区議会はしっかりやってほしいという意見を出しておくほうが、決議を出す方向で進めたらいかがかというふうに申し上げておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"原委員","kind":"質問・要望","question":"ただし、意見書の部分は勉強してからということで別にして、空にしておいていただきたい。順序を踏まえていただければ、別に意見書に反対しているわけでも何でもないわけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"},{"speaker":"本田委員","kind":"質問","question":"しかるべき経過、内容を正確に掌握をして行動をとると言っていることですから、それは構わない。勉強をして、やるというのは結構ですから、そういう形でやったらどうかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"},{"speaker":"原委員","kind":"意見","question":"それは別に、話し合ってやるべき問題。ただ、できれば、趣旨採択という形で出せれば結構の話だけれども、今の段階では私はそういうふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"本田委員","kind":"意見","question":"出すということを前提に趣旨採択すべきだという意見なんですけれども、原委員のほうは、そこのところは譲歩します。おのずと出てきますので、その辺は、今日できればこれを採択していったらいかがかなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"菊地委員","kind":"質問","question":"委員会運営で趣旨採択をしてから、勉強をしてから、趣旨採択をするとこういう経験がないものですから、そうなると、第４回定例会でという捉え方でいいんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"石田副委員長","kind":"質問","question":"ですから、アメリカはそのまま発言をしないかもしれませんし、もっとずっと上の段階で出してくるかもしれない。これは個人的な意見ですが、それは委員長とよく話し合いながら、私は趣旨には大賛成であります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"堺委員","kind":"質問","question":"国に対して意見書を出してくださいということですから、京都議定書の早期批准・発効、これについては一貫して現状とは変わっておりません。その辺で、取り扱いについては、趣旨採択で勉強もきちっとして、一日も早く内容をある程度理解する、そんなふうに私は考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、自動車業界はどういう対応をとっているのか、そういうものを提示をしていただきたいなというふうに思うんです。深い議論をして、いい意見書が出るようにしたいと思いますので、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"原委員","kind":"質問・要望","question":"資料をもらって、そのままというわけにいきませんので、その資料をもとにして若干の質疑の時間をとってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":74760,"voices":208}},{"id":"h13-20010925-7","meetingId":"h13-cm09","date":"2001年9月25日","dateIso":"2001-09-25","committee":"厚生委員会","time":"午前１０時０９分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"第７０号議案 平成１３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第７０号議案 平成１３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"メンテナンスの時期があって、予算の１年間の区切りの中では間に合わないから、いつも補正でやっているのかということ。そうでなければ、なぜそうなったかということを、もう少し具体的にお答えいただければありがたいんですがとの意見を述べました。","respondent":"野田口高齢事業課長","answer":"そういった意味で、先ほど説明が漏れましたけれども、１２ページの歳入ですけれども、１０分の１０の都の補助金といった事業です。昨年においても、そろそろ定期点検のときに買い替えの時期だということがございまして、南大井を優先的に整備するといったものです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、１８０万円余のお金が入って、これは新しく買い替えるという意識でよろしいのでしょうかということが一つ。いろいろなメンテナンスのところでやったのかという気がするんですけれども、二つの確認をお願いいただければありがたいんですが。","respondent":"野田口高齢事業課長","answer":"多分、記憶に違いがなければ、南大井についてはヘルストロンを替えていない、今回全く新しいものを買い替えるです。ただ、全く使えないというような状況ではなくて、百数十万円という高価なものですので、１７年経ってそろそろ買い替えの時期に来たというものです。","id":"exchange-002"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"その後も何回かありましたけれども、今、何施設に何台配備されていることになっているのか、分かればお聞かせいただきたいんです。約８,６００名の子どもが対象になるわけですけれども、大体当該世帯の何％ぐらいですか、そこがわかれば教えてほしいと求めました。","respondent":"野田口高齢事業課長、谷田部児童課長","answer":"ヘルストロンの配置ですけれども、シルバーセンターは１６カ所ありまして、１６カ所全部に配置しています。 新しい所得制限の基準でいたしますと、大体７０％の子どもが今回の緩和により対象になるです。従前は５４％程度です。","id":"exchange-003"},{"speaker":"鶴副委員長","kind":"質問","question":"では、南大井シルバーセンターには配置されていないから、これから配置するんじゃないですか。あるいは、今、伊藤委員がおっしゃっていたように、既に配置されていて、古くなったから取り替えるということなんですね、わかりました。","respondent":"野田口高齢事業課長","answer":"全く、そのとおりです。","id":"exchange-004"},{"speaker":"嶋委員","kind":"質問","question":"今回の３９戸４３人、１人居室が３５室、２人居室が４室という数はどういう形で決まったのか。数を見ますと３５室と、２人部屋のところも４室ということなんですが、この点でお聞きをしたいと思います。","respondent":"小野高齢者施設担当課長","answer":"「さくらハイツ南大井」につきましても３６人ということなんですけれども、大体三十五、六人程度がちょうどいいという形のものもあります。２人居室につきましては運営の面もありますので、少ない４室ということで、現在のところは計画しているものです。","id":"exchange-005"},{"speaker":"嶋委員","kind":"質問","question":"皆さんから「もっとたくさんつくってほしい」という声が聞かれると思います。金額的なものは、南大井と大体同じなのか、差があるのかお聞きしたいと思います。","respondent":"小野高齢者施設担当課長","answer":"「さくらハイツ西五反田」につきましては、現在のところ南大井と同じような金額設定で詳細を詰めているところです。","id":"exchange-006"},{"speaker":"鶴副委員長","kind":"質問","question":"その先のことを言ったら何が一体笑うのかなというふうに思うんですが、笑えないことに、要するにいやしという面からペットは飼えるんですか。安心の住まいも含めて、あるいは区民住宅は所管が違うからあれでしょうが、高齢者関係の福祉施設は動物は飼えるのか飼えないのかということです。","respondent":"小野高齢者施設担当課長","answer":"現在のところ、ペットは想定してございません。","id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"最近は生きた猫だけではなくて、ロボットの犬とか猫が声をかければ反応したりするような、そのぐらいまでが商品として開発されているぐらいですから。どうか検討するということですから、試みにそういうことを採用する方向をぜひ探っていただきたいと、こういうふうに要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"須藤委員","kind":"質問・要望","question":"何点かお伺いします。このカフェテリアもそういう考え方でお考えになった場合には、そのあたりのところも、そのあたりをお聞かせ願いたいと思います。","respondent":"小野高齢者施設担当課長","answer":"こちらとかなり連携を取った形での運営が必要になってまいりますので、具体的な運営にあたってのことについては、今後詰めていくです。貸付条件といったものもこれからですので、そういったものも固まった時点で中に入る方もあわせて今後決めていくということになります。","id":"exchange-009"},{"speaker":"須藤委員","kind":"質問","question":"逆に個室のほうで浴室は必要ないんじゃないですかという話に、本当に中に入る人たちのところが今までやった経験から生かされてきているのかなという点で、もう一度そのあたりのところをお聞かせ願いたいと思います。","respondent":"小野高齢者施設担当課長","answer":"シャワーだけでもいいのではないかということを検討しましたけれども、やはり自分が入りたいときにいつでも入れる浴室が居室の中についているということが、また入居者の条件の一つにもなっているのかなと考えております。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"先ほど言った、前と変えてレイアウト等はミサワホームに相談しましたと言うんだけれども、どういうところが変わってきているのかなと。それとも区側でこの辺はこうだよということを、あるいは入っている方からの声を聞いてというところで生かされたことはありませんか尋ねました。","respondent":"小野高齢者施設担当課長","answer":"ＬＤ、洋室の使い勝手とか、いろいろかなり細かい部分でのアンケートをいただいてあります。それから入居者のアンケートに基づいた形での台所の位置、物入れの位置なども検証しながら、設計を一緒になって進めてきたです。","id":"exchange-011"},{"speaker":"嶋委員","kind":"意見","question":"クリニックなんですが、近隣の方も利用できるクリニックなのかどうかをまず１点との意見を述べました。","respondent":"小野高齢者施設担当課長","answer":"こちらは５００戸のファミリー向けの住宅がありますので、もちろんそちらも視野に入れて、一般の方はどなたでもご利用できるクリニックという位置づけで設置いたします。","id":"exchange-012"},{"speaker":"嶋委員","kind":"意見","question":"クリニック専用の駐車場が１台となっているんですが、近くの方はご利用されるのではないかと思いますが、その場合にクリニック専用の駐車場が１台というのは少ないのかなと考えていますとの意見を述べました。","respondent":"小野高齢者施設担当課長","answer":"ここのクリニックは近隣ということを想定していますので、車に乗って利用ということは想定してございませんので、特にこちらのための駐車場は用意してございません。","id":"exchange-013"},{"speaker":"嶋委員","kind":"質問","question":"高齢者の方が利用されるとなりますと、やはり車で移動することが多くなると思うんですが、その辺は考えをなさらなかったのかどうかということ。外部からの訪問者、そういう場合の外部からの駐車場管理のスペースは、今回どのぐらいお持ちになったのかお聞きしたいと思います。","respondent":"小野高齢者施設担当課長","answer":"駐車場につきましては、１ページにありますように高齢者用について６台、区民住宅については３０台、地域センター用として３台、その他店舗、クリニック等として３台、合わせて４２台ということで設置しています。","id":"exchange-014"},{"speaker":"嶋委員","kind":"質問","question":"ということは、無料ということで理解をしてよろしいのか尋ねました。","respondent":"小野高齢者施設担当課長","answer":"店舗等の駐車場は特に有料ということではございません、それほど多い台数を用意してございませんので。","id":"exchange-015"},{"speaker":"嶋委員","kind":"質問","question":"南大井の場合は、前が通りで１時間３００円で駐車して、中の方に会いに行ったりできるんですが、やはり家族に会いに車で行く方があります。「安心の住まい」の友達に会いに行ったりする場合の確保のことで。","respondent":"小野高齢者施設担当課長","answer":"福祉施設のほうは６台の駐車場を用意していますので、そちらが空いていればご利用いただくことはできるかと思いますけれども、特にそのため用には用意してございません。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアホーム西五反田についてお聞きしたいんですけれども、職員体制がどういう体制になるのかということを１点お聞きしたいと思います。５ページにスタッフルームがありますけれども、休憩室ですとか仮眠室というところはどう考えているのかということを一つお聞きしたいと思います。","respondent":"小野高齢者施設担当課長","answer":"もちろん２４時間体制ですので、ここのスタッフルームにいるということは通常ないというふうに考えております。重度と軽度ですけれども、重介護の方につきましては要介護３から５ぐらい、軽度の場合は要介護１から２ぐらいを想定しております。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"職員体制は２対１ということですと、大体４０名ぐらいが職員になるということでいいのでしょうか。それから、軽度は要支援から要介護２から３ぐらいまで、重度が要介護３から５ぐらいまでということで考えていいのか尋ねました。","respondent":"小野高齢者施設担当課長","answer":"入居者の選考につきましては、今後まだ２年ありますので、もう少しゆっくり詰めていくです。今のところ、まだ決めてございません。","id":"exchange-018"},{"speaker":"鶴副委員長","kind":"質問","question":"自分が在宅復帰が可能かどうかを試すために最高６日間ぐらいですか、要するに訪問系のサービスが受けられない、全額自己負担だと。その在宅復帰を促進することについて、そこを中心に質問をしたわけですから、何となく釈然としなかった。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"鶴副委員長","kind":"質問","question":"その後の決算特別委員会もあることですから、決算特別委員会の款別審査の中でフィードバックしてお尋ねするようにいたしましょう。答弁書をいろいろつくった関係も、含めて自分が答えたんだということですから、ほかの点は自分の所管じゃないというふうにおっしゃらないですね。","respondent":"小沼福祉事業部長","answer":"結構だと思います。ただ、今ございましたように、私のほうからも今日のやり取りについては所管の部長に伝えしますので。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/723274?Template=document&Id=2998#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":16861,"voices":62}},{"id":"h13-20010925-8","meetingId":"h13-cm09","date":"2001年9月25日","dateIso":"2001-09-25","committee":"建設委員会","time":"午前１０時０７分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"早速ですが、予定の２、議案審査(1)、第７０号議案、平成１３年度品川区一般会計補正予算（歳出：建設委員会所管分）","agenda":"早速ですが、予定の２、議案審査(1)、第７０号議案、平成１３年度品川区一般会計補正予算（歳出：建設委員会所管分）","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"密集住宅のことでお聞きしたいんですけれども、もう一度そこを教えてほしいのと、そこらを説明いただければありがたいです。","respondent":"浜脇住環境整備課長","answer":"共同化を促進するために特に１、２、３については早く用地を買うということになってあります。それから、今のところ、共同化に参加するのは７世帯といいますか、７権利者がこの共同化のほうに入るというふうになってあります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"１、２、３と。そのときの助成なりあるいは税制面の優遇なりというのは、もしありましたらちょっと教えてほしいんですが。","respondent":"浜脇住環境整備課長","answer":"ですから、土地で私どものほうに１件、例えば５,０００万円かかれば、税金はそれだけ引きますから、ゼロに対して税金を払う。１億なら５,０００万円に対して税金を払う、こういうような仕組みになってあります。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"１１戸プラス１戸をやっているんですけれども、それはこれの関係とは何かあるんでしょうか。今度あったものですから、ずれちゃうのですが、関連があるので教えてもらえるとありがたいです。","respondent":"田村住宅課長","answer":"２８戸残るので、２８戸のうちの一部、東京都の事業用として東京都が確保していくという形で現在考えております。３７を食っていますので、８７戸のうちの３７戸はもう区として使うという形になっておりますので、その残りの公募という形で対応しております。","id":"exchange-003"},{"speaker":"上山委員","kind":"質問・要望","question":"二確認だけなんですが、それは住民の皆さんの要望を聞かれてやったことに関しては評価するんですけれども、そこのところをちょっと教えていただければなと思うんですが。","respondent":"田村住宅課長","answer":"やはり、町会長、２５階建てについてはやはり賛成はしていないけれども仕方ないだろうというような考え方を持っていると聞いております。この間の４月の本委員会を受けて、構造、なるだけ住民の方に沿えるような形にしたいというようなことで答申をした図面のとおりになったです。","id":"exchange-004"},{"speaker":"上山委員","kind":"質問・要望","question":"要望だけなんですが、ぜひ、ほぼこういう形でいくと思うんですが、いろいろまた今後、今ちょうど建設中ですので、相談があれば、ぜひよく相談にのっていただいて、丁寧な対応をしていただきたいなと考えていますので、今後とも。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"築舘委員","kind":"意見","question":"この駐車場が４６台から４０台になったということなんですけれども、その辺のことはどういうふうに考えていらっしゃるのかということと、もし考えていらしたらお答えほしいと求めました。","respondent":"田村住宅課長","answer":"そういう意味からすれば、４０台確保しておけばですね、一定の対応は可能かというふうに考えております。先ほどご説明しましたように、そういう意味からすれば、構造上は緑地を比較的多く設けて風害等の対応を図っていくという計画をしております。","id":"exchange-006"}]},{"id":"topic-02","title":"の第８３号議案、東品川四丁目地内特別区道路線の認定","agenda":"の第８３号議案、東品川四丁目地内特別区道路線の認定","exchanges":[{"speaker":"築舘委員","kind":"質問","question":"これは、道路ができますと歩道のところに自転車も通れるようになると思うんですが、それに伴っての駐輪場と、あとは駐車場はどの辺にできるような予定になっているのか尋ねました。","respondent":"岩田管理工事課長","answer":"この図面の、ちょうどこの白抜きになっている四角いところが、これが第１期事業で道路区域に入れました交通広場の予定地です。全体の商業施設がかなり大きなものが予定されておりまして、このジャスコが入る予定の大規模商業施設には約１,０００台の駐車場、日。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"この区道用地はＪＴの部分なんですか。アメリカが株も８,０００ドルをちょっと割るか割らないかという世界同時株安、募集をする、その辺は区としてはどう見ているんか尋ねました。","respondent":"岩田管理工事課長","answer":"ここにダイエー本社を持ってくる予定だったそうですけれども、ダイエー内部の事情から、本社ビルの移転について撤退をしたと。今のところ、先ほど現場のほうでも説明がありましたけれども、大体買い手については目星がついた上でやっているものというふうに考えております。","id":"exchange-008"}]},{"id":"topic-03","title":"の３、請願・陳情審査に移ります。 (1)の陳情第２０号、仮稱洗足コーポラティブハウス新築工事にかかる陳情","agenda":"の３、請願・陳情審査に移ります。 (1)の陳情第２０号、仮稱洗足コーポラティブハウス新築工事にかかる陳情","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"例えばこの間の説明会だとか、主な出されたのは先ほども伺いましたけれども、それとの関係で何かわかっているのでしょうか。ここのところで苦労しているというのがもしあれば、ちょっと伺えれば教えてほしいと求めましたが。","respondent":"伊佐都市計画課長、浜脇住環境整備課長","answer":"その考え方として、いずれにしても、昭和３８年の時代から商業地域という指定になっています。それ以降、３０年以上にわたって用途地域としてはこういう指定になっているというものです。 １３人の方々にお伺いしながらやるというようなことで、第１回の説明会や第３回の説明会では、建築主はだれなんですかというような説明があって。結局、その辺でどうも建築主の本当の意味での自分たちと建築主とのやりとりがないと…","id":"exchange-009"},{"speaker":"上山委員","kind":"質問","question":"余り多くなかったような感じなんですけれども、こういう方式は今少し増えているのでしょうか。６階建てを７階分みたいな感じに思うのかもしれませんし、お願いしたいなと思うんですが、どうでしょう。","respondent":"浜脇住環境整備課長","answer":"やっぱりここには光が足らないんじゃないですかというような、利用しちゃいかんでしょうというようなケースが増えているのは事実です。そういったことで、住民から見れば、まさに高じて７階建てあるいは８階建てというふうに映るという、そういうのは事実です。","id":"exchange-010"},{"speaker":"築舘委員","kind":"質問","question":"この地図を見ていますと、地下１階から６階まで、部屋は２０戸ぐらいしかないんじゃないかと思うんだけれども、これは２７戸ですか、これは共同住宅。そうすると２５名がもう決まっているのかなという感じがするんですけれども、その辺の、今の現状のぐあいはどうなっているのかということを。","respondent":"浜脇住環境整備課長","answer":"私が勘定したんですけれども、いつもお話するときに２７戸、２７戸というふうにお住まいの方は言ってきますので。犬とか飼っているらしくて、それで権利者の数としては１３で、お住まいの方はもうちょっと増えてくるというふうに聞いてあります。","id":"exchange-011"},{"speaker":"築舘委員","kind":"質問","question":"住民の方からすれば、本当に聞く耳を持たないというか、無視されているという感じがすると思うんですね。もうそういう６階はだれだれが住むよというようなみたいになっちゃうと、これはどうなんですかね、こういうケースというのはほかにもあるんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"私の考え方では、住民側から言わせればＮＨＫまで出て、コーディネートターをやっている方は説明しておったというようなことを伺っております。住民から見れば、先ほどから申しましたように、建築主としての顔が見えないというふうに判断するお気持ちがあるようです。","id":"exchange-012"},{"speaker":"菅家委員","kind":"意見","question":"４階が建っているのに３階にしてくれというのも主張がおかしいし、南側の、これは事務所ビルだか何かありますね。道路の反対側との意見を述べました。","respondent":"浜脇住環境整備課長","answer":"この代表の方は町会長ですので、地区を代表しているですので、ちょっと隣接されている方たちを代表しているというふうに伺っております。","id":"exchange-013"},{"speaker":"菅家委員","kind":"質問","question":"何か聞くところによると、このコーポラティブハウスというんですか、こういう制度が最近何かはやってきているという話ですよね。ですから、全体の了解をもう一回振り出しからやり直ししなきゃいかんということで、非常に建主側がガードがかたいんだろうと思うんですね。","respondent":"浜脇住環境整備課長","answer":"当然にやっておりますので、若干何かを出せば建築基準法確認後に割っているということで、当然区画は合法だというふうに思われます。区のほうで６階建て以下にしろと、民民と言いますか、住民同士でお話し合いをしていただくのが一番かなというのが私どもの気持ちです。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"そこから両側に２０ｍですか。それぞれ分けて円満解決のために双方が努力するというのが基本ですから、皆さんと一緒に町内で住む、町会員にもなるわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"辻委員","kind":"質問","question":"ちょっとお伺いしますけれども、ここで言うと何か出てきているんですか、これは。設計者でもないんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"これが今言った設計者の方がコーディネーター役をやっている。都市デザインシステム一級建築士事務所というところがそれです。","id":"exchange-016"},{"speaker":"辻委員","kind":"確認","question":"これはあくまでそれだけの契約をもってやっているわけですから、この菊入さんという人ですか、これは幾らなじみになってもいなくなっていく。丸がついて、ここが変わりましたよという、１１ページ以降の関係、ちょっとこれを確認したい。","respondent":"浜脇住環境整備課長","answer":"じゃあ１３名集まってきたからといって、そういった地元の方々が要求する答えが出るかというと、この辺が非常に難しい面だなというふうに思います。それから、これは９月１４日に私どもで建築紛争に係るあっせんということで…","id":"exchange-017"},{"speaker":"辻委員","kind":"確認","question":"ですから、それをどう評価して、それをまたどうなんだということをやっていかなきゃいけないと思います。要するにどうこうなくても、そういう形でいいのかどうか、ちょっと確認を。","respondent":"田平建築課長","answer":"これでは問題がありますので、右のように変更されているです。左の絵は、お示ししたものの間違いであったと、こういう意味です。","id":"exchange-018"},{"speaker":"辻委員","kind":"意見","question":"いずれにしても、この私どもの理解、扱いとしては、陳情の基準は拝聴しました。どう住民の方が理解し、どうなんだということの、見守りたいなということだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"すみません、２度にわたって申しわけないんですけれども、今まではどうなんですか。何名かでも出たことはあるんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"３回説明会がありまして、その間の２回、５月２４日に建築主が出ていますが、この代表の方、岩上さんという方と、もう一人出ています。この１３名のうちのもう１名。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"できたらぜひ、大変かもしれないけれども、その努力を一度やっていただけないでしょうか。要望でいいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-04","title":"平成１３年請願第５号、住友不動産による「仮称大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","agenda":"平成１３年請願第５号、住友不動産による「仮称大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"階数以外にもし変更などを住友不動産側ですか、都の審査会ですか、何か主にはこういうところがあれば教えていただきたいということ。あるいは今どういう状況になっているか、わかればお願いしたいと、まずちょっと二つ最初にお願いしたいんですが。","respondent":"浜脇住環境整備課長","answer":"高さを９８.６３ｍにしましたということで、図面はいただいておりませんので、これ以上どういうふうな変更があったということはわかっておりません。健康上あるだろうから、当然とるという、とるというか搬出をするということで対応をしたいということです。","id":"exchange-022"},{"speaker":"上山委員","kind":"確認","question":"３日ですか、今後のいわば建築確認というんですか、今後の。審査会でこういうふうになったらどうなるか、あるいはそこのところをちょっとお願いします。","respondent":"浜脇住環境整備課長","answer":"地元との話し合いを今後とも進めなさいと、変えられた計画概要を説明しなさいと、その辺かと思います。総合設計にはまだ許可がおりていませんけれども、許可がおりたらば、それを確認なさったというふうに思われています。","id":"exchange-023"},{"speaker":"辻委員","kind":"質問","question":"このこれは、１００ｍを超えていたら、環境アセスのほうに引っかかっていくんだよね。この１００ｍという話は非常に外してしまったという、どういう意味合いからそれを下げたのか、わからないんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"ですから、これは前回の資料ですと、１００ｍの３万２,１１８ですから、環境アセスメントなどは要らないんじゃないかと。風の問題とか、質問のあったものについてはこたえていくという意味で、この土壌汚染についても調査をされたのではないでしょうか。","id":"exchange-024"},{"speaker":"辻委員","kind":"質問","question":"どっちにしたって、山手通り広げるときに拡幅に引っかかってくるわけですから、建築主の方で土のほうは全部処理を責任をもってやるということですか。これは都なんですか、品川区がやるんですか、その辺はどこがやっているんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"やはり今はこういう時世ですから、ちゃんとした処理業者、あるいは処理地をしっかりとやるというふうに住友は言っておりました。それから、監督は住友不動産が監督をするものと私どもは認識しております。","id":"exchange-025"},{"speaker":"辻委員","kind":"質問・要望","question":"きちっと環境局に電話して、それについては区のほうとしても確認をとってありますというような形をきちっとぜひお願いしたい。これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"先ほど建築審査会はまだおりていないということだったんですが、今後のめどとしてはどうなんですか。そこらはいかがか尋ねました。","respondent":"浜脇住環境整備課長","answer":"建築審査会としては、９月３日で一応終わってですね。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"この４項目の条例制定のことで、区のほうはこたえられるのかどうかわからないのですけれども、この同意書取得の義務づけというのがありますよね。その４項の説明会の有償開催制度の制定というのはどういうことなんか尋ねました。","respondent":"浜脇住環境整備課長、田平建築課長","answer":"２点目の件なんですけれども、想像ですけれども、どうも説明会に来るには時間と足がかかるから、何らかのものが出たらいいなというふうに読める。想像です。 １点目の同意書取得の義務づけというのは、説明会の義務づけ、あるいは開催の問題を言っているのか。正解は、直接やはり請願者なりご本人に聞いてみないとわからないですけれども、以上です。","id":"exchange-028"},{"speaker":"沢田委員","kind":"確認","question":"合意書を確認申請の提出を義務づけるみたいな動きがあったけれども、東京じゅうの建物はほとんどのものが建たなくなっちゃう。それは条例化するというのはかなり無理だし、現実不可能なんじゃないかなというふうに、私はこの４項目については思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"菅家委員","kind":"意見","question":"さっき建築課長が説明してくれたけれども、やっぱりそのまま受け入れるということは、条例の性格上、私は無理があると思うんです。ちょっとその請願については受け入れがたい内容であるというふうに思うので、態度表明ということになると、不採択ではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"菅家委員","kind":"提案","question":"委員長のこれからのお計らいの中で、また議論させてもらいます。４項目という限られた提案だったから、そういう表明をしただけでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"辻委員","kind":"質問","question":"それはもちろんこの物件については、まだまさしく今建築の話し合いが行われてきているわけですから、継続していく。３については、土壌の問題もあるわけですから、基本的には建築請願として継続扱いにしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"沢田委員","kind":"意見","question":"結論から言うと、この請願は継続ということで、あえて４をどうかと言えば、これは問題があると言わざるを得ない。そういう思いがあってもとの意見を述べました。","respondent":"佐藤委員長","answer":"いずれ４項目も本日は継続という取り扱いをさせていただきまして、請願全体をまた改めて、取り扱いも含めて検討するということでよろしいでしょうか。〔「はい」と呼ぶ者あり〕","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/428096?Template=document&Id=3700#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":38583,"voices":115}},{"id":"h13-20010925-9","meetingId":"h13-cm09","date":"2001年9月25日","dateIso":"2001-09-25","committee":"文教委員会","time":"午前１０時３分～午前１１時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"議案審査に入りたいと思います。 第７０号議案、平成１３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"議案審査に入りたいと思います。 第７０号議案、平成１３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"山路委員","kind":"質問","question":"１点目の心の教室相談員なんですけど、教員の免許を持っていて仕事がないといいますか、なかなか職につけない方がたくさんいらっしゃるんですね。これは都の委託金ですけど、そういうものを、区のほうでも、心の相談員という形でもう少し拡大するというのはどうなんか尋ねました。","respondent":"青木指導課長","answer":"まさに生活面での対応ということで、こちらは１１校で、中学校全校にこういう形で入っております。小学校のほうは、担任や養護教諭ということで、子どもの悩みや相談を受けておりますけど、現時点では、この体制で進めていきたいと考えております。","id":"exchange-001"},{"speaker":"山路委員","kind":"質問","question":"全国の動きをみますと、不登校生の家庭のほうにお伺いして友達になる、地方自治体独自の補助教諭が潤滑油的な働きをしているということも聞くんです。将来的には、そういうような展開も考えられるんじゃないかと思うんですけど、その辺についてはどういうお考えか尋ねました。","respondent":"青木指導課長","answer":"そうした形での相談員というのは考えておりませんけれども、心の教室相談員の採用に当たっても、いろいろな方にお声をかけしています。そういうところでの活用というのは、このシステムの中で、しばらく対応していきたいと考えているところです。","id":"exchange-002"},{"speaker":"山路委員","kind":"意見","question":"その辺を開く役が、地方自治体のこういう心の相談員云々と言われるような方になってくるんじゃないかと思うんです。もう少し柔軟に、横割りとか、将来的な展開として考えられないかということを言っているんですけどとの意見を述べました。","respondent":"青木指導課長","answer":"この中にも、教員になろうというような人たちが指導員として働いておりますし、心理士の資格を持った方もそこにいます。マイスクール八潮、そして、それぞれの学校等の中で柔軟に人材を活用していきたいと考えております。","id":"exchange-003"},{"speaker":"山路委員","kind":"意見","question":"今、最後に言われましたが、総体的にとらえなきゃいけないでしょうと思うんですけど、実際の成果として、不登校生徒が復帰できたというようなパターンがどれぐらいあるのか、ひとつ説明を求めました。","respondent":"青木指導課長","answer":"そういう意味で、そういう対応の効果として、不登校生徒が減ってきた、学校に戻れた、進路が決まったというような事例は幾つも届いておるところです。やはり、そうした教育相談的なそれぞれの効果というものが出ていることは確かです。","id":"exchange-004"},{"speaker":"山路委員","kind":"質問","question":"ちょっとお聞きしますけど、今年の３月の予算特別委員会のときにお聞きしたんですけど、もう一つ相談が受けにくいという方もいらっしゃるんですよね。その辺の整備はしていただいたのか。","respondent":"青木指導課長、指田教育次長","answer":"教育センターの相談センターのセクションでそれぞれの不登校問題などにも対応いたしますけれども、今、不登校問題については相談を受けております。相談学級でも、対応できるような形になってありますので… 八潮の相談体制なんですけども、なるべく相談が受けやすいような形ということで、今年度、相談コーナーみたいに仕切りを入れまして、ハード的には相談に乗りやすい形の対応をとらせていただいたという話がございました。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"４月現在が把握しやすいんでしょうか、とりあえず３０人児童となっていますから、それから男女別に教えてほしいと求めました。これは１９９３年度ですから、この件について何かつかんでいる情報があれば、参考までに知りたいと思います。","respondent":"青木指導課長","answer":"昨年までは２年間継続での研究ということで、適応指導教室でのそれぞれの子どもへの対応というんですか、報告をしているです。そして、どのように変動していくのかというようなことについて、文部科学省のほうに報告をしていくという形での委託研究です。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"週８時間というと、４日間と考えていいんでしょうか。あるいは、親御さんとの関係はどうなのか、少し概要を教えていただきたいというのは、そういう意味で申し上げたところです。","respondent":"青木指導課長","answer":"ちょっと、委員へのお答えになってないかと思うんですけど。もう１回、ご質問をいただければ。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問・要望","question":"２年目と言っていますけど、もうかれこれ１０年近くやっているような気がするんですけども、見直しの段階に至ってないんでしょうか。この学校にとらわれないというか、全体に人権尊重というのは進めていかなきゃいけないと思うんですけども、そのあたりの現実ってどうなんか尋ねました。","respondent":"青木指導課長","answer":"それから２年目についても、都のほうの委託を受ける時期がずれているという形になるかと思うんです。そういうような総合的な意味での、人権尊重教育を、現在、推進しています。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問","question":"これで終わりますけど、具体的に、何をこの２校でやっているんですか。１０年経っても、まだ引き続いてやるつもりなんですかね。","respondent":"青木指導課長","answer":"総合的な学習で人権を取り扱うとか、そうしたことを通して、人権尊重教育推進に取り組んでいるです。もちろんどこの学校でもやっておりますけれども、さらにそこに重点的に取り組んでいるという状況であることをご理解いただければと思います。","id":"exchange-009"},{"speaker":"桜井委員","kind":"意見","question":"別の意味でかぶせているのかどうかわかりませんけども、改めて特別な位置づけというのは見直すべきだと、率直に思います。ただ、全体的には、この予算の点については賛意を示しますけども、意見として述べておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"川西委員","kind":"質問","question":"人権尊重教育の予算の使途を、ちょっと教えてください。それからもう一つは、守秘義務というのは、そういう方々にちゃんと指導なさっているのかどうか、伺いたい。","respondent":"青木指導課長","answer":"３点についてお答えいたします。心の教室相談員として守るべきことなどについても、ここで研修をしていただいております。","id":"exchange-011"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、そういう点ではいいことだと思いますが、なぜ城南中学校、台場小学校だけで、記憶では２０年を超している。ですから、女性の方で、こういう方がいるのかどうか伺っておきたい。","respondent":"青木指導課長","answer":"今後も、子どもたちの相談に乗れるような機会を増やしていけるように、工夫していきたいと思います。フリーダイヤルというのもありますので、そういう形で、子どもが相談できるような場も工夫していきたいと思っています。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"７校で文部科学省と東京都の教育委員会がやっているスクールカウンセラーを置いて、心の教室相談員を置いているという形でいいんですよね。そうしますと、スクールカウンセラーも心の教室相談員も、仕事内容は同じと考えてよろしいんか尋ねました。","respondent":"青木指導課長","answer":"先生方に対する研修会の指導を受け持ったり、大人の方たちの相談を受けたり、若干幅のある活動をしていると考えていただければと思います。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"事業展開としては、先行き、すべて１８校にスクールカウンセラーを委託事業として拡大していくという方向性が見えているんですか。その辺をちょっと説明を求めました。","respondent":"青木指導課長","answer":"そういう方向で、今、文部科学省は取り組んでおりますので、全校配置になるような方向です。","id":"exchange-014"},{"speaker":"高星委員","kind":"質問","question":"その中で、子どもたちと生に接する現場の先生方なんですから、この辺は結構シビアな部分もあるんだろうと思います。その辺を今どういうふうにやられていて、どういうふうに進められていくのかということを、ちょっとお聞きしたいなと思います。","respondent":"青木指導課長","answer":"２点目ですが、教員で、精神的な状況で休んでいる方ということでしょうか。ほんとうに数名ですけれども、やはり自律神経失調ということとか、鬱病状態というような方が数名いらっしゃるという状況です。","id":"exchange-015"},{"speaker":"高星委員","kind":"意見","question":"そういう中で、やっぱり先生にしわ寄せがいってないのか、どうしてもやっぱり気になってくるところもあるんです。その辺のところをどのように行われているのか、十分に措置されているのかどうなのか、そこだけ聞いて終わりたいと思いますとの意見を述べました。","respondent":"青木指導課長","answer":"それから、指導助手というような状況もあります。都からのそういうような過配教員や指導助手などを活用して、今、さらに教育の向上を進め、やれるようにしていきたいと考えております。","id":"exchange-016"},{"speaker":"高星委員","kind":"意見","question":"１点だけ言わせてもらえますか。だから、その辺は、基本的に、僕も先ほど最後に言ったように、大きな中で幅広くやっぱり大切に見ていってもらたいということだけ言っておきますとの意見を述べました。","respondent":"青木指導課長","answer":"先ほど、特殊な事情というのがちょっと誤解されたかなと思うんですけど、例えば他区から来られたときに、もう既にそうした持病がおありだったとか、そういうような事情でという意味合いで使わせていただきました。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ちょっと、基本的な問題で聞いてしまおうと思うんですけど、心の教室相談員関係の相談員と学校の先生の連携というのは、どういう形になっているのか。そこら辺を、ちょっと教えていただけますか。","respondent":"青木指導課長","answer":"教員のほうから、「その後、○○君はどうですか」というようなやり取りも当然あります。そうした連携をとって進めていきたいと、今後ともそうした環境をつくっていきたいと考えています。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどの質問ともちょっと絡んでくるかと思うんですが、先生としては、受けてもらいたいと思う生徒もいますよね。だけど現実には、そのギャップとしてはどのぐらいの人数が出るかというのは、つかんでますか。","respondent":"青木指導課長","answer":"一人ひとりの子どもが自発的に相談に行くような体制の中で、今、相談業務が進められていると考えていただければと思います。もちろん、そうした教員の指導性も必要なときもありますけれども、子どもたちが自発的に相談に行っているという状況が多うあります。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"やはり、かなり反発の強い子というんですか、そういう子というのは、実際にはあまり相談されていないという状況かなと、ちょっとその辺が気になったんです。","respondent":"青木指導課長","answer":"中学生時代に、そうしたお子さんの理解に努める、そうした傾向のお子さんが相談に行くという場面が多く見られたという報告も受けております。教員に反発するから相談員にも反発するというようなことだけではないと聞いております。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１点だけ。そういった意味では、どのような教則本というか、資料を使っているのか教えていただきたいんですけど。","respondent":"青木指導課長","answer":"それぞれの教育活動の中で、教科書を通して教える場面もありますし、また、学校が手作りの教材で示すこともあります。一定の教則本というものを持って指導に当たっているということではございません。","id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問","question":"先ほどのお話だと、２０年ぐらい続いているということでは、かなりその間の蓄積というか、また、工夫もあると思うんです。そういったものが活用されているのか、また、そういう資料はどこに行ったら見せていただけるのか、ちょっと説明を求めました。","respondent":"青木指導課長","answer":"この２校につきましては、長い時間をかけて、人権尊重教育という実践を積み重ねてきております。それぞれの学校で、今まで実践してきた内容については、それぞれの学校に資料があります。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ぜひ、それぞれの学校の資料を見せてほしいと求めましたし、また、知らない方もいらっしゃると思うんで、ぜひ、活用の方向を示してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"高星委員","kind":"意見","question":"過失割合が、こっちが２だと、それはいいんだけど、これを直すときにいわゆる区のお金が出されるわけでしょ。そういうのがあるんじゃないかと思うんですけど、その辺のことはどうなっているのか、ちょっと聞きたいとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"いわゆる金額的には、保険に入っていますから、本人に負担はないわけですけども、ただ、本人に不利益な部分があるかないか。そこら辺は十分留意して仕事に励んでほしいなと、日々、指導しています。","id":"exchange-024"},{"speaker":"桜井委員","kind":"質問","question":"全く違う次元での話ですから、先ほど申し上げた、判断というんでしょうか。その辺は、どういうふうになっているんか尋ねました。","respondent":"鷹倉庶務課長","answer":"説明会をやったときに、要するに、何らかの運用の基準を示していただけないかという話をしているわけです。学校として対応していただきたいということを言っておりますけれども、それからもう１カ所、これから決めていくわけですけども。","id":"exchange-025"},{"speaker":"桜井委員","kind":"質問","question":"そういう点では、学校の安全管理ということについて、学校での合意というんでしょうか、そういうものもできつつあると思うんですよ。その辺について、もうちょっとお考えを説明を求めました。","respondent":"鷹倉庶務課長","answer":"学校１１０番をどういう形で、こちらからお答えしますし、警視庁のほうに問い合わせた上でお答えできます。今のところは、そういう形で、学校にやっていただければいいのかなと考えています。","id":"exchange-026"},{"speaker":"桜井委員","kind":"意見","question":"先ほど来からあるように、それぞれ生徒の複雑な心理、状況というのがありますよね。だから、希望とすれば、特段中学校の場合は、やっぱり慎重に対応をされたいし、私たちも、ちょっと注意深く見守っていきたいと思っているところですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"山路委員","kind":"質問","question":"例えば、運動場で事件が起きても、部屋から見た人が、押すための会話をやっているとか、そういうものは技術的に可能なんでしょうか。非常にいい分析になってくるんじゃないかと思うんですけども、その辺の技術的なことと、現場的なことはどうなんか尋ねました。","respondent":"鷹倉庶務課長","answer":"逆信の電話が来たときに、相手は司令部ですけども、そこで、相手とこちらと話をしたことは全部録音されると十分考えられます。そういうもので、事故の今後の真相解明というものをやっていかれるのではないかと、そのように考えます。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問・要望","question":"押したら、例えばボックスがありまして、ボックスを開いたら、押す前の状況の会話を録音できるとか、そういう前後の状況を。犯行を次回に起こさないための徹底した現場での事実を残すということで、そういうものがあったら、研究していただきたいと思うんですけど。","respondent":"鷹倉庶務課長","answer":"こちらからボタンを押して、向こうから逆信で通話が来る。ここから初めて相手との連絡が取れますので、その前の段階というのは、ちょっと難しいんじゃないかなと考えられます。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、いざというときに、先生たちの中に相当な意識を持ってないと、これを実際に使えるかどうかというのは、疑問をちょっと感じます。ですから、２カ所にあっても、片方は全然わからないわけですよね。","respondent":"青木指導課長","answer":"子どもたちへの指導の中での理由ということでございましょうか。恐怖感というものをケアするような努力は、現在、しております。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、ご説明したと思うんですけど、そのことに対して、区としてどういう体制をとるか、いざというときのための体制づくりみたいな、そこまでは、直接かかわっている学校に判断をゆだねているということか尋ねました。","respondent":"青木指導課長","answer":"学校対策の安全委員会というものをそれぞれの学校に設置しまして、どこに逃げ込んでほしいかというようなことも含めまして、やってあります。パトロールの問題、それから受付けの問題、それから、戸締りの問題等も含めまして、それぞれの学校で対策を講じているところです。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"意見","question":"安全管理の点はわかるんですけど、起きてほしくないけど、万が一起きてしまったときに、どう考えるか。危機管理的な面ですけど、その辺、何か特別な体制というのはあるのかなとの意見を述べました。","respondent":"青木指導課長","answer":"そういうことも、今回の事件に際して、もう一度確認をしているということであります。万が一起きてしまったことを想定してのマニュアルの確認というのは、それぞれの学校でやっているかと考えています。","id":"exchange-032"},{"speaker":"川西委員","kind":"意見","question":"ちょっと、総務委員会みたいになっちゃうけど、特命業者というのは、どういうふうに報告を受けていますかとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"財団法人の電気通信共済会というような業者と聞いてあります。","id":"exchange-033"},{"speaker":"川西委員","kind":"意見","question":"なぜ特命かという、事の性質上、特命でなければいけないという報告、そういうことです。だから、業者がどうのこうのというんじゃなくてとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"財団法人電気通信共済会というのは、この基金を持っているだけじゃなくて、メンテの関係にもかかわってくる業者だと聞いてあります。東京都が警視庁と、きちっと調整できるという今後の必要性からも、今までやっている財団法人電気通信共済会が請け負うという形と聞いてあります。","id":"exchange-034"},{"speaker":"山路委員","kind":"質問・要望","question":"そういう面でも、派手さはありませんけど、非常に重要な事業じゃないかと感じています。区民周知というのはどういう形で、広報とかやられるんでしょうけど、そこをちょっと教えていただきたい。","respondent":"南生涯学習課長","answer":"広報紙等でのＰＲもしてまいりますけれど、雑誌などは編集の関係がございまして、既に原稿を送ったりしています。そういうことでは、できるだけさまざまな手段を用いて、ＰＲをしていきたいと思っているところです。","id":"exchange-035"},{"speaker":"山路委員","kind":"質問","question":"自由見学とかはないんでしょうか。団体としては、予約するとか、そういう形もできるということなんか尋ねました。","respondent":"南生涯学習課長","answer":"歴史館をたびたび訪れていただいておりますが、せんだって歴史館をご視察いただいたときに、ご説明申し上げたあの部屋で展示いたします。歴史館のほうで柔軟な対応をして、３班なりに分けるとか、うまく工夫をしながら団体の受け入れは可能かと考えています。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問・要望","question":"品川区民の方はもちろん、区民以外の方にも数多く見ていただいて、この社会状況の中にあって、文化芸術といいますか、その奨励ということで、区を挙げて取り組んでいただきたいような気持ちでいっぱいなんですけど、それは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"桜井委員","kind":"質問","question":"中小企業の分野の第４点の質問で、副読本等の質問をしまして、社会科の副読本で充実を図るという趣旨でいただいたと思うんです。副読本を含めて、お示しほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"松澤委員","kind":"質問","question":"その件について、どのような形で半旗を掲げたのか。何か通達みたいものを出したのか、その辺を説明を求めました。","respondent":"鷹倉庶務課長","answer":"その区については、半旗を上げていただけるよう取り扱いをお願いしたいという文書がございました。その関係で、私どもも、各学校に写しを送付したところです。","id":"exchange-039"},{"speaker":"川西委員","kind":"意見","question":"狂牛病の問題で、こんなごく簡単な通達、モデルをもらったんで、きょう、委員会で報告があると思っていたんですが、きょうもあしたも書いてなかったので、どうなったのかとの意見を述べました。","respondent":"久保田学務課長","answer":"実は、あしたのその他のところでご報告しようと……。","id":"exchange-040"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういうのというのは、前回も通知は内閣官房からですか。今回は内閣からですか、そこの経緯を。","respondent":"鷹倉庶務課長","answer":"庁舎そのものも、そういう形で上げてあります。文書は、後ほど。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/605950?Template=document&Id=4416#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":28187,"voices":114}},{"id":"h13-20010925-5","meetingId":"h13-cm09","date":"2001年9月25日","dateIso":"2001-09-25","committee":"総務委員会","time":"午前１０時０４分～午後５時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"行います。なお、議案等の審査順につきましては、説明理事者の調整をほかの常任委員会とした上で予定表のとおりとしたものであります。 それでは、まず…","agenda":"行います。なお、議案等の審査順につきましては、説明理事者の調整をほかの常任委員会とした上で予定表のとおりとしたものであります。 それでは、まず…","exchanges":[{"speaker":"三上委員","kind":"質問","question":"そういう部分の文言の整理、国の流れというのは、今、どういうふうになっているんでしょうね。そこらあたりを説明を求めました。","respondent":"太川総務課長","answer":"その件につきまして、今、委員のほうのご指摘のとおり、横書きにしておりますのは、２３区でももう既に２区ございまして、私どものは３区目です。基本的には、自治体のほうが先行していると考えています。","id":"exchange-001"},{"speaker":"三上委員","kind":"質問","question":"それこそインターネットを使ってどうのこうのってどんどん始まってきている世の中の流れがあっても、Ｂ版とか、これはもう全国ばらばらです。だから、それに当たって、区長会あたりもどういうふうに動こうとされているのか、どうなんでしょうかね。","respondent":"太川総務課長","answer":"その点につきましては、いわゆる区長会の中で、この話が直接議題、ないしは話題に上っているというのは、私のほうでは聞いてはございません。今、版はＡ４にほぼ確定してはまいりましたけれども、いずれまたその辺の話というのは区長会あたりで出てくるものと思ってあります。","id":"exchange-002"},{"speaker":"三上委員","kind":"意見","question":"そういった意味で、しっかりほかのところにも呼びかけいくように、いろいろな機会を使ってお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"北野委員","kind":"質問","question":"各１冊ずつだと思うんですが、例規集が配られて、それはもう既に横書きという形になっています。各会派に設置するというお話を伺ってはいるんですが、毎年１冊置くときに、どうなんか尋ねました。","respondent":"太川総務課長","answer":"従来は年に１回、差し替えをやってまいりました。経費的な部分につきましても、新しい情報４回の入れ替えができるというメリットがありますので、そういうものを私どもとしては考えております。","id":"exchange-004"},{"speaker":"北野委員","kind":"質問","question":"年１回印刷をして、交換する部分だけ差し替えていったほうが経費的にもいいんではないかなということで、ちょっとお伺いさせていただいたんです。その点については、どうなんか尋ねました。","respondent":"太川総務課長","answer":"金額的に１,４００万円近くかかってございましたので、今回、その経費というのは依然として変わらないということがあります。いわゆるパソコン上に入れましたものをプリントアウトすることによって１冊つくるということになりますから、一応、ご理解いただきたいと思います。","id":"exchange-005"},{"speaker":"北野委員","kind":"意見","question":"今回は、条例と規則ということですけれども、品川区には要綱とか、要領とかいっぱいありますよね。ゆくゆくは、それもやはり目に見えるような形で、ホームページの中に入れていく必要があるんじゃないかと思いますけど、それについてお考えをとの意見を述べました。","respondent":"太川総務課長","answer":"要綱、要領につきましては、基本的に決して非公開のものでも何でもございませんので、それはある程度、時期、全体の流れの中で、私どもとしてもやっぱり考えていくべきものとは思ってあります。","id":"exchange-006"},{"speaker":"北野委員","kind":"質問・要望","question":"事業には必ずつくわけですから、技術的に載せられる時期が来たら、一日も早く載せてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"施行前に公布されたすべての条例を対象にする意味というんでしょうか、どのような対応をされるのかということで、ちょっとお伺いしたいんです。そういったことと今回のことは、紙の量的な部分でどのような対応をされるのかだけ、ちょっと確認をしておきます。","respondent":"太川総務課長","answer":"いわゆる形式的にパソコン上の処理でまいりますので、縦の部分はそのままにしておいて、横の部分だけ対応しているということはありません。今まで物で回りましたものが、ＩＳＯの関係から申しましても、そういう意味でのペーパーレスには非常に貢献していくものと考えています。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"まさに膨大な消費量になってしまいますので、それはということで、質問させていただきました。あるいはその他、経費的なものでどれぐらいかかるものなのかだけ、お伺いします。","respondent":"太川総務課長","answer":"予算上、５２０万円組んです。年１回差し替えるのに１,３００万円ほどかかりますので、経費的には、大幅に減になっていると考えております。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"非常にそれと似て非なのか、似て似なのかわからないんですけど、そういうところが皆さんの議論の中でされたのかどうか。そんなところは個人的な説明はしにくいから、議論があったのか、なかったのだけ聞かせてくださいとの意見を述べました。","respondent":"太川総務課長","answer":"直接は、委員、ご指摘のところの歴史、文化的なものが、これによってなくなっていくんではないかという観点での議論はしてございません。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"国語というのを持っておいてほしいし、その辺が残念だなと、僕の感想です。それから、条例の文の中で一番最後の付則のところなんですけど、「この条例は、規則で定める日から……」となっていますが、なぜこうなったんか尋ねました。","respondent":"太川総務課長","answer":"これにつきましては、現在、今回の条例も含めまして、まだ施行期日が決まっていないものもありますので、そういう意味合いで、今回、提案されているもの全部を含めまして、いつというのが決定された後、施行するという形をとっていますので、こういう書き方をしています。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、例えば、来年の４月１日からということになると、これも４月１日からということで、一番遅いのに合わせると理解してよろしいんか尋ねました。","respondent":"太川総務課長","answer":"そのとおりです。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"それから、第一条、第二条というのはアラビア数字になるんですか。「高橋久二」の「二」は漢字ですね。","respondent":"太川総務課長","answer":"第一がアラビア数字です。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"はいいです。ウ、エ、オという順番で書かれると考えていいんか尋ねました。","respondent":"太川総務課長","answer":"順番ですか。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"アに六本木とか、九州というのは、こういうふうに書かれている。この取り決め、約束事というのは、日本語学会みたいなところで決められているものなんか尋ねました。","respondent":"太川総務課長","answer":"この取り決めと言えば取り決めですが、品川区の用字・用語例の訓令が昭和３６年に出ておりますけれども、それに基づいております。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"「いろは」を「あいうえお」に、なぜ変えるんですか。「いろは」を「あいうえお」に変えた理由を聞かせてください。","respondent":"太川総務課長","answer":"これにつきましても、公文例および用字例です。昭和３６年に交付されております。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと説明してほしいんだけど、縦書きは「いろは」で、横書きは「あいうえお」と決まっているんですか、それは。","respondent":"太川総務課長","answer":"そのとおりです。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"なぜ、ただ単なる「横書き」じゃいけないんですか。昔の看板にはあったけど。","respondent":"太川総務課長","answer":"やはり、左から横書きにするということはきちっと決めなきゃいけないことです。今、言われたように、看板は、今も右のもありますので、ついては、左横書きです。","id":"exchange-018"},{"speaker":"土井副委員長","kind":"質問","question":"一番大きいのは、一般的に横書きにするのは何数字というんですか、時計文字のあれね。そしてまた、一番最後のところにきて、一般的には、日本的にはＡ、Ｂ、Ｃがないものですから、あ、い、うとなるのが多いように思うんです。","respondent":"太川総務課長","answer":"これにつきましては、いわゆる私どものほうで、先ほどから言っております公文例および用字例で言っておりますけれども、公文上は、そのように決められているものです。","id":"exchange-019"},{"speaker":"土井副委員長","kind":"質問","question":"法令を、当たり前の形で、だれもが認める形でつくるべきじゃないですかと。いわゆる日本語学会というのがあるのか、そういう普遍的なものに依拠すべきじゃないかと思うものですから、伺っているんです。","respondent":"太川総務課長","answer":"大変失礼ですが、ナンバリングというのは、いわゆる１、２、３、４という意味ですか。そういう意味ですか。","id":"exchange-020"},{"speaker":"土井副委員長","kind":"意見","question":"大きい１、２、３、第１条とかありますね。そういうやり方の順序立てをきちんと決めたものがどうなっていますかということですとの意見を述べました。","respondent":"太川総務課長","answer":"それにつきましては、今までの条例も全部含めてそうですけれども、いわゆる、先ほどから何度も申し上げておりますが、公文例、用字例の部分では、その辺につきましてはきちっと決められて、ルール立っているものと考えています。","id":"exchange-021"},{"speaker":"土井副委員長","kind":"質問","question":"そうじゃくて、現代の世の中に合うようにせっかく左横書きにするわけですから、一般的にどこにいっても普通に通用するやり方というのがあるはずだ。それをどうなさっていますかと。","respondent":"太川総務課長","answer":"今、副委員長がおっしゃっている部分につきましては、現況におきましても、その辺のルールというのはできているものと思ってあります。それはそこで考えなきゃいけませんが、現行の中で、そこのルール立てというのはできていると考えています。","id":"exchange-022"},{"speaker":"土井副委員長","kind":"意見","question":"(2)、(3)があって、そういう流れを言っているんです。その流れが、どこか飛っじゃっているんじゃないかと言っているんですとの意見を述べました。","respondent":"市岡企画財政課長","answer":"第１、(1)、厳格な先生は減点をするということがよくあります。おっしゃられるとおり、「お」と「か」はほんとうはどっちが先なのかという議論は確かにありますけれども、国の用字例に倣って決めているです。","id":"exchange-023"},{"speaker":"土井副委員長","kind":"意見","question":"先ほど、お話があったように、国のほうは縦書き、分量が多いからということで逃げているのかどうかわからないけれども、そういう状況ですね。感想だけ述べておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"確認","question":"もう１回、すみません、確認だけさせておいてください。そうなってくると、今度、品川区内に出る文書はすべて横書きになると考えなきゃいけないんか尋ねました。","respondent":"太川総務課長、本間総務部長","answer":"基本的には、いわゆる行政から出す公文書につきましては、基本原則でＡ４の横ということになっております。やはり縦でやらざるを得ないものもありますので、その部分は、やはり例外として残さざるを得ないかなと考えています。 今回も、法令的な部分については横書きで統一して、ＩＴ時代にマッチしたシステムにしていきたい。こういう部分についてまで横書きにするという考えは、現在のところ、持ってございません。","id":"exchange-025"}]},{"id":"topic-02","title":"の第８２号議案、特別区人事・厚生事務組合の共同処理する事務の変更および特別区人事及び厚生事務組合規約の変更","agenda":"の第８２号議案、特別区人事・厚生事務組合の共同処理する事務の変更および特別区人事及び厚生事務組合規約の変更","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"今回の質問で触れましたように特別区人事・厚生事務組合の役割というものは、それも既に時代的に役割が終わりつつあるという認識を示しております。それと、負担の責任といいますか、どこがどれを負担するかということを説明願いたいと思います。","respondent":"太川総務課長","answer":"平成１３年１１月からやるといたしまして、５カ月分で、それから運営費を含めまして４億２,０００万円と聞いてあります。残りの２分の１を２３分の１ずつ負担ということで、９００万円の支出になる、そういうことです。","id":"exchange-026"},{"speaker":"塚本委員","kind":"意見","question":"迷惑施設であることは間違いないんだけど、それに真剣に取り組んでみたら、これはやはり本質的に東京都がやるべき仕事ですよと。具体的にさっきの数字の部分で、施設と運営経費の按分のところをもう１回聞くのと、考え方のところで、助役のお考えを聞かせてくださいとの意見を述べました。","respondent":"太川総務課長、本間総務部長","answer":"平成１３年１１月から来年の３月分で２億２,０００万円、合計４億２,０００万円と、私のほうとしては聞いてあります。それで、平均いたしまして、１区９００万円です。 こういう共同事務の基本的な考え方という後段のご質問ですけれども、効率よく執行できるという部分については、継続して行っていくということです。提案をしていますので、ご理解のほど、よろしくお願い申し上げます。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"ですから、広域的なのはわかるけど、なぜ東京都じゃないのかということ。なぜ、東京都じゃないのか。","respondent":"濱野助役","answer":"この問題ともちろん同一ではありませんけれども、広域的な対応が必要であるということ、こういうことになったです。今般一日も早く対応しなければならないという事情の中で、こういう取り扱いになったということでご理解いただきたいと思います。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"この場で新たに、ある程度共通のものになったと思いながら、事態に対応していただきたい。これでやめときます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"意見","question":"大田区が３００人、２３区の路上生活者が５,０００人ぐらいになっているという説明だったんですけども、数の考え方はどういうふうになっているのか。今後の増設も含めての考え方というのは、どういうふうになっていますかとの意見を述べました。","respondent":"黒田生活福祉課長","answer":"墨田区が年内の１２月か１月ぐらいの予定で、今、動いてありますけれども、自立支援センターが、渋谷区を含めて５カ所できますと、４００名程度です。施設の予定はそういうことです。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"私の質問の趣旨は、やっぱり一番心配されるのは、冬をどういうふうに乗り切るかというのがあるかと思うんです。私は想像しているんですけども、そこら辺のところはどんな感じで見ておられるのか、あわせてお願いします。","respondent":"黒田生活福祉課長","answer":"冬についても、平成１２年度につきましては、冬季臨時宿泊所というのを、なぎさともう１カ所で実施していますのでクリアできました。自立支援センターと一時保護センターで動いてはございまして、人数は少ないんですが、やはり今回も冬季臨時宿泊所というのを開設する予定です。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問・要望","question":"いわゆる就職していく、実際上、就職して一人立ちしていくのはどんな感じになっているのかというのを教えていただきたい。そこら辺のところは、どうか尋ねました。","respondent":"黒田生活福祉課長","answer":"路上生活をしていた方が自立支援センターに入りまして、今年の８月末なんですが、就労による自立をされた方が４１.３％です。自立支援センターから、即アパートを借りるということは、今のところは考えてございません。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"区の対応が機械的かなという感じも受けたものですから、かなり数が多くなってきますけれども、ぜひきめ細かい対応をしてほしいと求めました。交通災害のほうもいいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと交通災害共済のほうで伺いたいんですけども、まず、品川区としてはどういう対応をしてきたのかというのが一つ。そこのところを、ちょっとお聞かせほしいと求めました。","respondent":"宮地区民課長","answer":"１点目の、いろいろ検討させていただきましたが、共同処理は廃止するという方向で結論を出しています。平成７年の段階で５万２,０００人強だったのが、平成１２年度で４万２,０００人ということで、全体の減少率は２０％強という状況になってあります。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"まず、やっぱりそういう意味じゃ、手軽に使えるというのがあったかと思うんです。実際に町会とか商店会の方々はかなり使っていたんですけども、こういうところの方々の意見というか、声というのは実際に聞いておられますかとの意見を述べました。","respondent":"宮地区民課長","answer":"これだけではちょっと不安だということで、いろいろな家庭内事故とか、転倒等も含めてちょっとした不慮の事故の民間の保険に入っていらっしゃいます。入っていれば、お守りがわりになるかしらというご意見も、あわせてございました。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"手軽に入れる保険だったものですから、これは続けていってほしいという声もありましたから、これは紹介しておきます。そこら辺のところは、どうか尋ねました。","respondent":"宮地区民課長","answer":"最終的には、参加するところは数区になろうかと思いますが、それを対象に、民間の保険会社がある保険制度を検討しています。民間ですと１,０００万円出るところが、６００万円とか、聞いてあります。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"意見","question":"１点。例えば町会、商店会の方で今まで利用されていた方への対応といいますか、それはどういうふうにされますかとの意見を述べました。","respondent":"宮地区民課長","answer":"１０月末から１１月中旬にかけまして、その後、それも説明した内容の直接のお手紙を差し上げる予定です。町会等に説明する機会が今後あろうかと思いますので、私どもが出向いて行きまして、お話をするということになっております。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"要するに、区と都が一部事務組合に委託しているみたいなものじゃないですか。５億円だ、これができると３億円だとかいうような、東京都と話しをしないんか尋ねました。","respondent":"市岡企画財政課長","answer":"さらにこういう行政需要が増大するようであれば、国の責任も含めて、いろいろな議論を都市行政としてしていかなければいけないものだと思います。とりあえず、今、各区への負担をお願いをされているのは、先ほど、総務課長、それから生活福祉課長が申し上げた段階です。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"「厚生」という２文字で、威厳を持たせておけばいいんじゃないかというのが出てきたんじゃないのかなという気がするんです。その辺、東京都と話をしてみるべきじゃないかという気がするんですけど、いかがか尋ねました。","respondent":"黒田生活福祉課長","answer":"平成１３年度で、１億２,０００万円強のお金が出るということで、意見を出しました。の取り組みとか、できる範囲で、資源を活用しながら取り組んでまいりたいと思います。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"意見","question":"自転車対策だって１億円をかけているんだから、やるときはどんとやる。お願いしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"北野委員","kind":"質問","question":"ちょっとお伺いしたいんですけれども、来年の４月１日廃止ということですけれど、入っている間は補償がつきますよね。その年を外れたとしても、１年か２年の請求の期間があると思うんですけれども、廃止された後、その補償はどうなるのか、ちょっとお伺いしたいんです。","respondent":"宮地区民課長","answer":"それから請求期間が２カ年ですから、最終的には、平成１７年３月末をもって契約事項が終了いたします。そういう形になります。","id":"exchange-041"},{"speaker":"北野委員","kind":"意見","question":"それは、加入するときに、ちゃんと説明していただいていることですよね。事故に遭わないことが一番なんですけれども、入った以上は、補償ということはぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]},{"id":"topic-03","title":"平成１３年請願第８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成１３年請願第８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"あるいは特殊事業、やはり人の手当てをどうやっていくかということ、これに歴然と公私の格差が出てきているということが実態じゃないかと思います。その辺の認識は一緒なのかどうか、説明を求めました。","respondent":"太川総務課長","answer":"それについても、そろそろやはり考えていかなきゃいけない時期に来ているということは認識しています。ちょっとまだこれから検討しなきゃいけない部分ですけれども、私どもも、実情に合った部分での考え方を少し取り入れていくべきものと考えています。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"実態は、私の感覚でものを言わせてもらうと、先生の給与は、公務員の６掛けか７掛けぐらいだろうと思います。それになお、公立と競争ができなくなるという妙な現象が起きておりますので、今のお答えを具体化することを強く要望します。","respondent":"太川総務課長","answer":"実態に合った部分という形でお話を申し上げましたけれども、考え方の基本にありますのは、全体の中を少し見直していきたいという意味です。それにつきましては、実情に合った形を少し取り入れて考えていくべきときが来ているかなという意味ですので、よろしくお願いいたします。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"意見","question":"今、課長の答弁の中身は、具体的にどういうことを考えておられるのか、説明できる範囲でいいんですが、もうちょっと詳しくお願いしたい。資料のところで、実際に公私の格差がどのぐらいになっているかというのがよくわからないんですけども、そこら辺の説明をしてほしいと求めました。","respondent":"太川総務課長","answer":"今年の補助金のあれでいきますと、二、三千円あるかないかというような数字に迫ってきていると考えております。以前ほど、月々の部分での公私の格差はございません。","id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"いわゆる、保護者負担の部分ということですね、そこの資料がなかったものですから、わかりました。一番最初の入園奨励費のほうは、どうか尋ねました。","respondent":"太川総務課長","answer":"入園料補助金ですか。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"保護者負担の部分もありますし、予算が絡む請願ですから、できればきょう決めていただきたい。扱えないんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"わかりました。予算編成の中で、できる限り考えていただきたいというお願いを込めて、趣旨採択。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"可処分所得というんでしょうか、どれだけ負担に耐えられるのかというところもあわせた考えた支援のあり方を考えていただきたいという思いも一方です。そういった観点も、ぜひあわせてご検討いただきたいという意を含めて、ぜひ採択をお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"中島委員","kind":"質問","question":"どうせ出るなら春に出してほしいという声も聞いているぐらいですから、幼稚園ということで、子どもの教育のために選んでいることだと思います。２３区を見たときに、うちのほうは、趣旨採択ということでいきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"北野委員","kind":"質問・要望","question":"私も紹介議員になっているということで、ぜひ、採択してほしいと求めました。保護者がどういう園に行かせたいかとか、趣旨採択ではなくて、採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"土井副委員長","kind":"質問・要望","question":"というのは、別の形で後から来るものですから、この格差がそれだけになっているということに対するご理解が不十分な感じがしないでもないんですね。その範囲の中で、やれるものはやっていただきたいということも含めて、趣旨採択ということでお願いをしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"林（宏）委員","kind":"意見","question":"あなたたちが意見をつっぱるとそういう結果になりますから、委員長とやりとりをしてください。何も説得はしていませんよとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"一番最初に採択かどうかの決を取っていただき、次に、趣旨採択についてイエスかノーかという聞き方が行えるのかどうか。そういうことは可能なんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"北野委員","kind":"質問・要望","question":"やはり、これは予算を伴うということで、さっきも発言させていただきましたけれども、方向性としては、皆さん同じ考えだと思いますので、ぜひ、努力をしていただきたいということで、私は趣旨採択ということで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"私も、限りなく採択を主張しますが、予算編成権、執行権は区長側にありますし、裏付けとなるものが、ぜひ実現ををしていただきたいという願意も含めて、趣旨採択に同意いたしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"}]},{"id":"topic-04","title":"第７０号議案、平成１３年度品川区一般会計補正予算","agenda":"第７０号議案、平成１３年度品川区一般会計補正予算","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"これはしていいのかどうかわからないのだけれど、予算委員会に出られないのでいいのかなと思いつつ、総務委員会なのでお聞きします。ずっと疑問に思っていたんで、きょう説明をされて、そういう手法しかないのか、そのときにわかりやすい処理をすることはできないんですかね。","respondent":"市岡企画財政課長","answer":"この１０万円は、先ほど繰越金をちょっとご説明申し上げましたけど、あの中に紛れ込んでしまったんです。繰越金の中でわからなくなってしまうといけませんので、あえてはっきり指定寄附のご趣旨に従って、まず積み立てようです。","id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"それから、少子化対策の基金が５００万円入っているんですね。これは、平成１３年度で終わるようになっているとすれば、その基金の残額、つまり、あと幾らぐらい使えるのか、教えていただけますか。","respondent":"市岡企画財政課長","answer":"５００万円予算を組むのはどういうことかというご疑問があろうかと思うんですが、これは工事費ですので、私どもは必ず落差が出ると思っています。もし４７０万円ぴったりの予算を組んでしまいますと、落差見込みでぎりぎり組んでおきまして、一番効率的にできます。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問・要望","question":"歳入のところで、先ほど説明があった、１０ページで公営住宅等供給促進緊急助成事業なんですけども、これについて具体的にどういう内容なのか、どういう背景で出てきたのか、そこら辺の説明をほしいと求めました。","respondent":"市岡企画財政課長","answer":"ただ、先ほどもちょっと申し上げたとおり、毎年緊急だということで、何回か延伸をされてきたんですが、どうやら平成１３年度が最後だと。いろいろな諸般の状況を考えますと、先ほど、ご説明申し上げたような手続をとったものです。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"意見","question":"今年度が最後となると、先ほどの西大井のところは区営住宅と複合施設にするんですけど、例えばこういうところなんかは対象になるのか、ならないのか。そこのところは、どうでしょうとの意見を述べました。","respondent":"市岡企画財政課長","answer":"設計費の補助金がありますが、設計費、建設費というものの補助金が制度として確立しております。これは法律の補助ですので、こちらが優先されるという形になります。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問・要望","question":"わかりました。たしか区内では２校が指定されていたかと思いますが、どういうふうな内容になるのか、ちょっとお知らせいただきたい。","respondent":"市岡企画財政課長","answer":"所管を通じて、こういう指定は年度前の予算編成期にぜひしてもらいたいということを、都を通じて国のほうに申し入れしているところです。内容は、従前の引き継ぎです。","id":"exchange-061"},{"speaker":"三上委員","kind":"意見","question":"１９ページの仮称西大井六丁目複合施設の設計委託等について、予算計上されている。これがすべて載っていたのかどうか、そのような形でやられるのかどうかというのに興味を持っているんですけどとの意見を述べました。","respondent":"市岡企画財政課長","answer":"所管のほうでは、今、そういう希望を持っております。ただ、今回のは建設費本体ではありませんで、まず自主設計をして、その辺のメリット、デメリットをよく検討したいと、所管では進めております。","id":"exchange-062"},{"speaker":"三上委員","kind":"質問・要望","question":"このプロポーザル方式に参加する人たちの負担ということについては、どういうふうに我々は考えていったらいいんでしょうかね。自治体としての考え方というのか、どういうふうに受けとめて考えていこうとされているのか、伺っておきたいなと思います。","respondent":"岡田施設課長","answer":"説明会のときにそういう趣旨の説明をしまして、それに提案できる設計事務所で結構ですと、こういう形の説明をしています。そういう意味では、極力、図面だとか、模型だとかをつくらないようにという説明をしています。","id":"exchange-063"},{"speaker":"三上委員","kind":"質問・要望","question":"今の時期、やっぱりやっていっていただきたいということを、強くお願いしておきたいと思うんです。結果的にどういうふうになるか、それはわかりませんけれども、要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"北野委員","kind":"質問","question":"１点、質問なんですけども、それから後の２５ページの職員費のところに分かれていますよね。それで、一般財源に入って相殺されている形なんですけども、それはどういう意味なのか、お伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"財源充当という言い方をしますけれども、一定程度は事務費に充て、残ったら職員費に充ててよいという組み立てになっています。財源更正という言い方で、民生費、職員費のところに載せてあるものです。","id":"exchange-065"},{"speaker":"北野委員","kind":"質問","question":"では、事務費に充てている８４万４,０００円というのが、受託事務として、一応、事務の範囲の中では、この経費で賄えるということですか。それで残りの分を、職員費のほうで相殺したということか尋ねました。","respondent":"市岡企画財政課長","answer":"そういうご理解でよろしいかと思います。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問","question":"１点だけに絞ってお伺いしたいんですが、都から移管されるものには何らかの条件というんでしょうか、２０年間はその目的でとか。知的障害者の方が入所する施設と住宅が合わさるということなんですが、今までこういうケースがあったのかどうか、お伺いします。","respondent":"市岡企画財政課長","answer":"１点目の、２０年間この用途のとおり、公営住宅として使うということが条件になっております。したがいまして、今回の例は、私の聞いているところでは、初めてのケースということです。","id":"exchange-067"},{"speaker":"宮崎委員","kind":"質問","question":"今の西大井六丁目のところは、現時点で何部屋あって、今度出てくるんでしょうか、区営住宅としては何部屋になるのか、この辺の計画はどうなんか尋ねました。","respondent":"市岡企画財政課長","answer":"現況から申し上げますと、都営住宅が４２戸あります。つまり４戸増やすわけですが、その４戸は、特定目的住宅で別に募集をするということになります。","id":"exchange-068"}]},{"id":"topic-05","title":"の第７６号議案 仮称母子生活支援施設等複合施設新築工事請負契約","agenda":"の第７６号議案 仮称母子生活支援施設等複合施設新築工事請負契約","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"ですから、これについては、できるならば、そういった情報が仮にあった場合には、ご努力いただきたいと、これはお願いしておきたいと思っています。何らかの要望とか、お願いだとかということがあったのかどうか、ちょっとお教えていただけませんか。","respondent":"岡田施設課長","answer":"１回目は、基本計画ができたときに、計画概要の説明会をいたしました。それから、先日、工事説明会という形で、解体工事のほうは決まっておりますので、これを含めて説明会を行いました。","id":"exchange-069"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、北側に接する部分について、もうちょっと離れてもらいたいという要望は聞けたのかなと思うんです。そういった公園改修の件がありましたら、そこのところを一体となったような考え方にしてもらいたいなと思うんですけど、どうなんか尋ねました。","respondent":"岡田施設課長","answer":"建物をもうちょっと南側に寄せたらというお話ですけども、当初、私どももそういう案は考えました。よく２項道路の話が出ておりますけれども、そういう機会をとらえて、これは開発指導のほうから指導を受けて設計したものです。","id":"exchange-070"},{"speaker":"北野委員","kind":"質問","question":"これが大体みんな同額のところの並んでいるというのは、どうしてなのかすごく疑問に思うんです。みんな構造は同じものとし、建物を建てるんだったらこれぐらいの金額というのが、目安として公示しないまでもわかるんか尋ねました。","respondent":"西島経理課長","answer":"応募をされた事業者の方に設計書をお渡しして、それをもとに積算をしていただくわけですが、その積算の元となる数字というのが公開されております。したがいまして、きちっとある程度包み込んでいけば、そんなに大きな誤差が出てこないと考えています。","id":"exchange-071"},{"speaker":"北野委員","kind":"質問","question":"大体、使う建材というものは、やっぱり仕様書ではこういうものと決まっているものがあって、結局、その中から建設の方たちは選ぶんか尋ねました。","respondent":"岡田施設課長","answer":"したがいまして、それから外れたものは私どもの検査に引っかかりますので、使えないようなシステムになっております。これは、契約書に一緒に綴じ込まれますので、それに基づいて積算するなり、あるいは、現場の材料を選ぶというような形になってあります。","id":"exchange-072"},{"speaker":"北野委員","kind":"質問","question":"それで出てくるんですけれども、使われる範囲というのは何種類か決まっているから、こういうふうに金額的な誤差というのが出るんでしょうね。いいものが高いというわけではないと思いますけれども、入札をしたときに、区として選ぶ基準というのはどういうところなんか尋ねました。","respondent":"西島経理課長","answer":"数字の差が出てくるというのは、一言で言ってしまえば、企業努力の部分です。その中で、幾らの金額にするかというのは、それぞれ入札参加者のほうで決めて応札してくるです。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"意見","question":"１点目は、たしか３１部屋だったと思うんですけども、部屋数としては２０に大分減ってますよね。２０部屋で大丈夫というか、その辺の実情といいますか、ちょっと説明ほしいと求めました。","respondent":"谷田部児童課長","answer":"私ども、この間の四、五年の入所世帯の推移を見まして、２０世帯で十分、新施設のほうで大丈夫だということがまず１点。その辺の両方から見まして、今回、２０世帯として定員を設けたところです。","id":"exchange-074"},{"speaker":"宮崎委員","kind":"質問","question":"じゃあ、そうすると、大体のこの間は１５とか、そのぐらいで推移しているということなんですか。そこら辺のところは、どういうふうにお考えなのか。","respondent":"西島経理課長","answer":"１億３,６５０万円ですので、ゼネコンということではなくて、中と大のちょうど中間ぐらいの規模ではなかろうかと考えてます。営業所としてきちっと区内で活動していただければ、品川区の場合は区内業者という取り扱いですので、そのようにご理解いただきたいと思います。","id":"exchange-075"},{"speaker":"宮崎委員","kind":"質問","question":"例えば、これで見ますと、もうちょっと区内業者という精神が生かされるということが必要じゃないかと思うんです。参入のために名目上事務所を置ているとか、そういうことはないのかどうかというところの判断というのは、どうされているんか尋ねました。","respondent":"西島経理課長","answer":"実態調査を行いまして、そこで契約行為ができるかどうか、それから責任者がいるのかということをきちっと確認をして登録しています。特に新規登録の場合は、新規登録を受けた後で、必ず調査に行って、区内業者だと認定をしてやっておりますので、その辺は…","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"５番目に高田・塩谷建設共同企業体、３のところからそのまま移ってきちゃっているけど、印刷ミスじゃないですか。おそらく、高田何とか工業とかいう名前になるんだろうと思うんですけど。","respondent":"西島経理課長","answer":"失礼いたしました。ここは、高田工業の間違いです。","id":"exchange-077"},{"speaker":"林（宏）委員","kind":"質問","question":"こんなに資本金は大きいんですか。ダントツですよ。","respondent":"西島経理課長","answer":"正式名称は、もう一度、確認して報告します。申しわけありません。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問","question":"そのときに、完成保証の部分で、そこがどういうふうになっているか。上がこけたときに、下はどういう影響をこうむるのかということについて、説明を求めました。","respondent":"西島経理課長","answer":"建築の場合、４億円以上の工事についてはＪＶを組むというでやってありますので、二十数億円という金額ですので、特に特例規定は設けてございません。それから、契約保証金の問題ですけれども。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問","question":"もとがつぶれる可能性がかなりあるということは、皆さん認識しているわけですね。こっちも、自治体のほうもつぶれるわけがないしという感覚の中で、契約慣行が今までのとおりでいいのかというような質問の趣旨なんですよ。","respondent":"西島経理課長","answer":"そういう意味ですと、今までは契約保証金というのを取ってございまして、完成工事ができない場合には、そこから賠償する。あるいは履行ボンドという保険に入ってございまして、できない場合にはそこで補償するという取り扱いになってあります。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"これだけ大きくなって、経済情勢が変わってきているんですから、そこのところが今までどおりでいいか、保証金で賄えるのかどうか。速やかに健全なる企業が請け負って、こういう約束になっていましたから、私が仕事をさせてもらいますとなるかどうかということを聞いているんです。","respondent":"岡田施設課長","answer":"過去において、ＪＶではありませんでしたけれども、ＪＶの下のほうが、そういうことになったことがあります。やはり同じような形で、できた部分については支払いをするけれども、できてない部分は後の人に受け継いでもらうというような形でやってあります。","id":"exchange-081"},{"speaker":"塚本委員","kind":"質問・要望","question":"上がつぶれたら、大きさが違うわけですから、その次々がもろに会社がすっとんでしまうというような事態も考えられるわけですよね。そこのところを仕組みをしっかりしてほしいということが願い。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問","question":"１点は、契約というものの考え方というか、とらえ方とか、そういう部分でお伺いしたいんです。こういう契約というものの考え方、また一方、議会側とのかかわりにおいての考え方というのをまずちょっとお伺いしたいと思います。","respondent":"西島経理課長","answer":"それから、道路の補修、あるいは改修という部分が出てまいりますと、それまでということになると、なかなか問題が出てまいろうかと考えています。現在のところは、そういう状況で進めているです。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"要望といいますか、総額で１億８,０００万円以上とか、そういう方向でご検討いただけないかという形の要望としてさせてほしいと求めました。湿気だとか、何か特別な配慮などがされた施設になるのかどうかを、ちょっと確認をさせていただきたい。","respondent":"岡田施設課長","answer":"こういう意味では、スパンといいますか、飛んでいる部分、あるいは広さの部分で、柱で制約される、こういう意味合いでのデメリットはあります。今の構真柱は、後ほど建てる建物のこともある程度頭に入れてスパンを考えておりますので…","id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"今から設計変更とかは難しいかもしれませんけれども、そういう池の上にできる施設だということを、ぜひ十分ご配慮いただいた運営の仕方をお願いしたいという要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"}]},{"id":"topic-06","title":"の第８１号議案、大崎駅東西自由通路延伸部分および乗換えこ線橋整備工事請負契約","agenda":"の第８１号議案、大崎駅東西自由通路延伸部分および乗換えこ線橋整備工事請負契約","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"ついでに、ホームの上にできる乗換えこ線橋についてもお願いします。だれの持ち物になって、維持管理はだれがして、事故があったときの責任はだれが持つのかとの意見を述べました。","respondent":"市岡企画財政課長","answer":"区有通路というふうな、道路に準ずる区の資産として、ＪＲとの協定のもとに区が管理をすることになります。それから、ＪＲの駅舎部分を一部臨海が使用権を持って管理する部分と、ＪＲがＪＲの資産として管理する部分とに分かれるかと思います。","id":"exchange-086"},{"speaker":"林（宏）委員","kind":"質問","question":"この間の明石みたいな事故が起きたときに、どこがというのが出てくると思うんですけど、その辺はこれから協議するわけですか。人のお金でやるから、あまり強くは言えないのかもわからないけど。","respondent":"市岡企画財政課長","answer":"まだ設置費用についてしか協議をしておりませんので、所管のほうを通じて、将来。〔「西口も」と呼ぶ者あり〕西口も含めてです。","id":"exchange-087"},{"speaker":"林（宏）委員","kind":"意見","question":"それだけはお願いしておきたい。その辺もしっかりしておかないと、何が起きるかわからないので、ぜひお願いをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"三上委員","kind":"質問","question":"ここも、要するに鉄建公団のような形で、そこが工事をするという形で、それにしたって別な会社なわけですよね。間に入って、どこかに仕事をやらせるという仕組みにならざるを得ないと受けとめているんですけども、それで間違いないか尋ねました。","respondent":"市岡企画財政課長","answer":"この辺はＪＲが責任を持って行うということになりますので、委員のおっしゃられるとおり、実際には何社かの建設事業者が下請けとして入ることになろうかと思います。","id":"exchange-089"},{"speaker":"三上委員","kind":"意見","question":"全くこの金額で工事をお願いするということになるのかどうか。結局、そういうことで、中間マージンは東日本旅客鉄道株式会社が取りますよという理解でいいんですねとの意見を述べました。","respondent":"市岡企画財政課長","answer":"ご説明しているとおり、それから施工管理技術上も、相当専門的なノウハウが必要です。この中にしっかり入っておりまして、契約書、工事協定の中での内訳を明記させる形になろうかと思うんです。","id":"exchange-090"},{"speaker":"三上委員","kind":"質問","question":"そうすると、最終的にその金額がどうのこうのということは、品川区としてはちゃんと聞きますよということになっているんですか、ＪＲ東日本から。","respondent":"市岡企画財政課長","answer":"内訳の中で、管理費が幾ら、それから、個々の工事に相当する、例えば基礎工が幾らだとか、けたをかけますから、けたの工事費が幾らかとかいうことは、工事協定の中で、添付文書としてつくような形になっています。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/517525?Template=document&Id=1558#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":69399,"voices":263}},{"id":"h13-20010926-6","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"区民委員会","time":"午前１０時０５分～午後２時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問","question":"こっちは区民委員会なものですから、委員会の関係で、この図そのものについては特にないんですけれども、地域センターがこっちに出てきますよね。どういう構造になっているのかなと、多分質問が出たんじゃないかと思うんだけれども、ちょっと説明を求めました。","respondent":"長田地域活動課長","answer":"池の上の構造はということなんですけれども、今まで設計等の会議に出させている中での説明では、池が何層かになっているようです。その辺につきましては設計事務所のほうで強度計算をしっかりやっていると思いますので、崩れたりというような心配はないかと思います。","id":"exchange-001"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけいいですか。３０年間でしたっけ、その後の交渉というのはできているのかどうか、どなたか。","respondent":"長田地域活動課長","answer":"この地上権につきましては、借地権と違いますので永久の地上権ということで保有ができるというふうに説明は聞いております。地上権の権利というのは契約期間は一定はありますけれども、ずっと継続ができると、こういう意味で発言させていただきました。","id":"exchange-002"},{"speaker":"堺委員","kind":"質問","question":"これはどうするんですか、この大崎第一出張所というのは。あのビル自体は品川区のビルじゃないんですか、あれはどこかのビルのフロアを出張所として借りているのか尋ねました。","respondent":"長田地域活動課長","answer":"現在の大崎第一地域センターのビルにつきましては、４階建てでございまして、これは土地も建物もすべて区の所有になってあります。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"そうすると、１度しか通ったことがないので、中に入っていないんだけれども、わかんないでごめんなさいね、４階のそういう建物全部が大崎第一出張所で使っていたんか尋ねました。","respondent":"長田地域活動課長","answer":"１階の部分が地域センターで事務を扱っていまして、２、３、４階がそれぞれ区民集会所として利用しているという状況です。","id":"exchange-004"},{"speaker":"堺委員","kind":"確認","question":"３、４階という階数の違いはあったけれども、これは利用する人にとっては非常に利用勝手がいい形になってくるんだろうと思うんです。現行より広くなったような気もするんですが、その辺ちょっと確認させてください。","respondent":"長田地域活動課長","answer":"４階建てで、たしか年次の問題もございまして、エレベーターがございません。必ず集会所を義務づけられる部分がありまして、それとの関係で現在の計画のような配置になっているということでご理解いただければと思います。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"要するに利用される方の動線というんですか、これはどういう感じになるわけですか。要するに、年配の方が利用される場合の動線で、交通事故に遭わないようにするための流れなんかはどういうふうに考えているのか尋ねました。","respondent":"長田地域活動課長","answer":"２ページが一番わかりやすいかと思うんですけれども、それから、目黒川からどちらからでも入れます。Ａ棟の方々がそのＣ棟のほうの部分を使う場合についても、表に出ることなく中を通ってそれぞれの施設に行き来ができる、こういう形になってあります。","id":"exchange-006"},{"speaker":"堺委員","kind":"確認","question":"今なぜお尋ねしたかというと、この３ページ目の地図を見た場合に、Ａ地区のほうがよくわからないんですね。それだけちょっと確認しておきます。","respondent":"長田地域活動課長","answer":"道路から入る部分は３カ所ほどございまして、北側の今委員の指摘がありましたＡ地区駐車場出入り口、この脇が公園になってあります。それから東側に幅員５ｍの道路がありますけれども、また目黒川側からも入れる、こういう形になってあります。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"現在の大崎第一地域センターにおられる職員の方々が、そっくり移動、少なくて足りるかの職員体制になってくるのですか。人員的には増やさないという、そういう形で考えているのか、その辺を。","respondent":"長田地域活動課長","answer":"実は、このセンターは１３地域センターの中で、取り扱い件数が一番多いセンターです。人数も１３人と多いわけですけれども、私どものほうも現状の人数で実施をしよう、このように考えてあります。","id":"exchange-008"},{"speaker":"本田委員","kind":"意見","question":"複合施設なわけですよね。どんなふうなメンテナンスになるのかなと思うんですが、どこか１カ所に委託をしてやると思うんですが、その辺を参考までに聞かせてくださいとの意見を述べました。","respondent":"長田地域活動課長","answer":"５００にちょっと足りませんけれども、５００戸規模出てくるという中で、そういった部分を一括して民間を活用できないかという話もあります。昼間は職員がいますから問題はないにしても、夜の管理はこの防災センターのほうの職員に管理をしていただく…","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"防災センターの管理というと、区の直営になるんですか、これからのこの部分。ですから、つまり地域センターだけを管理するのではないと思うんですけれども、ちょっとそこのところを。","respondent":"長田地域活動課長","answer":"この５００戸規模の住宅の管理をどうするかという問題がありますので、こういう話で、ちょっと歯切れの悪い答弁をさせていただきました。基本的には、Ｃ地区の管理をする拠点というのは１階の防災センターであり、そこでＣ地区全体の管理はするよということに紛れはないと思いま…","id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"どこかに全く振るんだと思いますけれども、一元化で地域センターも管理、メンテナンスもやっていくと。そういうふうに理解していていいんか尋ねました。","respondent":"長田地域活動課長","answer":"委託で管理はお願いをする予定です。それから、夜間の管理等も含めて一緒にやっていくような形で考えてあります。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"さっきお話の中で１点確認し忘れて申しわけないんですけれども、教えていただきたいのが、４階建てということですから。地元からまたどういうふうに要望が出されてくるかも未掌握なんですが、中だけとか、その辺だけはちょっと検討してほしいと求めました。","respondent":"長田地域活動課長","answer":"中途でエレベーターを入れるというのは、これは大変なお金もかかりますし、大変な工事です。ですから、その目的に応じた改修がなされるべきだろうというふうに思ってあります。","id":"exchange-012"},{"speaker":"原委員","kind":"質問","question":"今の建物の話なんですけれども、あれは、できてどのぐらいたつんか尋ねました。","respondent":"長田地域活動課長","answer":"建設年月日が昭和４９年７月２２日ということになってあります。","id":"exchange-013"},{"speaker":"原委員","kind":"意見","question":"どこが使うかわかりませんけれども、大幅な改修をしないと、ちょっと難しいんじゃないのかなという気がするんです。だから、どこの課でどこの事業部が使うかは別としても、その辺は費用対効果をよく考えて検討してくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"原委員","kind":"確認","question":"一つだけちょっと確認を。そういうことは、医療関係の部分もそこで補ってくれるということですよね。","respondent":"辻田防災課長","answer":"総合防災訓練のほうで実施している形で、医師会等との連携の中でこれを実施したのではない、その方が救護の訓練を実施したという形です。","id":"exchange-015"},{"speaker":"原委員","kind":"意見","question":"ということは、医療も含めての訓練をしたということなのかどうかとの意見を述べました。","respondent":"辻田防災課長","answer":"この前、一般質問でもお答えしましたけれども、トリアージの訓練をするということを今回一つの目玉にいたしました。それから、包帯をするとか、診察をするとか、というような具体的な行動につきましては、今回は省略したです。","id":"exchange-016"},{"speaker":"本田委員","kind":"質問","question":"４００名余の職員の皆さんがこれだけご努力をされていることに大変感謝をしたいと思います。今回９月５日ですから従来の訓練だと思いますけれども、そういう危機管理についての多彩な問題というのは、どんなふうにとらえられていましたか。","respondent":"辻田防災課長","answer":"それの少し前に、駅ができて電車が走っちゃいますと訓練ができませんので、いわゆる電車が脱線して死傷者が出たというような訓練を実施いたしました。地域防災計画とは関係なく、そのときに合った適切な対応というのが常に求められているので、その辺が一人ひとりの防災課職員。","id":"exchange-017"},{"speaker":"本田委員","kind":"意見","question":"何ができるのかというような、問題はどこの自治体も同じだろうと思いますけど、検討をしていくときに来ているということを言っておいて終わります。答弁は要りませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"金高委員","kind":"質問","question":"そういう災害が起きたときに、そういうグッズですか、そういうのは用意されているんでしょうか。私も機能とかそういうのはちょっとよくわからないので、お聞かせ願いたいと思うんですけれども。","respondent":"辻田防災課長","answer":"そういう際にはそれなりの装備を持っていらっしゃるので、それを活用していただくという形になってくるかなと思います。その辺についてどうするかなというのは一つ考えていかなければならないということですけれども、なくても支障なく作業が行えると考えております。","id":"exchange-019"},{"speaker":"金高委員","kind":"質問","question":"それは、例えば阪神・淡路のときに、あれだけのいろんな倒壊がありましたね。区のほうではそういうのはまず、先々のことも含めて、用意する予定はないのか尋ねました。","respondent":"辻田防災課長","answer":"当然知識を持っておりますし、粉塵が飛ぶというようなこともありますので、そういうようなものを用意されているだろうという想定です。ただ、決して高価なものではありませんし、そういうようなものをある程度これからは考えていくことが必要かなというふうに考えております。","id":"exchange-020"},{"speaker":"金高委員","kind":"質問","question":"そういう提示というんですか、あるいは危機意識に対する、すごく神経がぴりぴりしている方が大勢いる。昨日のちょっとテレビを見ていたら、核シェルターも掘り出したという話があったぐらいな状況なものですから、最後にそれだけ聞かせてください。","respondent":"辻田防災課長","answer":"変にいろいろこちらのほうで勧めますと、不安をあおるというような部分もありますので、その辺は慎重にしていかなければならないかなです。ただ、情報提供につきましては、私どものほうでいつでも対応できるような体制を持ってやっていきたいと考えています。","id":"exchange-021"},{"speaker":"堺委員","kind":"質問","question":"あるいはどこの学校に行っていいですかとか、その辺の調整というんですか、そこに派遣するということになると思うんですけれども。","respondent":"辻田防災課長","answer":"どこの学校に集まるかというのは、大体地域的な部分で、どこの職員がどこに集まると決めてあります。ですから、あなたはここに集まりますよということで知らせて、そしてそこに集まるような形で実施しております。","id":"exchange-022"},{"speaker":"堺委員","kind":"意見","question":"実際に学校に行って、日時が午前８時半から１２時となっていますから、９月５日は学校の授業中ですよね。あるいは現場に直接生徒を誘導するとかしないとか、そういうのは具体的な内容の訓練をやったのかどうかという、そこがもう一つとの意見を述べました。","respondent":"辻田防災課長","answer":"あらかじめ私どものほうは学校の校長先生、教頭先生に、来ましたらこういう形で対応していただきたいということでお願いしています。話し合いをしながら、大体学校を１２時過ぎに出て、そしてもう一度西大井広場の訓練会場に集まるという形で全体の訓練と内容はしております。","id":"exchange-023"},{"speaker":"堺委員","kind":"確認","question":"指定されたときに指定された学校に行けるかどうか行って、学校ではそれぞれの場所の確認というだけですね、当然今言っていることは。備蓄倉庫の中でどういう状況であったとか、そういうようなこともやったのかなというふうに思ったので、それでお尋ねしました。","respondent":"辻田防災課長","answer":"いわゆるまず確認と、そこで連携をつなげておくというような形の訓練で、それからそこでほかの訓練を入れるというようなことについては実施しません。それを１回きちんとやりまして…","id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"大体１０時ぐらいまで今のお話ですとおられたようですから、その学校以外の地域の、そんなのも可能ならどうかなと思ってきたんですけれども。その辺はざっくばらんに。","respondent":"辻田防災課長","answer":"今後、そういうようなことも入れながら訓練していきたいなというふうに考えております。全員集まったところで確認作業であるとか、そういうようなことが行われますので、それなりに時間はかかってしまうというようなことがあります。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"仮定の話なんですけれども、新米というか、わかりませんので、例えば区長が負傷、助役も負傷、防災課長も負傷で、６キロ圏内の幹部職員が全部負傷で、負傷していない幹部職員が電車が交通機関が寸断されていて来れませんとなった場合に、指揮系統というのは、ちゃんと確立されているんか尋ねました。","respondent":"辻田防災課長","answer":"なかなか考えづらい想定なわけですけれども、決してないとは言えない。訓練を実施しておりまして、係長ないし職員が当面の対応をしなくちゃならないという、そういう認識は持ってあります。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"職員の皆さんの中にも家族がいらっしゃると思うんですけれども、家族も負傷している場合に、役所のほうに来るか、負傷した家族の面倒を見るか、どちらを優先させるのかという指導みたいなものはあるんか尋ねました。","respondent":"辻田防災課長","answer":"それから、次に家族の安否を確認し、そして負傷者がいれば、それに対応する。万全とは言えないけれども、区のほうに駆けつけていただくということで私どものほうは考えておりますし、そういう形での取り扱いを含んでおります。","id":"exchange-027"},{"speaker":"石田副委員長","kind":"確認","question":"一つだけ確認で教えてください。何名ぐらい医師が参加して、どのようなトリアージを行ったのか、それだけちょっと説明を求めました。","respondent":"辻田防災課長","answer":"保健所は５名の方ですけれども、医師としては、現場で実施したのは１名。それから、職員がそこに補助的な形で３人ばかりついたという形で実施をしております。","id":"exchange-028"},{"speaker":"石田副委員長","kind":"質問","question":"トリアージ対応はやったということで理解していいんか尋ねました。","respondent":"辻田防災課長","answer":"そうです。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"貸付で３４０件余りということなんですけれども、ここでの区が紹介したときに審査をした部分と、実際に金融機関に行ったときの断られる理由というか。その辺がわかれば。","respondent":"市川産業振興課長","answer":"このあっせんと融資実行の差ですけれども、まず、年末の緊急融資を利用なさるお客様の９８％が信用保証制度を利用なさっています。これは、返済不安ということも一番大きな理由ですけれども、次に多いのが、使用目的の違いというものがそれなりの件数を出てあります。","id":"exchange-030"},{"speaker":"菊地委員","kind":"質問","question":"まちの中に入るとよく聞く話なんですけれども、据え置き期間の１２カ月というのをさらに延長するような形というのはとれないものなんでしょうか。それの期間をさらに延長するような交渉というものか、区の体制というのか、そういうものはできないものか尋ねました。","respondent":"市川産業振興課長","answer":"この５００万円に対して５年６カ月で据え置き１２カ月というのは、ほぼ妥当な水準だとは思ってあります。今年度の緊急資金はこういう形で打たせていただきますけれども、ご利用なさる方の動向などを見て、今後の参考にさせていただきたいと思います。","id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"例えば返済不能になっていて、それも回収できないというのが、要するにその現状をちょっと教えてほしいと求めました。どうなんか尋ねました。","respondent":"市川産業振興課長","answer":"今、申し上げた中で、平成１０年の４０億というのがこれまで区の実施した中で飛び抜けてすごい数字が出てしまったわけですけれども。最近の特徴は、この４年間打つ中で、必ず新規のお客さんが３分の１近くが出てきております。","id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"先ほどの数字だけをトータルしても、約８５億ぐらいのそれぞれの規模の中で、中小企業が一生懸命に返して努力されている。今後も引き続いて努力していただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"本田委員","kind":"質問","question":"一つだけお尋ねします。ＰＲなんですけど品川の産業ニュース、これはどういう意図で区内の商工業者の方々のほうに郵送するようになっているのか尋ねました。","respondent":"市川産業振興課長","answer":"現在約２万８,０００部発行していますが、シルバー人材センターを経由して、各事業所に直接に個別配付をいたしています。この緊急資金の個別のチラシを置かせていただきまして、このような、なるべく各事業者の方に情報が届くようなＰＲを進めてまいったところです。","id":"exchange-034"},{"speaker":"本田委員","kind":"質問・要望","question":"どういうことなんだろうと、いろんな方々が、しかも品川区の身近なところでの商工業者のニーズを求めているという人というのもあると思うんですね。ですから、いろいろな情報を発信してご利用いただくという姿勢が必要だと思うんですけれども、どういうふうに思うんか尋ねました。","respondent":"市川産業振興課長","answer":"いわゆる風俗関係とかそういうもの以外は、１年に１回、手持ちのカードと、それからタウンページの情報とすり合わせて更新をしています。カードを新規作成をしていくような対応をとっておりますが、今後そのようなことがないように対応させていただきたいと思います。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"それで、質問なんですけれども、まず１点は、保証協会の事故率が少ないというのは、保証協会の代弁差益が少ないということなんでしょうか。それぞれ平成１２年度が７４％という、これは平成１１年度よりも下がっているのか尋ねました。","respondent":"市川産業振興課長","answer":"２番目のお尋ねは、この４年間の推移を説明させていただきましたけれども、融資実行率だけは年々低くなってきてあります。いろいろ問題を抱えている方も含めて申し込みに来ていただいているということが実行率の悪さにつながっている、こういうように受けとめております。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"簡単でいいんですけれども、融資の実行、産業ニュースを見て、融資を受けたい方が、課長がいらっしゃるところに初めて伺いますよね。伺いますよね。","respondent":"市川産業振興課長","answer":"大体最近は１件当たりの相談時間が長くなりまして、２０分ないし３０分ぐらいやりとりをする。その上で、次に正式な書類を持参していただいて、発行状を出すというような手順になります。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"５００万円なら５００万円、いいですよと書いてくださいますよね。融資のオーケー、紹介状を出すか出さないかを中小企業診断士がやるのか尋ねました。","respondent":"市川産業振興課長","answer":"のアドバイスをする、５００万円を借りるこういうお金というのはもっと有効に使えるのじゃないですかとか、そういうお話を中心にしています。ケースに応じて必要なアドバイス、少しでも事業資金を役立てていただきたい、こういう趣旨から経営相談を行っているものです。","id":"exchange-038"},{"speaker":"金高委員","kind":"質問・要望","question":"紹介状ですか、それを保証協会、銀行とか融資相談という流れですね。区のほうにいただきたいんですけれども、どうですかという、審査ができるのか尋ねました。","respondent":"市川産業振興課長","answer":"これは事業者と金融機関のやはり関係と申しましょうか、そういう事実があります。ただ、実際の取り引きとか資金調達する場面では、結構日常化している場面ではないかと思います。","id":"exchange-039"},{"speaker":"金高委員","kind":"確認","question":"再確認だけ、そうすると、そういうのがあった場合には、区のほうの要するに利子補給とか、保証料の補助とか、そういうのは可能だというふうに解釈してよろしいか尋ねました。","respondent":"市川産業振興課長","answer":"もともと区の制度融資をお使いになるということで、お話がこうやって持って来られれば、これは後先逆になっても、私どもは要するに、先に話をつけたかつけていないかというのは、私どものカウンターの中から見えない話ですので、それはご心配要らないと思います。","id":"exchange-040"},{"speaker":"堺委員","kind":"質問・要望","question":"参考までに教えていただきたいのですが、これは昨年の実績で、３４０件で１３億３,０００万円という形ですね。あるいは、資金の使途として運転資金または設備資金（併用可）となっていますけれども、これの内訳、この辺は明確に把握しているんか尋ねました。","respondent":"市川産業振興課長","answer":"飲食業が１０％ぐらい、あと、その他と。もう恐らく９割を超す使用目的は運転資金です。","id":"exchange-041"},{"speaker":"堺委員","kind":"質問","question":"ただ、年末なんか併用可でもやっぱり全体的に運転資金ということの中身というか、その辺はどうなんですか。併用で申請してくる人はいないということか尋ねました。","respondent":"市川産業振興課長","answer":"さっき申し上げたように、まずこの年末緊急資金で設備資金を使う方というのは、恐らく５％ぐらいだと思います。１,０００万円から１,５００万円ぐらいの何か設備投資をしたいというときに、５００万円の中で設備もやって、実際には余りございません。","id":"exchange-042"},{"speaker":"堺委員","kind":"質問","question":"年間の利用内訳で、製造業で２８％ですか、あとは建設業その他の内訳がなかったんですが、どの程度かつかんでおられますか。","respondent":"市川産業振興課長","answer":"ただ、飲食業がさっき１０％程度と申し上げましたけれども、そんなに率は変わらないぐらいです。それから建設、不動産、こういったところでほぼ大半を占めてしまうというような構成状況になってあります。","id":"exchange-043"},{"speaker":"本田委員","kind":"質問","question":"先ほど換気所の件については報告、説明をいただきまして、また地元説明会が始まってまいりますので、今日は再質問はいたしません。一応先ほどの説明で、言っていたとおりだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"菊地委員","kind":"質問","question":"前回でしたか、ご説明いただいたときに、９月１７日の辺でもって、区のほうから意見を上げていくというのがありましたけれども、その日程関係をちょっと教えていただけますか。","respondent":"金井環境課長","answer":"ですから、基本的に私どものほうで今後の予定として、１０月中ぐらいに区長の意見の提出時期が来るかなと。これらを参考にしまして１２月から１月ごろ知事意見が出されて、事業主が４月ごろまでに環境影響の充実も、こういう流れになっております。","id":"exchange-045"},{"speaker":"菊地委員","kind":"確認","question":"請願に対する問題でちょっと確認だけしておきたいんですけれども、この学習会を通じて改めて論議をして、決めていきましょうと。その辺が確認方というか、実際にはそういう意見がありましたら、その辺はまだ今の時点では確認されなかったという解釈でよろしいのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"南委員長","kind":"確認","question":"重たい内容で、分量との関係で、もう一度意見書の内容で皆さんのご意見を伺って出していけるものであれば出していきたいなというふうに思っています。ですから、その時期がじゃあいつにするのかということですから、あるいはおそくても１月中ぐらいには出していきたいというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"本田委員","kind":"提案","question":"私の要望としましては、この議定書問題について議論する議題としてぜひ提案していただいて、一定の方向を出しながらさらに話を前に進めて。その先に行くかは正副委員長の一任にいたしたいというふうに思っておりますので、そんな扱いでいかがかなと思うんですがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"原委員","kind":"意見","question":"どういうものか、間に合うかどうかは別として、状況をみていくということでいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"金高委員","kind":"質問","question":"昼間の本部態勢９９名という今の報告だったんですけれども、いわゆる作業服というんですか、そういうのを全部身を包んでの仕事をしながらの態勢ということか尋ねました。","respondent":"辻田防災課長","answer":"この監視態勢につきましても、水防第１次配備態勢になりますと、当然そこに従事する職員は全員防災服を着ます。ただ、この日は特にこのほかに９９名以外にも勤務時間中であったということもありますので、事前に防災服を着用しながら執務をしたという状況です。","id":"exchange-050"},{"speaker":"本田委員","kind":"質問","question":"１５号のほうですけれども、目黒川が近いもんですから、防災無線が非常に聞きにくいですよね。東京にも警報が出ているわけですから、あれは品川のテレビに５チャンネルで、テロップでも流せるようなことができないだろうか。","respondent":"辻田防災課長","answer":"本当の災害のときは、音量を上げて放送するということを予定しておりますけれども、そういうことも今後考えなければならない。それにも対応できるような体制を組んで実施していくです。","id":"exchange-051"},{"speaker":"本田委員","kind":"質問・要望","question":"集中的に品川が降って立会川があふれるというようなことが起きるような気象状況になってきているわけですから、もっとこれは検討していただきたいなということを、感じましたので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"原委員","kind":"質問","question":"うちにも電話があって、何を言っているかわからない。今後の中でもうちょっと、あれは町会長あるいは地域の各町会のところには有線か何かで行っているのか尋ねました。","respondent":"辻田防災課長","answer":"私どものほうも何とかしたいというぐあいに考えておりますので、ただ、いわゆる役場式の防災無線は今後も活躍する場面はたくさんあると思います。そういうことで、補完の方法をいろんな形で考えていければと思います。","id":"exchange-053","title":"町会・自治会支援"},{"speaker":"原委員","kind":"質問・要望","question":"今後も含めて、検討してほしいと求めましたし、それからもう一つ、先ほど目黒川が１０時に警戒水位になってきたというようなお話でしたね。それは今回使われたのか、使われないのか、それともう一つは、どこの時点でそれを使うような形にとられているのか、ちょっとそこのところを。","respondent":"辻田防災課長","answer":"２５万ｔ入るところを約５分の１の５万ｔぐらいあそこの中に入ったです。〔「今回は５万ｔ」と呼ぶ者あり〕大体５万ｔ入ったということです。","id":"exchange-054"},{"speaker":"菊地委員","kind":"質問","question":"一つだけちょっとお聞きしておきたいんです。今回の委員会で出るのかなと思っていたんですけれども、ちょっといまだに出ていないんですけれども、経過をお願いします。","respondent":"市川産業振興課長","answer":"作業がおくれてすみません、今印刷所のほうで校正をしている最中でございまして、でき次第、特に区民の皆様方にはただちにお届けできると。最終的にゴーサインを出してから１週間ぐらいということですので、なるべく早くお届けするようにいたします。","id":"exchange-055"},{"speaker":"石田副委員長","kind":"質問","question":"私はＩＳＯ１４００１のことはよくわからないのですが、紙まで全部分けているとか、いろいろやっていますね。ああいうすごい厳しい、そこまで品川区が段階的にやっていこうという将来お考えなんか尋ねました。","respondent":"宍戸ＩＳＯ担当課長","answer":"外部の説明や何かにきちっと説明できるようにするということが、今、副委員長のおっしゃったようなことをなさっているんだと思います。棚まできちっとしてというふうな、違う手法ではありますけれども、やはり紙の使用枚数については把握に努めているです。","id":"exchange-056"},{"speaker":"原委員","kind":"意見","question":"彦根で４項目、割合目標が決まっていて、まとめやすいんじゃないか。そう思うんですが、ほかの方のご意見はとの意見を述べました。","respondent":"南委員長","answer":"いいでしょうか、そういう方法で、１人一つずつ分担をしていただいて、報告書として。最終的な責任は、正副にあるわけですけれども。","id":"exchange-057"},{"speaker":"原委員","kind":"意見","question":"そういうところは１回やっぱり出していただいて、まとまって、ここにはこういうものがあった、こういうふうに感じたという。〔「後で検討会をするという」と呼ぶ者あり〕それを入れておけば、委員の中で自由に広がると思うとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"石田副委員長","kind":"意見","question":"皆さんにそれにつけ加えるものとか、これは私はこういうふうに思いましたという意見交換みたいなものをやってから製本をしましょうという形ですので。我々の業界では玉鳥というんですが、そういう項目をどうぞお一人ずつとっていただければと思うんですがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"原委員","kind":"意見","question":"それかあるいはくじ引きじゃないけれども、どうしても、それは好きなところでやるほうもやりやすいかもしれませんけれどもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"石田副委員長","kind":"質問","question":"私から勝手に言っていいですか。ここの懇談会のまとめをもし正副でやれということであれば、正副で必ず足助を入れてほしいな。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"本田委員","kind":"質問","question":"きょうは、京都と言ったもんですから、ある程度環境問題で、地球環境のことで書かなくちゃいけないんですが。〔「お知恵を拝借に参りますので、そのときには」と呼ぶ者あり〕資料には目を通しておきますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"石田副委員長","kind":"質問","question":"黒壁と東大阪ですから、ものづくり。懇談会はこちらでまとめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":52570,"voices":189}},{"id":"h13-20010926-7","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"厚生委員会","time":"午前１０時０６分～午後 ４時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"第１に、そしてまたこういうことがあるんだから犯罪を犯したら捕まってしまうなというようなことで抑止効果を発生させるということなんでしょうか。そこがどうなっているのかお伺いします。","respondent":"谷田部児童課長","answer":"それからこういう施設にはこういう装置が入っているということを明確にすることによって一定の抑止効果を出すということを考えてあります。ですから、例えば目立つところにこういう装置のステッカーを張るですとか…","id":"exchange-001"},{"speaker":"船波委員","kind":"質問","question":"もう一つ。補助対象外の施設は別途安全策を構築するということですけれど、どういったことが考えられているのか、現時点でのプランをお伺いします。","respondent":"谷田部児童課長","answer":"今、警備会社のほうからその事件の発生があったかないか、ワンクッション置かざるを得ないような形になってあります。ですから、この装置とは、万全な体制で私ども対応はしていきたいというふうに思ってあります。","id":"exchange-002"},{"speaker":"鶴副委員長","kind":"質問","question":"その５０名なら５０名、指揮命令系統というのがあって、指示なしには消防署だって動かないじゃないですか。指示がなければ消さない、そういう仕組みになっているじゃないか尋ねました。","respondent":"谷田部児童課長","answer":"この装置を設置する管理責任者ということで、それぞれの氏名を報告して警視庁のほうに承認をいただくという仕組みになってあります。園長のほうと連携をとりながら、園長を含めて、その辺で対応していくというような流れになってあります。","id":"exchange-003"},{"speaker":"鶴副委員長","kind":"意見","question":"どの程度のものだったら非常事態というふうに判断して館長とか園長がしかるべきところに、最初は警備会社に通報するのかということですね。その非常事態という判断の基準ですよとの意見を述べました。","respondent":"谷田部児童課長","answer":"そういう人が入った場合にどういう対応をするのかですけれども、やはり何らかの不審な行動といいますか。私ども日常の館内の安全管理の面で、児童センターを長く運営していますので、その辺は十分対応ができるというふうに思ってあります。","id":"exchange-004"},{"speaker":"鶴副委員長","kind":"質問","question":"どうしてもそれがだれかを子供を人質にして刃物を突きつけて一歩も引かないというような場合には、狙撃だってあるかもしれないじゃないですか。そこらあたりのどこまで普及徹底、今回の１１０番制度に伴っての対応措置というのは、いかがか尋ねました。","respondent":"谷田部児童課長","answer":"ここの施設にはこのような装置が設置されているというような部分でのＰＲ、設置した後、日常の非常通報とはまた違った対応になろうかと思いますので。ですから、こういうものが設置されているというのは…","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"例えば５０名規模の警官が来てくれればそれはありがたいのですが、例えば施設の大きさとか、それが例えば５０名で必ずしもそれがいいのかどうか。そういうふうなことはお考えにならなかったのでしょうかということをお伺いしたいのと、そういうことを考えていくと、その辺はいかがか尋ねました。","respondent":"谷田部児童課長","answer":"こちらのほうを使って児童の安全管理配備をしていきたいというふうなことで別途違うシステムを考えていきたいということがまず第１点です。私どもこの池田小事件が起こる起こらないの以前から、お子さんの人命をまず第一に考えろということで指導してまいりました。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"施設の大きなところに５０名来るのはいいのですけれども、例えば小さな施設に５０名が来て、それは考え直しなさいよと。５人でもいいですよとか、相当変わってくる可能性があるんじゃないですかということをお伺いしていますので、もう一度ご答弁をお願いいたします。","respondent":"谷田部児童課長","answer":"児童センターの場合、実際に保育園に５０名の警官が駆けつけた場合にうまく対応できるのかというのは確かに委員がおっしゃるとおり疑問もあります。面積、そういうような非常事態の場合にどういう対応をするかというのはこれから警視庁のほうが詰めていくというふうに私どもは考…","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"何も５０名という頭があるから動かないのではなくて、池田小学校の事件は１人の犯人だったわけですから、そういうふうなことを考えていきますと。お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"嶋委員","kind":"質問","question":"これは基本的に考えてこのまま１施設２カ所という認識でよろしいのか、この施設の大小に係ってこの設置場所が数が減ったりふえたりとかするのかどうか、ちょっとお聞きをいたします。","respondent":"谷田部児童課長","answer":"基本的には１施設に２カ所の非常ボタンを設置するというのが一つの仕組みになっています。ただし、例えば複数階の建物で各フロアに１カ所欲しいといった場合には、それはそれで増設が可能だというふうになってあります。","id":"exchange-009"},{"speaker":"嶋委員","kind":"質問","question":"そうお聞きをして安心をいたしました。その大小があると思いますので、ぜひ安全対策で本当に子供たちが安心して学校生活また保育園とかで生活ができるようにお願いをしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから押しやすく押しにくい場所を探さなきゃいけないよというような判断になろうかと思うんだけど、こういうシステムができた場合に。何か不審者が来れば電話で、考え方というのも整理しておいていただきたいのと、そういったところもを含めてひとつＰＲもお願いしたいと思います。","respondent":"谷田部児童課長、日下部障害者福祉課長","answer":"そのときにもし誤報だったら電話を取って、警視庁からの逆信に対して、今のは間違いでしたというような対応もまず１点とれると。この辺のＰＲの方法につきましては所管の関係課と集まりまして… その他の福祉施設での対応についてのお尋ねですけれども、今回のこの学校１１０番の設置の対象といいますか、これが対象になっております。それはそれで対応できると、今回の非常通報のようなそういう仕組みはあえてとらないと…","id":"exchange-011"},{"speaker":"船波委員","kind":"質問","question":"９月１８日に住民説明会をしたということですけれども、これはどういったところへ呼びかけて参加を募ったのか尋ねました。","respondent":"谷田部児童課長","answer":"公園改良の場合、その改良する場所を中心として半径２００ｍとか３００ｍの範囲内の方に大体個別にチラシを入れたり、その町会の回覧板を使う。それから品川第２地域センターの管轄になりますが…","id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"それから、それ以外にどんなことがあったのでしょうか。了承されないというか、疑問を呈されたというようなことは、ホームレス対策以外にどんなことがあったのかを伺います。","respondent":"谷田部児童課長","answer":"その方々からフェンスは見通せないようなフェンスにしてほしいとか、それからうちは網の目で見えるようにしてほしいとか、いろいろ要望があります。そういった細かい要望等もありましたので…","id":"exchange-013"},{"speaker":"船波委員","kind":"質問","question":"土の部分もあれば、周囲はそういったものになっているといった話も聞いたのですが、その通路の部分は浸透性のものにするといったものなのでしょうか。土の部分と浸透性にした部分、どういう理由でそういうふうに分けたのか、その辺をお伺いします。","respondent":"谷田部児童課長","answer":"先ほどの説明で、その方々が通行しやすい材質を考えなければならないという部分で、そちらのほうで整備すると。これから図面を起こして、実際に通行上支障がない幅は何ｍぐらい確保したらいいかどうかというのもこれから検討しなければならないという部分です。","id":"exchange-014"},{"speaker":"鶴副委員長","kind":"質問","question":"ちょっと気になったことだけをお伺いしておきたいんですけれども、桜の木を含めて、あそこの樹木は何本ありますかね。そこのところをちょっと答えていただけませんか。","respondent":"谷田部児童課長","answer":"ですからしばらく木登りできるまでというと、現存する大木が２本ありますので、そちらを利用して木登りができる。当然登ることができませんから、登れるような踏み台を用意するとか、そういうことで木に登ってもらおうかというふうに考えてあります。","id":"exchange-015"},{"speaker":"鶴副委員長","kind":"質問","question":"そういうふうな工夫をいろんな専門家とも話をしていただいて、ぜひ夢のある冒険の広場にしてもらいたいというふうに思っているのです。今お話聞きましたら、高木で４４本、低木で２９９本、ここにはどんな鳥が来ているか尋ねました。","respondent":"谷田部児童課長","answer":"鳥を観察した結果はございませんので、どんな鳥が来ているかはわかりませんが、私が行ったときにはハトとスズメが公園の中にいたです。","id":"exchange-016"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"でも、あそこをどういうふうにするかはわかりませんが、障害を持った児童たちが車椅子で泥遊びができる場所をつくってほしいんですよ。いや、ハンディを持った子供たちもここで遊べる冒険公園にしてもらえないかという希望を私は持っているんですが、その点はいかがか尋ねました。","respondent":"谷田部児童課長","answer":"障害をお持ちのお子さんも、例えば車椅子から降りて泥にまみれてということは、当然介助の方もいらっしゃるでしょうから。私ども遊びを指導する者も必要に応じて配置しますので、その中で介助しながら遊べるというようなことも考えていきたいというふうに思ってあります。","id":"exchange-017"},{"speaker":"鶴副委員長","kind":"質問","question":"車椅子で遊べる泥んこ遊びのできる施設というのを、大々的なものではありませんが、文献でもいいですからごらんになったことはありますか。","respondent":"谷田部児童課長","answer":"ちょっと私どもは見たことはございません。","id":"exchange-018"},{"speaker":"鶴副委員長","kind":"提案","question":"工夫して歩いてもらえばいい、だったらバリアフリーなんかもすることはないじゃないですか。そういうことで申し上げましたので、もう一回１０月に設計をなさるわけですから、設計が終わったら設計を変更するのは厳しいことでしょうからとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"二つお伺いいたします。幅８０cm、せっかくこういう立派なものをつくっていくわけですから、特に道路公園課のノウハウを持っているはずですから。","respondent":"谷田部児童課長","answer":"説明会でも子供たちは全然遊んでいないじゃないか、なんでこんなのをつくるのだというようなご意見も確かにいただきました。そういうような形で何とか間接的なホームレス対策というのをこの広場でやっていきたいというふうに考えてあります。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問・要望","question":"一見矛盾するような話かもしれませんけれども、確認ですけれど、道路公園課はいろんなアイデアを持っているはずです。そういうようなものを十分踏まえて対応していっていただきたいと思うのですが、その辺の対応と確認はいかがか尋ねました。","respondent":"谷田部児童課長","answer":"住民説明会でもホームレス対策というのが随分言われたところです。ホームレスの定住化の阻止に向けて、これから具体的な図面を引くわけですから、その中でホームレス対策を考えていきたいというふうに思ってあります。","id":"exchange-021"},{"speaker":"嶋委員","kind":"質問・要望","question":"まず開園時間をお聞きしたいということと、それからあとやはりもしできましたら電話ボックス、電話をかけられる体制にぜひしていただきたい。考えていらっしゃるかどうかということと、目黒川のほうには駐輪場を考えていらっしゃるのかどうかをお聞きしたいと思います。","respondent":"谷田部児童課長","answer":"それから決まった時間には家にちゃんと帰るとか、ある程度決まりの中での遊びですから、その辺は当然公園ですから時計はつける予定です。多分公園内には公衆電話の新設は難しいだろうというふうに思ってあります。","id":"exchange-022"},{"speaker":"嶋委員","kind":"質問・要望","question":"やはり子供たちは低学年が遊ぶとなるとやはり電話を家にかけたりとかすることがあるので、ぜひ電話をつけていただきたいことを要望したいと思います。それから、これを見ますと大分花壇があるのですが、この花壇は全部下に定置というか、下につける花壇の想定でいらっしゃるのか尋ねました。","respondent":"谷田部児童課長","answer":"今のところプランターではなくて、路地で植えて、直接土に植えるということで考えてあります。本当に冒険広場ができるのかという話になりますけれども、そういうご要望を少しでも生かす形で考えていきたいというふうに思ってあります。","id":"exchange-023"},{"speaker":"嶋委員","kind":"質問・要望","question":"全部路地ではなくて、そうやった手入れも楽にできるような花壇がありますので、ぜひそれは要望したいと思います。こういう意味での交通安全対策などは考えていらっしゃるのか、ちょっとお聞きしたいと思います。","respondent":"谷田部児童課長","answer":"ただ想像できるのは、あそこの橋をおりてきた車が坂をおりてすぐの場所になるんですね。その辺はちょっと確認をさせていただいた上で横断歩道等が設置できれば設置につきまして働きかけをしていきたいというふうに思ってあります。","id":"exchange-024"},{"speaker":"嶋委員","kind":"意見","question":"車を運転する方も、私もきのうあんなにそばに公園があるのを本当に申しわけなく知らなかったんですけれど、車の方たちがこの横に公園があって子供たちがいつ飛び出してもおかしくないというような危険予知ができるような安全対策をぜひお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１日何人ぐらいということで目標にしてこのボランティアを組織しようとしているのかということを一つ教えてください。火おこしができるということなんですけど、その中で管理というところではどういうふうにされていくのかということについて説明を求めました。","respondent":"谷田部児童課長","answer":"それから２点目の、がちっと毎日必ず１人つける２人つけるではなくて、活動できる範囲の中でやっていただくと。大人たちがよその子でもいけないことをしたら叱れるような、そういった形で運営できないかというのをまず基本として考えています。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、それは結局物品の部分の予算というのだけというふうな状況になるのでしょうかということをお聞かせください。トラブルというのがあって、毎日入るかどうかもわからないというふうなそういうところでは、そこら辺のところではどう考えられているか尋ねました。","respondent":"谷田部児童課長","answer":"例えば巣箱をつくって木にかけてみるような行事も取り組みができるというふうに思ってあります。特に公園近辺の方々が、当然信頼関係はもうでき上がっているという意味ではぜひそういう形でやっていただきたいと思ってあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"火は使えるというふうなところでは結局ボランティアの方がいるときにはそれを貸し出して火を使うということができるという状況になるわけですよね。そうすると、そういうふうなところまで全部そのボランティアの方が責任を持って最後まで後始末をするという、そういうことになるんか尋ねました。","respondent":"谷田部児童課長","answer":"子供が火をつけたら自分で消すと、最後まで。何でもかんでもボランティア任せということではなくて、まず子供たちがそういう責任を持った上で十分に遊ぶということが今回の広場のコンセプトです。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その子供たちにそういうことを教えていくというふうなところが、世田谷なんかではそういうところでプレイリーダーがそういう形で責任を持つというところまできちんと教えていくというふうな体制になっていると思うんですが、そこら辺の体制がこういう無償の。","respondent":"谷田部児童課長","answer":"区が設置して、子供たちに遊んでもらうということで、何かあれば区が最終的な責任を負う。それをすべてボランティアの責任だということはあり得ません。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当に公園にすぐ密接しているというふうなところで、そこのところでもしも万が一火災とか何かが発生するというふうなことになったら大変だなというふうな思いがあったのでずっとお聞きしているんですけれども、そういうふうなところはどうお考えか尋ねました。","respondent":"谷田部児童課長","answer":"住民説明会で、火おこし体験ができるということを私どもは強調してご説明申し上げました。子供たちの遊びを阻害しない範囲で地域の皆さん方がやるのであれば、それは責任を持ってやっていただくということでお願い申し上げています。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。本当にそういうところでは管理も含めて子供たちが本当に伸び伸びと遊んでいけるようにきちんとやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"須藤委員","kind":"質問・要望","question":"やはり子供の広場という表現をしても、品川区全体の住環境としては高齢者が多くなってきているわけですから、お願いしたいと思います。そういったいろんなところに公園ができてくるので、一番最初にお話したように、その辺の方向性を見せていただければというふうに思います。","respondent":"谷田部児童課長","answer":"１点目の子供の数ということですけれども、決して子供が減っているということではなくて、それなりにいるというふうに認識しています。この辺から落ちたら大丈夫だと、そこまでは子供に任せようというような多分配慮もできると思いますので…","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その内訳、その内訳についても教えていただきたいのと、そしてそのあと毎年２回ずつ監査が入るとかいろいろありますよね。それともう一つ、２０００年版というのがもうできていると思うんですが、なぜこの古い９４年版で取られるのかについても説明を求めました。","respondent":"金子保育課長","answer":"２０００年版のお尋ねなんですけれども、先ほど申し上げましたとおり、日本語に訳したものがＪＩＳ規格であるというふうに申し上げました。それがＩＳＯの９４年版に対してＪＩＳ規格では９８年版…","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そしてあと、このマニュアルがここに１ページ、そういうところでどういうふうに日常保育をされながらそういう手順をつくられていったんでしょうか。人員配置とかされたのか、そういう人手というか、労力というのはどういうふうにして確保するというふうに考えているのかについて説明を求めました。","respondent":"金子保育課長","answer":"東五反田保育園は１０時までの夜間保育もやっているところですので、人的にはこのＩＳＯ取得ということでは１名を特別に配置しています。それから、そういう意味ではなるだけ…","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１名配置されているということなんですけれど、この１名というのは今後も続けてずっと配置が続けられていくんでしょうか。それともう一つ、具体的に親の思いというか、図られるのかというふうなあたりについて教えてほしいと求めました。","respondent":"金子保育課長","answer":"まだ私どもはそこの詳細については詰めておりませんけれども、今回１園取得して、検討してまいりたいと思っています。先ほども申し上げたとおり、そういう意味ではすべてではないにしても一定の満足度については図られていくとは考えているところです。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この９０００シリーズを取ることによってそこら辺のところが明確になっているということがあるのかどうかをお聞かせください。そのマニュアルが親も自由に見られるような形になると思うんですが、その開示というのはどのようにされるのかについて説明を求めました。","respondent":"金子保育課長","answer":"第三者評価ということで東京都の実施している部分に私どもも参加して、昨年度並びに今年度引き続き試行を実施する予定にしております。すべてが、先ほど申し上げたとおりですが…","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと今お話に出たのであわせてお聞きしちゃって、その点についてはいつぐらいにご報告をいただけるのかについて一つ教えてください。それとあと、このときに子供が一体何人いるかとかということはまた別な資料でわかるものがあるのかどうか、そのことについて説明を求めました。","respondent":"金子保育課長","answer":"当初予定ですと、大体１０月ぐらいに１３年度の第三者評価の試行をしようという予定だったのが、恐らく私の見込みですと二。この全体を０歳から５歳までをまとめたページもありますので、児童も予定によればこれだけいるということがわかるようなページをつけております。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"逆に保育が後退するようなことがないようにぜひお願いしたいということと、そういうところも含めて保育の質が、本当に親も満足できるというふうな形で保育の質が向上できるようなそういう方向でぜひご検討いただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問・要望","question":"人と人とのふれあいの部分ですから、もしくはやりませんということになったら、マニュアル化していい部分といけない部分があると思います。ですから、当然要望は違ってくるわけですから、ただどこかでそのサービス提供の担保はしていく必要がある。","respondent":"金子保育課長","answer":"ですので、それはマニュアルとは別途のところでも当然あるものだということで指導していきたいというふうに考えております。これが大前提になりますので、そういったところを大前提にしながらいろいろな保護者のニーズに対して対応していきたいというふうに考えおります。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、効果が出たということを目に見える形にしていく作業がこれから必要ではないでしょうか。ですから、それを目に見える形で表していただきたいと思うんですが、お願いできますか尋ねました。","respondent":"金子保育課長","answer":"それによって私どもが提供している日ごろの保育サービスそのものを見直し検証していくということができるというのが一つあるだろうと思うんですね。これは非常に重要なことだというふうに考えますので、その点についてはご指摘を踏まえて考えていきたいというふうに思っておりま…","id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問・要望","question":"プロセスが大切とおっしゃいました。そのプロセスをもってほかの保育園に広めていっていただきますようにここでは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"船波委員","kind":"質問","question":"この９０００シリーズに関しては、どういうことに対して、それならば認証を与えましょうということになるのでしょうか。その今年度中に認証取得したとはいっても、認証取得した後の検査・審査というのはどういうことが審査されていくのか、お伺いしたいのですが。","respondent":"金子保育課長","answer":"前段、この９０００シリーズにつきましても、つまりシステムが整っているということで評価されるというものだというふうに認識しております。それから、先ほどちょっとお話が出ました２０００年版についてもその取得については検討していきたいというふうに考えております。","id":"exchange-042"},{"speaker":"船波委員","kind":"質問","question":"たくさん製造されるその製品がある一定のレベルにそろえられている同質のものであるということに対して与えられるものなんでしょうか。このＩＳＯ９００１に関しては同じクオリティのものが提供されるようにするということが強調されているような感じがしたので、どうか尋ねました。","respondent":"金子保育課長、小沼福祉事業部長","answer":"私どもにしてみれば、やっぱり問題が次々起こってくるわけですから、それについての対応策なり対処策というのを必ず考えて実行していく。そういう意味で１４０００と全然本質的には変わらないものだというふうに考えております。 保育課長のほうからるる詳細な点の説明があったのですが、取りますと、これは本当に永続的にそれをキープしていかざるを得ません。こういうことでご理解いただければ比較的おわかりいただけるんじゃないかというふうに思ってあります。","id":"exchange-043"},{"speaker":"船波委員","kind":"質問","question":"わかりました。保護者とのかかわりということもあって、ＰＴＡとはどういう関係になっているのか、ちょっとお伺いしたいと思います。","respondent":"金子保育課長","answer":"次の報告で（仮称）ＰＴＡの部分というのは報告する予定なんですけれども、いろんなことを申し上げますと。あるいは苦情というものを的確にとらえて迅速に対応しようというふうにしている園ですので、その辺はご理解いただきたいというふうに思います。","id":"exchange-044"},{"speaker":"船波委員","kind":"質問","question":"この管理表によるともうことし４月から始まっているこの９００１取得へ向けてのさまざまな動きの中で、あるいはもうお知らせしていることとか、そういうことはどんなことが行われてきているんか尋ねました。","respondent":"小沼福祉事業部長","answer":"そこらあたりでも審査の対象となりますし、逆にＰＴＡの方々からの意見の吸収なり、あるいは応答ができるようなものが自動的になっていると。それも含めての全体の質のアップというんですか、品質向上に努めると、こういうふうにご理解いただければと思います。","id":"exchange-045"},{"speaker":"船波委員","kind":"確認","question":"ちょっと確認ですけれど、こういうふうなかかわりにしますとか、それを決めたのは区の側でこうしますとただ単に決めただけなんですか。それともその９００１のマニュアルに入れていくものの中でそういった園と保護者とのかかわりについてはこういうものを入れようと考えていますけれど…","respondent":"金子保育課長","answer":"この９００１シリーズのマニュアルを作成するに当たっては、保護者の意見をこれに反映するというふうなことは直接的にはしておりません。このＰＴＡの設立に関しては保護者から役員を募ったり…","id":"exchange-046"},{"speaker":"鶴副委員長","kind":"質問","question":"この９０００シリーズの取得については、東五反田の保育園だけか尋ねました。","respondent":"金子保育課長","answer":"１３年度で９０００シリーズ取得を目指しているのは東五反田保育園１園です。","id":"exchange-047"},{"speaker":"鶴副委員長","kind":"質問","question":"ほかのところも続々とそういう９０００シリーズの認証を取得したいという保育園が出てくれば、それにチャレンジさせるという意味なのですか。１３年度は、という意味は。","respondent":"金子保育課長","answer":"先ほど予算面のお話も申し上げたとおり、認証取得に当たっては一定程度審査登録費用等々かかります。１３年度は１園でこれを取得することを目指して、品川区の保育園全体のレベルアップを図っていこうというふうに考えているところです。","id":"exchange-048"},{"speaker":"鶴副委員長","kind":"質問","question":"ならば、どういう形でそのすばらしい品質を持っているということを知りうることができるのですか、保育園に行かなくてもわかるようになるのかです。どうなんか尋ねました。","respondent":"金子保育課長","answer":"今お話しありましたとおり、これから利用される方、あるいはその他の方々にも周知していく方法というのを考えていきたいというふうに思っております。","id":"exchange-049"},{"speaker":"鶴副委員長","kind":"質問","question":"でも、そのマニュアルはベターだと思って出しているのもにもかかわらず、それと逆行のことをする人がいるかもしれないじゃないですか。そのどういう人的資源が整っているかということについてはどうして知ることができるのですか、その片鱗でも。","respondent":"金子保育課長","answer":"私どもが目指している部分というのは、どの園もだれでも一定の保育の水準を提供できるのだというところを目指しておりますので、そうご理解いただけたらと思います。","id":"exchange-050"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"いい方向に追求、追い求める追求です。そういう体制のほうは大丈夫ですか、部長。","respondent":"金子保育課長","answer":"副委員長ご指摘の部分というのは、確かに過去においてそういう心配をせざるを得なかった場面というのはあっただろうというふうに認識しております。私は３７人の園長がいて、その下に確かに８００人ほどの職員がおりますけれども、ご理解いただければというふうに思います。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"活動等について区としても支援するということで答弁されていますけれども、その支援の具体的な中身について一つ教えていただきたいのと、それからこの保育園ＰＴＡの活動する中身というのは具体的にどんなものになると考えているのかについて説明を求めました。","respondent":"金子保育課長","answer":"例えば講師を呼んできて講師料がかかると、こういったような場合には区として一定の支援をしていこうというふうに考えています。２番目の保育園ＰＴＡの活動内容として私どもが考えているのは、その目的を達成するための必要な活動を一応活動内容としては考えているところです。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、例えば保育園行事とのＰＴＡとのかかわりというふうなところはどういうことになってくるんでしょうか。その行事なんかは保育園とＰＴＡの父母と一緒になって行事を計画をして取り組んでいくとか、そういうふうなことというのも今後出てくるんか尋ねました。","respondent":"金子保育課長","answer":"例えば運動会とかその他の保育園の行事がありますけれども、基本的にはこの（仮称）保育園ＰＴＡはかかわりはないというふうに考えております。１３年度予算で計上しているのはご指摘のとおり３０万円ですけれども…","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それとあと、そういうふうに保育園行事とは全く関わりないところでＰＴＡとして行事なり講座なりを組んでいくということになるんでしょうか。これは基本的に親が働いているというふうな状況ですから、そういうこともできるという状況になるんか尋ねました。","respondent":"金子保育課長","answer":"ＰＴＡが行事とかかわりないところで実施するのかというところですけれども、ＰＴＡが実施する事業については、基本的には任意団体でありますけれど。もう１点、職員の超勤対応ということですけれども、当然職員としては超勤対応にはなり得るというふうには考えております。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ぜひ保育者と保護者が一緒に手をつないで子供を真ん中においてよりよい保育を、子供たちにとって本当にいい保育をつくれるようにというふうなところで、そういうところもぜひ行事についての親の参加についてもご検討いただけたらというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"嶋委員","kind":"質問","question":"区のほうはこれを予想していたぐらいの数だったんでしょうか。やっぱりニーズに合って、保護者の方たちの思いがあったのかなと思いますが、そこら辺ちょっとお聞きをしたいと思います。","respondent":"金子保育課長","answer":"私ども予算を調整した段階では、先ほどちょっと申し上げたとおり、３０万円で、その内訳は６万円掛ける５園というふうに思っておりましたので、私どもとしましても予定より多いかなというふうに考えているところです。","id":"exchange-056"},{"speaker":"嶋委員","kind":"質問・要望","question":"では、大変喜んでいらっしゃるということでよろしいでしょうか。あってはならないことだと思うんですが、ちょっとそこら辺をお聞きしたいと思います。","respondent":"金子保育課長","answer":"保育園の定員が大体７０から１００ですので、園長が保護者に向けて任意の団体であるから参加するのは基本的には自由だよということでご説明するようにというふうに指示しておりますので、そのようにお伝えしていただければというふうに思います。","id":"exchange-057"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、園長に直接やはりお話が保護者ができるような体制をますます綿密にとっていただけたら大変助かりますので、要望しておきたいと思います。要望にとどめします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"鶴副委員長","kind":"質問","question":"そういうふうな、その歴史の教訓の上に立って今回のようなみんながすっきりした形で相互親睦が保てるようなＰＴＡという組織ができたわけですから。それを超えているということはとてもいいことだし、今後の展望は煮上がっている絵があるのですか、今。","respondent":"金子保育課長","answer":"一定の活動方針の中でやってもらわなければいけないというふうに考えておりまして、私どもは各園の規約についてすべてチェックしておりまして。今後の私どもの考えとしては、３年ないし４年のうちに全園で設置できればというふうに考えております。","id":"exchange-059"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それは切りわけていきますと、今保育課長から説明があったように、運営方針に協力するということが３項目に入っております。ですから、不介入ということはなかなか難しいでしょうから、その二つご答弁いただければありがたいです。","respondent":"金子保育課長","answer":"それも委員ご指摘のとおり、基本的には園の運営に関しては不介入であるというふうなことで考えているところです。職員の認識状況、先ほど申し上げたとおり、３年ないし４年のうちにはすべての園で実施していきたいというふうに考えているところです。","id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、それから有効な関係をつくっていきましょうということですから、逆に品川区が引っ張っていくぐらいの思いを持ってほしいんですよ。ある意味苦労、それからいろんな思いがあるでしょうから、むしろこちらのほうから仕掛けていくぐらいの思いがあってもいいんじゃないか尋ねました。","respondent":"金子保育課長","answer":"私どもとしては、そういう意味では１０以上までは難しいかなと思っていましたので、一応８園に絞って今年度は実施していきたいと思ったところです。私どもとしましても、あるいは委員のご指摘を踏まえながら…","id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問・要望","question":"簡単に要望だけしておきますけれども、相当このことについては今まで議論もありましたし、それからいろんな要求も実際あったことも事実です。一つの回答がこれですから、今言った保育課長の答弁を踏まえてそれで進めていっていただきますように要望しておきますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの進行状況の中で、このＰＴＡ設立のお知らせというのは品川区でつくった文書とかそういうのがあるのでしょうか。そのことが１点と、また、会員の保護者をどうふやしていくかというところではどういうふうに考えられているのかについて説明を求めました。","respondent":"金子保育課長","answer":"小山台保育園が２２名として少ない理由ですけれども、小山台は過去、そういう意味ではその残滓があるのかなというふうに想像はしております。この事業内容を実際に見ていただいてお考えいただくということが非常に重要な要素ということで指示していきたいというふうに思っており…","id":"exchange-063"},{"speaker":"鶴副委員長","kind":"質問","question":"拒絶反応どころか、私たちが食い込んでいける余地があるみたいなことをインターネットを通じて呼びかけている人もいるぐらいですから。それぞれの自発的な活動ですから、そこまでをだれも規制することもないわけですし、自由にやっていただければいいことだから、だから全員が入る……。","respondent":"林（和）委員長、田中健康課長","answer":"ほかに。ないようですので、これで４番目の（仮称）保育園ＰＴＡ設立についての報告を終了いたします。 続きまして、５番目の、乳がん検診マンモコースについて、理事者からご説明を願います。 乳がんの検診につきましては、従来から昭和５０年度以来実施をしていますけれども、設けることにいたしました。月１回… 続きまして、６番目のＣ型肝炎ウィルス抗体検査の実施について、健康課長、同じですので、一緒に説明願いまして、一括して質疑したいと思います。…","id":"exchange-064"},{"speaker":"船波委員","kind":"質問","question":"一般コースもあるのに、マンモコースのほうを新設されて、最初からマンモグラフィの検査をするというのもあると。視診、その辺はどういうふうにこの二つがあるということを広報したり、どうして決断すればいいかということをどうやってお知らせするんか尋ねました。","respondent":"田中健康課長","answer":"そのうちでこの精検に１,２８１名の方が受けて、１６名の方の結果ががん、あるいは疑わしい結果が出てあります。ですから、いわゆる精度管理のあり方をどうしていくかということを含めて研究してまいりたいというふうには考えてあります。","id":"exchange-065"},{"speaker":"船波委員","kind":"質問","question":"こういったことがもうすぐ１０月から実施ということですけれども、どちらか年に１回受けてくださいという場合に、それほど不安に思っていない人は無料の現行のコースでもいいですよというようなお知らせになるんか尋ねました。","respondent":"田中健康課長","answer":"ある意味では本当の意味で体制が、いわゆる一般的なところの数をこなせるところまでいくかどうかという物理的な問題もあります。この状況に合わせてご自分の不安、それから一般的な診断という形で受けていただく選択肢かというふうに認識しております。","id":"exchange-066"},{"speaker":"船波委員","kind":"質問","question":"これはちょっと私の知識を知りたいというところでご質問するだけなんですが、Ｂ、ＢとＣはウィルスの型が違うというだけの違いなんでしょうか。今回Ｃ型の検査を始めるということですけれど、それではＢ型はどうなんでしょうかということをお伺いしたいと思います。","respondent":"青山品川区保健センター所長","answer":"それに対して、特に対策のおくれていたＣ型肝炎に対する対応を今厚生労働省が極めて急いでいるというところがあります。今回とりあえず希望する方に対しましては一般健康相談の中でＣ型の検査ができるようにということで取り入れたというところがあります。","id":"exchange-067"},{"speaker":"嶋委員","kind":"質問・要望","question":"１年の無料のほうはお誕生日の月に郵送されてきますが、東京都のがんセンターで受ける場合は希望者を募って予約をいたしますよね。そういう方式になっていくのか、ちょっと教えていただきたい。","respondent":"田中健康課長","answer":"両方のコースが選択できるようにということでとりあえずはダイレクトメールは差し上げたいと思います。ただ、その中で周知を図っていきたい、その中で選択をしていただきたいというふうに考えてあります。","id":"exchange-068"},{"speaker":"嶋委員","kind":"質問","question":"先ほどもいろんな関係で月１回１５名程度、両方で３０名ということになると、もし電話をしてもどういう方向……。すみません、電話か郵送かというのをちょっと説明を求めました。","respondent":"田中健康課長","answer":"両医師会のほうへ電話等で申し込みをいただくということになってございまして、現在月１回という形でとりあえずスタートさせます。これは実は一般コースの精密検査がほかの月３回、あるいは機会等、周知の方法等を研究してまいりたいというふうに考えてあります。","id":"exchange-069"},{"speaker":"嶋委員","kind":"質問・要望","question":"この乳がんというのに、ぜひこれはたくさんの方が申し込みがあると思いますので、ぜひ頑張って回数を多くしてほしいと求めました。これは今回１,０００円なんですが、一般で受けるとなるとどのぐらいの金額になるかおわかりか尋ねました。","respondent":"田中健康課長","answer":"保険診療の点数がいろんな方法論があるんですが、６,５００円から７,５００円ぐらいというふうにお考えいただければよろしいかと思います。","id":"exchange-070"},{"speaker":"嶋委員","kind":"質問・要望","question":"それぐらいかかるんだったら、ぜひこの区の無料を受けるということもぜひ区民の皆さんに言っていきたいと思いますので、ぜひこれは回数を多くしていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことを考えると、本来の検診としてはマンモグラフィも新設のような形でいっぺんにやってしまうというのが早期がんの発見というところでは一番ベストなのかなということで思うんですが、その点に関してはいかがか尋ねました。","respondent":"田中健康課長","answer":"スクリーニングと言いますか、一番最初に最低限のことをやるというのが一次で、精密という形で流れてまいりました。ただ、皆さんの選択の度合いがどんなふうに今後ご希望が流れていくかということを見定めながら検討してまいりたいというふうに考えておるところです。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今までの現行ですと、一次検査で大丈夫だということになるとマンモグラフィまでは行かないということになると思うんですよね。大丈夫でしょうということで言われて、それがなければまた１年後というふうなことになっちゃうということを考えると、どうか尋ねました。","respondent":"田中健康課長","answer":"やはりすべてにご負担をいただきながら精度管理の高いものを早くから導入という考えがすぐに転換できるかどうかという悩みもあります。発見の正確さみたいなものが医学の発展とともにどういうバランスで行くかということを含めながら検討したいというふうに考えてあります。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"できるだけ早期がんをたくさん発見して大事に至らないようにというふうなところでの検診のあり方ということでぜひご検討いただきたいというふうに思…Ｃ型肝炎って本当に人数が多くて、１００万人とも２００万人とも言われているかなとも思うんですけれども、そういう点ではいかがか尋ねました。","respondent":"田中健康課長","answer":"できれば４月からということで厚生労働省は考えているようですが、その計画のとおり私どもも対応したいというふうに考えてあります。現在、とりあえず不安をお持ちの方に対して窓口を開くというふうに、臨時的措置というふうにお考えいただければよろしいかというふうに思います。","id":"exchange-074"},{"speaker":"鶴副委員長","kind":"質問","question":"このマンモグラフィですけれども、医師会で機械を何台持っているんですか。医師会でこのマンモグラフィ検査をする機械を何台持っているのか尋ねました。","respondent":"田中健康課長","answer":"それぞれの医師会１台ずつかというふうに認識しています。","id":"exchange-075"},{"speaker":"鶴副委員長","kind":"意見","question":"なぜ聞いたかと言いますと、ほかの病気もそうですが、がんをどう駆逐するかということが私たち人類にとって大きな課題ですね。全部で８,８６５名ぐらいの人が一次検診を受けて、マンモグラフィ検査を精密検査が必要だということで、今までの実績の中でとの意見を述べました。","respondent":"田中健康課長","answer":"昨年の実績で申し上げますと、精密検査という形で受けている方が１,２８１名です。","id":"exchange-076"},{"speaker":"鶴副委員長","kind":"意見","question":"だから１,２８１名の方がこのマンモグラフィ検査を受けられたと。あるいは超音波検査だけだったのか、あるいは今までの細胞診検査まで、三つのこの項目で全部を受けられたのかどうかとの意見を述べました。","respondent":"田中健康課長","answer":"この三つをすべてやっているかどうか、必要に応じということがありますので、精密検査の所見によりまして、両医師会の診療所の専門の先生方が必要に応じてやっているですので、マンモグラフィは確かに基礎的にはやっているようです。","id":"exchange-077"},{"speaker":"鶴副委員長","kind":"質問","question":"基本的なものの考え方というのはどうなんですか。どうか尋ねました。","respondent":"田中健康課長","answer":"従来の精密検査、現行やっております精密検査というのも、これにつきましては医師会の診療所へ行きまして、それで保険適用をいたします。極端な話を言えば、そういう選択肢はもともとあるという内容で…","id":"exchange-078"},{"speaker":"鶴副委員長","kind":"質問","question":"自己負担分に相当する１,０００円、検診を受けたいと思っている人は全く何の負担もないんですよということになるわけですか、これは。今の説明によると。","respondent":"田中健康課長","answer":"今回は１,０００円をいただくことによって早く対応が図れるようにしたいという内容で考えてあります。全く保険とかかわりなく検診という内容です。","id":"exchange-079"},{"speaker":"鶴副委員長","kind":"意見","question":"１,０００円を負担というのは、これは本人負担だ。１,０００円だからいいじゃないのという人がいるかもしれないけれども、これ以上質疑はいたさないことにいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"伊藤委員","kind":"質問・要望","question":"一つだけ確認ですけれど、この乳がんマンモコースを新しくつくったことによってまず機会がふえましたということはそうでしょうかというのが一つ。待機者が解消できる可能性があるのでしょうかということを三つお答えください。","respondent":"青山品川区保健センター所長","answer":"そちらを精密検診を待機するという形ではなく、そういった意味ではより待ち時間というのはふえてしまう可能性があろうかとは思います。そのあたりを実際に募集をしてみて…","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、せっかくこういうふうな窓口が広がって、結果としてまたそれがおくれてしまったら本末転倒になるわけですよね。でももう少し考えていただけないでしょうかという思いがあるんですが、答弁をいただけますか尋ねました。","respondent":"田中健康課長","answer":"今回初めてこういう形で自己負担をいただきながら新たな方法ということで進めてまいります。その辺も含めてこの検診自体、今後どのようにしていったらいいかということを総合的に考えていきたいというふうに考えてあります。","id":"exchange-082"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひ、税金の投入の部分ももちろん整合性あるんですけれども、こういうシステムが円滑に回ることによって、要は疾病、がんというものを防いでいくことになるわけですから、そういうようなことの目的を十二分に考えた上で具体的な対策をとっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"鶴副委員長","kind":"提案","question":"在宅で再び生活を始めようと試みようとする人たちについてのサポートの一つとしてそういう助成なら助成をする支援事業というのが必要ではないのです…僕の答弁の聞き間違いだったらお許しいただきたいんですけれども、財政支援をやっているんだったら…","respondent":"新美保健高齢事業部長","answer":"こういう事例を私どもとしては今後もより家族の方への支援、あるいは高齢者の方の支援になるように努力していきたい旨をご答弁申し上げたものです。現在のところは１カ所ですが…","id":"exchange-084"},{"speaker":"船波委員","kind":"質問","question":"そのワーキンググループに町民として参加している方にはお話を伺わないということでしたけれども、プロセスについてお伺いしたいと思います。何せいろんな、当初のワーキンググループでさえも６０人以上というようなたくさんの人が代わってやってきたことですから、特に関心があるところです。","respondent":"林（和）委員長","answer":"そのときにも説明もあるでしょうし、向こうで用意していただけるんじゃないかなと思いますので、それを入れるということ。ほかに。","id":"exchange-085"},{"speaker":"鶴副委員長","kind":"質問","question":"に理想の福祉とはどうあるべきかを検討しようと現在に至る福祉への取り組みが始まったということですから。だからどこからどこの範囲まで話をすることにするのかと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"船波委員","kind":"質問","question":"ですからワーキンググループが、いろいろなサービスやら施設を整備してほしいという意見が出て、そういうところ。もいいですというふうに妥協や何かを重ねてきたと思うんですけれど、そういった様子がどんな様子であったのかというところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"鶴副委員長","kind":"提案","question":"僕なんかがここにいろんな施設だとか何かで住民のボランティア組織であるワーキンググループによって要するに検討されて提案されて実現したというと…だから提案があったこの人たちとは会話するチャンスがなかなか設定が持てないということでしたよねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"船波委員","kind":"質問","question":"ええ、参加された方に、でも話を伺えればそれはもちろん、そういうところをぜひと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"鶴副委員長","kind":"意見","question":"特にどういう困難なことがあって、それをどう克服したかというところが僕だったら知りたいなと思うとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問","question":"当然鷹巣町でもそれを実際やっているわけで、それから提供状況というんですか、介護保険の状況を客観的に把握しているところがあるはずなんですよ。どうしたらいいんか尋ねました。","respondent":"事務局","answer":"このレジュメには落ちていないんですけれども、福祉の事業概要の中で話の中に時間的に折り込めれば折り込むというお話はいただいております。このレジュメの中にもう１点再度確認の意味も込めまして落としまして先方にお送りしてご用意いただくということは可能かと思います。","id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、その客観的な立場で介護保険サービスの提供を評価している仕組みがあったらぜひそこを、できれば鷹巣町では見てきたいという思いがあります。もちろん限界がありますので、要望だけ伝えておきますけれども、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"},{"speaker":"嶋委員","kind":"質問","question":"分担が一番早いかなと思いますけれど、そうしますと、自分はやっぱりこれをやりたいというのがあるかと思うんです。その希望が通るんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１人が一つの項目だけというよりも、複数で複数の項目を持つというふうにしたらどうかなと思いますとの意見を述べました。","respondent":"林（和）委員長","answer":"１人の方が２項目ずつ持つのか、１項目持つ人とに分けるのか、それとも複数で持って４項目ずつやるのか。これでよろしいですかどうですかということをまとめて、それで報告をするという形を取りたいと思うんですけれども。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２人で２項目ずつ持つとか、２人で違うペアでも構わないんですけど、感想は全体のものを全員が出すという形はどうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"船波委員","kind":"質問","question":"あるいは一つの項目について必ず２人がやるとか、少なくとも漏れているところがないようにしておくぐらいでいいんじゃないでしょうか。ですから、一つの項目について３人いてもいいかもしれないし、あるいは薄いところではお一人しか関心のない項目もあるかもしれない。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"鶴副委員長","kind":"意見","question":"自分が気に入ったところをどうだったとか、要するにレポート形式でもいいし、随筆形式でもいいし、ドキュメンタリーでもいいし、それを書いてもらう。見解も違うことだしとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、厚生委員会という大きな中でやっていくわけですから、厚生委員会の名のもとにまとめていくわけですから。ですから、要望を聞いていただいて、私はこの項目をやりたいと大体希望が出てくると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この鷹巣町と宮古市の介護保険の事業概要というのは、この市勢概要の中に入るということで確認させていただいていいんでしたっけ。介護保険全体の事業概要という項目がここにないんですけれど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"鶴副委員長","kind":"質問","question":"ＡさんとＢさんとＣさんの文言が文言的に重なってもそれは当然同じところに視察に行くわけですから、表現が違うだけですよ。原稿用紙５枚とは言いませんから、どうですかね、伊藤さん。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"伊藤委員","kind":"確認","question":"ただ、きょう欠席の委員も含めて、きょう出た、これはだれがお願いすればいいんでしょうかね。それから個々にこの項目は私がやるという担当を決めていくのか確認してほしいんですが、時間がないということですからきょう決めますか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/723274?Template=document&Id=3000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":91944,"voices":262}},{"id":"h13-20010926-8","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"建設委員会","time":"午前１０時０７分～午後０時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"辻委員","kind":"質問","question":"隣接して一緒になって一体というなら分かるけれども、真ん中に下がっている区道ですか、大きい通りがある。財源的にこれをやったほうが金を取りやすいとかというと話は別ですけれども。","respondent":"岩田管理工事課長","answer":"その上物については財調で対応されるという財源的な仕組みがございまして、これで公園として用地を取得したほうが、これが一つの大きな理由です。未来永劫品川中央公園と同じように担保性を高めて網をかけていたほうが…","id":"exchange-001"},{"speaker":"上山委員","kind":"質問・要望","question":"２枚目の資料ですけれども、きのうちょっと現地を見てまいったんですけれども、今、学童保育クラブの建物ですか、これはどこら辺なんでしょうか。要望ですけれども、住民の皆さんがいろいろ要望も出されていたかと思いますので、そういう要望を汲んでいただいて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"辻委員","kind":"質問","question":"こういう公園という立場から見たときに、それだけの保険というんですか、事故に対するものはどういう考え方ですか。その辺をお伺いします。","respondent":"岩田管理工事課長","answer":"そのためにはプレイリーダーに対する何らかの保険のような措置を併せてやる必要があるというふうに児童課のほうは考えております。私ども、できるだけ最初はフリーな形で運用をしていこうではないかというふうに、児童課のほうとは詰めております。","id":"exchange-003"},{"speaker":"辻委員","kind":"質問・要望","question":"木登りのできる木を選んで、うまくやってほしいと求めました。その辺も。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"住民の人からどんな意見が出たのか、出なかったのか、ちょっと教えてほしい。プレイリーダーがいないときには、学童保育クラブの冒険ひろばはオープンになっているんですか、そこらをちょっと説明を求めました。","respondent":"岩田管理工事課長","answer":"これでは残念ながら泥ダンゴもできませんし、泥んこ遊びもできないわけです。住民説明会でのご要望ですが、道路側からの見通しが非常に悪いということもありまして、まず明るくしてほしい。","id":"exchange-005"},{"speaker":"築舘委員","kind":"質問","question":"土が最近珍しくなっていますから、そういった意味の自然の部分を残せるような、そういった形で固めないほうがかえっていいんじゃないか尋ねました。","respondent":"岩田管理工事課長","answer":"土のほうが一部なっておるんですが、そういった部分をインターロッキングブロックというもので、透水性機能のあるブロックをここに並べるつもりです。委員のおっしゃるように、できるだけ土の部分を多くとってあげるように配慮をしております。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"都が負担する５０％送水を引いた額が2,９００万円という、ここの仕組みがわからないんですけれども、どうしてこうなったのかということ。その辺の考え方についてお尋ねしたいんですとの意見を述べました。","respondent":"北村下水道河川課長","answer":"目黒川の水質浄化に向けた取り組みですけれども、ＢＯＤで見ましても４ｐｐｍということで、大分良好な状況にはなってきてあります。いろんなことを検討していますので、連携して取り組んでいきたいということで、検討を進めているような状況です。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"そこの水そのものはもっと増やすことができるんですか。どっちなんか尋ねました。","respondent":"北村下水道河川課長","answer":"現在送水している量というのは数％ですので、量的にはごくわずかといいますか、そのものが水が足りないとかという話はないと思います。流域変更という形になりますので、神田川側でどういう影響が出るか、もうちょっと慎重に検討する必要があろうかと思います。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"それは、都市再生の柱の一つですから、そのことで止まるということはないと思うんだけれども、その辺の影響はないのかというのが一つ。その２点をお聞きしたいと思います。","respondent":"伊佐都市計画課長","answer":"それから、大深度法の検討ですが、ここでは大深度法ですと、地下４０ｍ以下になっております。目黒川の部分をもっと深くして、大深度法の適用を検討したらどうかについては、ちょっと私どもそういった検討がされているか聞いておりません。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"だから、その点でどうかなと思って質問をさせていただきました。これは東京都のものなので、とりあえず今日はこの辺にしておきます。","respondent":"伊佐都市計画課長","answer":"今回の品川線の河川部分の設計もその辺の支持層を確認をした上で、地上から約３０ｍの土被りを確保したです。そういう意味での固い層の中をシールドトンネルで掘削しても、支持杭への影響は出ないものと考えているという説明をいただきました。","id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"土丹層といわれる層が出るところと、出ないところとあって、東京都の調査は必ずしも完璧ではないなというふうに私は思っています。ただ、こう言ってもしようがないので、今日のところはここまでにしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"上山委員","kind":"質問","question":"ちょっとお尋ねなんですけれども、区の大きな施策の中ですので、そこらの考え方そのものをもう一度教えていただければと思うんです。","respondent":"中島街路事業担当課長","answer":"連携の問題ですけれども、私どもこの住民説明会の後、合計６回説明会を実施しています。基本的には開発課のほうで所管していますので、そういった課とも私ども連携をとりながらこの事業を進めてまいりたいというふうに考えてあります。","id":"exchange-012"},{"speaker":"上山委員","kind":"質問","question":"いよいよ２６号線も完成して、同僚議員が質問をしておりましたけれども、ちょっとお願いしたいんです。","respondent":"中島街路事業担当課長","answer":"ただ、古い数字ですので、改めてきちっとした測量を、またシミュレーションをしていきたいというふうに考えてあります。そういったことで、今後調査が終わりましたら、改めてご報告をさせていただきたいと思います。","id":"exchange-013"},{"speaker":"横山副委員長","kind":"質問・要望","question":"ですから、そうして、商店街が生き残っていくような施策をやってほしいと求めました。商店街の方々もそういった部分で団結しているわけですから、進めるからには、そのぐらいの気構えで進めていただきたい。","respondent":"中島街路事業担当課長","answer":"今回説明会等をする中で、地元の方も、始めた以上はなるべく早く完成させてほしいという要望もいただいております。どうしても２年、３年というスパンでは、今後また地元の商店街の方とお話し合いをさせていただきたいというふうに思います。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"まちづくり協議会の要望があるので、８月だったのを、５月から用地買収の交渉をやる。まちづくり計画ができなければ、ちょっとマイナスなんじゃないかという気がするんですけれども、それはどう考えられておりますか。","respondent":"中島街路事業担当課長","answer":"街路事業と並行してまちづくりについても考えていきたいということでございまして、すでに今月中にブロックの方と話し合う予定になってあります。それと、あるいはそのためにどういう手法が考えられるのかというようなことを十分話し合いながら…","id":"exchange-015"},{"speaker":"沢田委員","kind":"意見","question":"あるいはあとどれぐらい足せば１階に店舗、用地買収単体でいけばどうかということを、どっちがいいのか。答弁は結構ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"辻委員","kind":"質問","question":"ですから、まるっきり建て替えてやるかという話になってくるわけですから、片方は。そういう幹線道路になっていくわけですから、池上通りのほうへ抜けていた車が、多分ここからストンと行くような形になっていくでしょう。","respondent":"中島街路事業担当課長、佐藤委員長、田村住宅課長","answer":"私ども先ほどからご説明しておりますけれども、１６３号線の道路事業と並行してまちづくりのことも考えていきたいという考え方です。… ほかにないようですので、本件の報告を終了します。 実施機関としましては、まちづくり事業部１６班、３２名編成でやっておりまして、区内の荏原、品川、大井消防三署と共同でやっております。点検要請書や…","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"待望していた西五反田の荏原市場跡地の募集なんですけれども、だんだん期待していたのがしぼんできちゃったんですけれども、全体の状況で聞きたいんですが、８７戸を建設をして、そのうち３７戸を西大井分にして、今回１２戸を募集するということですが、その残りはどうなるんか尋ねました。","respondent":"田村住宅課長","answer":"それ以外に品川区としては地元割り当てということで、１１月に予定しています。残りは東京都の都営住宅ですので、東京都のほうで東京都の事業用として使うです。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"西大井の３７世帯は、あるいは移りたくないとかという部分になると、それは品川区の地元割り当て分として公募になるんですか。具体的にそういうのが分かれば教えてほしいんです。","respondent":"田村住宅課長","answer":"実施設計をして、建て替え後の計画が来年の２月頃に大枠ができますので、来年の２月頃確認するです。あるいは東京都の住宅ですから、来年の２月時点で３７戸については、その時点に具体的に取り扱いについて協議をするという形になると思います。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問・要望","question":"本来的には地元割り当てで３７戸を実質取っているわけですから、地元割り当てとして募集をできるように頑張っていただきたいということを要望して、終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/428096?Template=document&Id=3702#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":35305,"voices":84}},{"id":"h13-20010926-9","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"文教委員会","time":"午前１０時０２分～午後１時１６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"自分たちのまちをどういうふうに体験したり、二葉一、二丁目の町工場を訪問した経験があるんです。子どもたちも非常に感動した記憶があるので、そのあたりも含めて、どういうふうに進められているのかを質問したいと思います。","respondent":"青木指導課長","answer":"先ほどのご質問にありました、製造業における後継者問題というような内容はどんなふうに位置づくのかということをご説明いたします。工業といった内容についての説明が書いてあるわけですけれども、とりわけ製造業につきましては、６０ページから出てあります。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"子どもたちがどういうふうに将来職業を身につけていくのかという点では、非常に大きな力だと思うんです。そういうふうな地域の工業、特に製造業の点についても理解を深めるという点では、その辺のところをもう一遍伺います。","respondent":"青木指導課長","answer":"もう１点、今こういうような仕事をしているんだよという、仕事を実際に子どもに見せるというような時間もあります。地域のそうした優れた技術というものも、子どもに紹介するという時間も今後増やしていきたいというふうに考えております。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"６３ページだけではちょっと載せ切れない、やはりそこの中学校の中でどういう工場があって、いろんな意味で体験というのはそうだったと思うんです。総合的な角度で、ぜひそういう点ではいろんな角度で研究をしていただきたいというふうに、これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"この中で、学習活動例というのがありますけれども、大体５時限ぐらいの時間なのか、社会科の先生が取り上げて、これを実際に使ってやられるのか。ちょっとお聞きいたします。","respondent":"青木指導課長","answer":"これは社会科の時間に、それぞれの教員がこの冊子を自分たちの指導の中で、どういうふうに組み入れて指導をするのかという計画を立てて、その学習の活動例というのを生かして、計画を立てて指導をしているところです。","id":"exchange-004"},{"speaker":"山路委員","kind":"質問・要望","question":"数年前に私は一般質問をさせていただいたんですが、細かくお聞きしたら、ここが大事だと。将来目指したいという、その辺は的確にできているかどうか、ご説明をほしいと求めました。","respondent":"青木指導課長","answer":"委員ご指摘のとおり、そのように今指導をしています。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"先ほどからの質問で、またほかの体験をして、自分の将来の仕事に生かしたい。そういう両面で効果があると思いますので、どうぞこの点につきましてはよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"山路委員","kind":"質問・要望","question":"３点目は、参考になることだと思いますので、この辺もお願いしたい。４点目に、アメリカの教育委員会と学校の関係と役割ということについても調査をしてほしいと求めましたので、どうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"高星委員","kind":"質問","question":"校長会、教頭会あたりぐらいのところできちっとその辺の、どうするかということを徹底すべきだというふうに私は思うんです。日本は何で戦争に反対しているのに、アメリカの戦争を手伝うんですかと言われたら、何と答えたらいいかと思って。","respondent":"青木指導課長","answer":"子どもたちのほうへ、テロということに対しての問題については、尊い命がこういう形で失われたというような形での指導というのはあるかと思います。これは憲法の枠内でやっていることだということを、今、子どもたちには答えているという形になるかと思います。","id":"exchange-008"},{"speaker":"高星委員","kind":"意見","question":"言い訳がきくのは、所詮、きらきらと目が輝いている小さな小学校の子どもたちに言い訳はきかないでしょうということを言いたかったんです。いろんな考えがある中で、それを飛び越えて前へ一歩進んだ答弁は、指導課長のところではなかなか難しいのかなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"桜井委員","kind":"質問","question":"今日の東京新聞によりますと、東京都の指示が出ているようですけれども、品川区の場合の牛の入荷はどこからきているのでしょうか。そこの出荷、入荷の登録業者との対応をしているようですけれども、区のほうはどこからきているのか。","respondent":"久保田学務課長","answer":"肉の購入は、区内の普通の肉屋から入れておりますので、その肉屋がどこから仕入れているかというのは私どもはつかんでおりません。そういう点では今のところ、念のためということで、ほかの肉に切り替えて対応をしているというような状況です。","id":"exchange-010"},{"speaker":"桜井委員","kind":"質問","question":"その関係というのは、保護者へのお知らせというのは、その辺はどうなんか尋ねました。","respondent":"久保田学務課長","answer":"直接保護者の方に、給食の変更の部分については、学校通知でお知らせをしてあります。そういう形で対応をしてまいりたいというふうに考えております。","id":"exchange-011"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望ですけれども、当日はもちろん具体的に現地でご説明いただくんですけれども、前もって予備知識として概要みたいなものはいただけるんか尋ねました。","respondent":"事務局","answer":"先方から資料はいただいてはおるんですが、今資料を調整中ということで、当日にしてくださいと。は建物のパンフレット的なものしかいただいておりませんで、まだ皆さんにお見せしてもそれほどの感じでもないんじゃないかと思います。","id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"どういう方々がやっているとか、施設そのものについては、私はいいと思います。事業内容について、できればお願いしたいと思います。","respondent":"事務局","answer":"ですから、当日に間に合わせるです。手元にもともとそういうものがあれば、そういうものをいただけるんですけれども、手元にないということでございました。","id":"exchange-013"},{"speaker":"山路委員","kind":"質問","question":"ちょっとお伺いしたいんですけれども、調査報告書というのは、。","respondent":"藤田委員長","answer":"では、この調査項目で先方に正式に伝えてまいりたいと思います。続きまして、報告書ですが、昨年から報告書を提出するというようなことになっておりますので、皆さんのご意見がございましたら、お願いいたします。","id":"exchange-014"},{"speaker":"山路委員","kind":"質問","question":"各委員が報告書を出して、正副委員長でまとめていただくという形か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"桜井委員","kind":"確認","question":"個人視察ではないわけですから、委員会としての視察ですから、こういうふうに全体として確認がされることもあるし。だから、一人ひとり報告を出して、報告をまとめて、それが委員会という、委員会の視察としてはそぐわないなという思いがするんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"松澤委員","kind":"意見","question":"こういう中で１時間なら１時間述べ合って、委員会の中で話をしたら、それは視察の報告になっているんだよと。私は、直感的にはそれでいいような気がしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"川西委員","kind":"提案","question":"そういう意味で、委員長の提案で、今回は並列にそれぞれ感想を列記して、出するというところで参考になるのではないか。議論しても、一致点はないと思うんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"桜井委員","kind":"意見","question":"川西委員の言うのを否定しているわけではないんですけれども、委員会として行く場合。どういう視察をして、それで委員会としての、そこでいいんじゃないかと思うんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"高星委員","kind":"質問","question":"みんなそうやって行くわけですから、それで総括的に、記録に上げていかなければいけないなという気がする。それは何カ所か回るわけですから、そこでだれかが取りまとめをしていくという、それを写真も含めて集大成の一つの報告書をまとめ上げる。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"高星委員","kind":"意見","question":"そういうことじゃなくて、僕が言ったのは、現場を見てのところの、そこで議論をしたものを大事にしたい。あまり参考にならないんじゃないか、そういうのを羅列して、生で議論をしたものをとっておくというのが大事なんじゃないかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その前に委員長のほうで吟味なさったものもありますけれども、私はそれでも十分対応できるのではないのかなと思います。これがよかったと思ったから参考にしたいという、それが結論で、皆さんが出せばいいんじゃないかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"川西委員","kind":"意見","question":"それが次から次へと、予定して行ってきますでしょう。やはりおさらいというのが、３行書くのでも、一応全部目を通しますから、見てきたのと、資料とが一致するということで、いいなと思いますとの意見を述べました。","respondent":"事務局","answer":"は感想をレポートにするのか、委員会の中で議論をして、その委員会記録を貼付するのかというところで、今お話が二つに分かれていると思います。そこのところをおまとめいただければと思います。","id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"意見が分かれるようでしたら、委員会ですから、正副委員長にお任せして、委員長の考え方で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/605950?Template=document&Id=4418#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":13888,"voices":66}},{"id":"h13-20010926-5","meetingId":"h13-cm09","date":"2001年9月26日","dateIso":"2001-09-26","committee":"総務委員会","time":"午前１０時０４分～午後０時１２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"こっちから行ったり、向こうから来たりというのがあるんですけれども、費用というのはどういう基本的な考え方になったのかということ。今回も２００名なので、今回は東海道４００年祭との絡みもあって、その辺のところはどういうふうになっているかとの意見を述べました。","respondent":"太川総務課長","answer":"日本がジュネーヴに５周年で伺いましたときも、これが国際交流の進めていくところのルールというのでしょうか、そういうような形で行われております。友好協会主催のさよならパーティー…","id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"今回１０周年ということで、５周年のときは２３０名と書いてあるんですけれども、その辺の規模の考え方というのはどういうふうになっていますかとの意見を述べました。","respondent":"太川総務課長","answer":"やはり、その辺のバランスというのは考えていかなきゃいけないものだと。ただし、経費につきましては、それぞれの国の負担になりますので、そこのところは多少の差異は出てくるかなと考えております。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"かなり規模が大きくなって、これからどんどんこういう感じでいくと大変だなという感じがしたものですから質問しました。では、そういう方向で、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ジュネーヴの方々がこういったところを見たいという何か要望と言いますか、日本に対して関心を持たれているのかということを、まずお伺いしたい。２０日、例えば公式訪問団の方々との交流なども図れたらなという要望があるんですが、その部分に関してのお考えをお聞かせほしいと求めました。","respondent":"太川総務課長","answer":"やはり品川の伝統工芸の部分で伺う予定になっておりますのが、やはりそういう職人の世界を見てみたいという要望が強うございまして。委員の方々につきましても、状況によりましては、私どもものほうもそういう話ができるような場所を工夫していけるかなというふうに考えておりま…","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど少し予算的な部分も出ておりましたが、せっかくの機会なのでより効果的なと言いますか、そういう機会もぜひしてほしいと求めました。日本の工芸もぜひ親しんでいただきたいんですが、音楽的なものも含めて交流を深めていただけたらなという、これは要望とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"学校はあまり喜ぶかどうかわかりませんけれども、ＰＴＡを含めて学校周辺の方たちで、そういった形のものはどうするのかとか。本当にお金の多寡ではなくて、そういった意味の交流会というものが考えられないのかどうか、どうなんか尋ねました。","respondent":"太川総務課長","answer":"２０日につきましては、友好協会といたしましても、各学校にそのような形でご案内を差し上げてあります。ここは私のほうも友好協会に話をしてまいりますけれども、地域の方がどういう形なら参加できるのかということを工夫してまいりたいと考えております。","id":"exchange-006"},{"speaker":"三上委員","kind":"質問・要望","question":"せっかくのこういう機会ですから、これも直接関係した人はそれなりに関心もあるし、それ以降のお付き合いもしているということはあると思います。ですから、せっかくですからゆっくり日本を見学させてあげたいということも十分配慮してあげるべきだと思いますけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"北野委員","kind":"質問","question":"これはどの場所に設置して、だれが押すんですか。発見した方が押すとか、そういうところはどういうふうになっているのかお聞きしたいんですけれども。","respondent":"桑村政策担当課長","answer":"今のところ東京都の考え方としては２カ所と言っておりますが、一つは事務室につけていただきたいと思います。学校あるいは保育園につきましては、都を通しましてつけるような形になりますので、文教委員会あるいは厚生委員会等で内容についてご報告します。","id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"適正化というと、その辺のニュートラルですけれども、下げた理由があるのかどうかということを知りたい。あるいは、待遇の考え方を現状に合わせていくかという、等級等の考え方を、そういう事例があるかどうか確かめたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"それから、職員の残業というのか、今は不規則勤務という部分にしてもこれがどういうふうになっているのかということです。品川区の場合だったら、それで１０時までの延長保育をやっているわけですけれども、その点はどういうふうに行っているのかということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"北野委員","kind":"質問","question":"どういうふうに利便性を図っているのかというのをお伺いしたいのと、どういうものを育成確保しているのかというのをお伺いしたいなと思います。透明性を確保するということで、情報公開とか市議会の公開というのもありましたので、それについてもどういう進め方をしているか伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"役人というのはやっぱりコストに追われて仕事をするということがあまりないですから、どうしても遅れがちになってしまうということがあります。品川区の場合も、どうしているのか教えてほしいけれども、とりあえずお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"田中委員","kind":"確認","question":"その中でのということで、例えばシステム的なものが用意されているのかどうかだとか、そういう形の仕組みとしての内容を確認したいということ。それが入札の改善につながったのかどうかだとか、積算のことも伺っているかと思いますが、特に聞きたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"いろいろ行革をやっていく上での市民からの市政の意見の反映とか、仕組みがどうなっているかということ。これは考え方と、まだやったばかりなので、この辺の実際のところを伺ってみたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"１０年前にやったとか、そういうところはいくらでもあるわけで、実際話を伺うと何年前にやりましたというような報告がありますけれども。抵抗勢力じゃないですけれども、ちょっと待ってくれよというような話があるわけですから、我々自治体の経営に役立つんじゃないかと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"前のときもちょっとお願いしていたんですが、唐津市の競艇場があるんですね。そこの今の現状だけでも聞かせてもらえるように付け加えていただけませんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"麻生総合研究所というのは……。何を質問しろと言われても、すごいことをやっているなということなんですけれども、そこからお聞きしたほうがいいんじゃないかなという気がします。","respondent":"本多委員長","answer":"本当に特色ある取り組みですので、我々も事前に勉強会を開いてやっているところを先方にもお伝えして、現地で本当に実り多い調査にしていきたいと思いますので。","id":"exchange-017"},{"speaker":"土井副委員長","kind":"質問","question":"思いはあるけれどもというけれども、ここに管理委員会につなげた人がどこのだれなんでしょうかということをまず聞きたいと思いました。そしてつながったんだから、今度はつながった人が来てくれるんですから聞くことはたくさんあるんじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"もしでき得れば、そういった比較資料をいただけたらと、要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"意見","question":"それから「民間の経営管理的な視点から市行政運営のあり方について意見を提起してもらう」と、そういうことだと思うんです。この資料を見ただけなのでよくわからないんですけれども、ある意味では最初に目標ありきではなくて、その辺のやり方みたいな……との意見を述べました。","respondent":"中尾根企画部長","answer":"では、自治会・ＮＰＯの育成支援に向けて機能強化したらどうかということで、そういうことをそれぞれの項目で全部やられているということなんです。イメージとすると、先生方がこういう点はどうなんだという問題点があって…","id":"exchange-020"},{"speaker":"三上委員","kind":"質問・要望","question":"市長就任後に取り組みを始めたということですから、ここらあたりをまず最初にしっかり学びたいなというふうに思います。どういうような形で組合が教育をする形になってきてたのかということについて、組合の状況あたりを教えていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"北野委員","kind":"質問","question":"どういう職種の方たちがなっていらしているのかというのと、どういうことで選考したのか、ちょっと細かいんですふうにお伺いしたいと思います。この結論を出すのは、全部経営管理委員会で報告書をまとめたのかどうかというので、職員の係わり方もお伺いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"報告といたしましては、それぞれ口頭でこういうことがあったとか、この点はよかったとか、委員会の中であったという記憶をしております。分担制にしますと、やはり会派の問題が出てきたり、それぞれがそれぞれの方向を出すのは構わないですけれども…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"土井副委員長","kind":"質問","question":"あった事実は事実ですから、淡々と書くだけですから、そこにはまるのは何なのかということなので、分担すると片方の意見だけが載ってしまうんです。１回委員会で少しもんだ上で、それをまたもう１回皆さんのご意見等を聞いて、ちらっとは議論をしております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、自由に書いて、それを寄せ集めるという感じでもいいのかなという感じがするんですけれども。あんまりそうでなかったところ、その委員によって強弱があるかと思うし、それはそれでいいんじゃないかなという感じがするんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"田中委員","kind":"意見","question":"私も大体皆さんと同意見で、私も昨年区民委員会に参加しまして、昨年の方式はいい報告の仕方だと思いますので、分担制ではなくて、個々の委員の方々の感想なり評価を口頭でお伝えをし、それを正副委員長のほうでまとめていただくような方式がいいかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/517525?Template=document&Id=1560#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":36572,"voices":80}},{"id":"h13-20010927-13","meetingId":"h13-cm09","date":"2001年9月27日","dateIso":"2001-09-27","committee":"清掃・リサイクル特別委員会","time":"午前１０時１４分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そして１０月１２日までという、どういうふうに私たちが認識をしていったらいいのかというのが、教えていただきたいんですけど。","respondent":"中山清掃リサイクル課長","answer":"この都内の区市町村、それぞれ計画なり施策の方針を持ってありますから、これをそのまま網羅するというものではございません。かなりその各区で考えている施策、例えばそれに全くもとるような方針が出れば、それは意見を申し上げる。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"変更というのかしら、ここはしないんだという、そこのところを改めて確認していただきたい。ちょっとこの辺のプロセスもあわせて説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"先ほどのお答えと繰り返しになろうかと思いますけれども、区の施策の方針に東京都の計画が、きちんと申し入れていくという形です。平成１３年中につくり上げていきたいというふうに考えておりますので、あるいは多くの場面は設定されることになっております。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"なぜかというと、結局、こういう流れになるための端緒を築く大変重要な中身を持っているんじゃないかというふうに思うんですね。ここが極めて大きいと、私は思ったんですけど、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"区の清掃工場の現状を考えましても、一般廃棄物の排出量の見込みからすると、それから処理施設に余裕があるというふうに見えるのが実態です。余力のある範囲の中で市区町村の清掃工場の中で焼却ができないのかということが、これは国レベルでも検討がされている実態があります。","id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"そのとおりだと思うので、これは十分皆にも説明をして、理解を求めなければならんということが一つ。我々が独立をして、我々も処理してやらなければいけないんだという自覚を求める中身でもあるということですから、わかっているんですね。","respondent":"中山清掃リサイクル課長","answer":"東京都が移管した事業まで権限を持って運営できるやの意識ではないと考えていますが、そういうふうな認識での計画には決してならないようにしようと。これは既にいろんな前段の説明をされたときにも申し入れはしてありますけれども…","id":"exchange-004"},{"speaker":"土井委員","kind":"質問・要望","question":"先ほどから何回も言いますけれども、これは何もそれを言おうというんじゃなくて、どう具体的に処理をするのかというときの課題だろうと。財政的なもの等についても十分見計らって対処していっていただきたいなということを、それしか言いようがないので、要望も含めて。","respondent":"野本環境清掃事業部長","answer":"ぜひこの点につきましては、事務当局とともに委員会とも知恵を出し合いながら、精いっぱい努力をしていきたいなというように考えております。よろしくご理解をお願いします。","id":"exchange-005"},{"speaker":"須藤委員","kind":"意見","question":"この計画のメンバーが有識者云々であるというんだけど、そういうところがどういうメンバーの方なのか。それから、この立ち上がった時期は、いつ委員会なら委員会が立ち上がってきたのかということを聞きたいと思いますとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"この部会が設置されましたのが、この廃棄物行政のあり方の検討部会の設置ということが出されておりまして、この特別部会として検討を行ったのが。この廃棄物行政のあり方の検討特別部会の第１回が行われて以降、８月２７日まで９回行われて…","id":"exchange-006"},{"speaker":"須藤委員","kind":"意見","question":"これはもっと、逆に言うと、我々委員会の中でそういう話を出せて、品川区の議会としてこういう考え方を持っているよということをしていくべきなのか。とやるのとか、その意見を聴取するというのはどういうことなのか、聞きたいと思いますとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"郵送、ファクス、Ｅメールでご意見を１２日金曜日までにお寄せくださいということをホームページ上に出しております。都民・区民として意見を出されるという場合については、ここあてに何らかの形で、要は文書という形でいただきたいという形になっている次第です。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"今日の午後の視察は、各委員からこういう視察要請があったんですか。ペットボトルですとか。","respondent":"高木委員長","answer":"この委員会として、部署の認識をできるだけ高めていかなければならないということで、こういう場所を正副で検討いたしまして決めさせていただいたと。リサイクルに関するそれぞれのポジションの仕事について、やっぱり現場認識を高めていく必要があるということで…","id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"はい、結構です。特にその方向性が云々と、正副で決めたのではなくて、参考にこういう状況を視察してみましょうということですねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"ぜひお願いしたいなと思うのが、後で解説してほしいんですけど、サーマルリサイクルはどんなのかなと思うわけです。やっぱり区がどういう方向を示しているのかによって、援助とか、その辺のご意見をちょっとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"プラスチックというものを考えたときに、ほかの紙や瓶、缶に比べて非常に難しい。そういった区の取り組みがあれば、それは技術的にというところで、また調査研究で支援するというふうに言っているものです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"格段に清掃工場で燃やしているのが多いというところでは、やっぱり何よりも発生抑制のところを、うんと力を入れていく必要があると思っているんです。都の押し付けるものじゃないという話は先ほどから伺っておりますけれども、区の視野に入っているのかどうかっていうのを改めてお聞きします。","respondent":"中山清掃リサイクル課長","answer":"いわゆる視野の中に入れながら、より望ましい今後の廃棄物の処理のあり方ということは、検討していくべきだとは思っております。あるいはいろんな場面での議論を受けながらですけれども、はなから視野に入れないということではないという認識は、少なくとも私は持っております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区にやっぱりいろんな角度で検討もしてほしいな、意見も載せていただくことが大事だと思います。やはりいろんな情報提供もしていただきたいし、またその辺をどう考えていくのかという、これからも持っていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"北野委員","kind":"質問","question":"実際に出るのは平成１４年度からということになると思うんですけど、平成１４年度の当初には、区としての考え方もこれを受けながらやっていくと。できるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"平成１３年度が計画期間に入っておりますから、最初の１年はもう食ってしまっているじゃないかということかもしれません。スケジュールが平成１３年度中にこうやって検討していること自体は、５年のうちの最初の１年は、むしろ検討で食われているという実態はあります。","id":"exchange-013"},{"speaker":"北野委員","kind":"意見","question":"やはりその支援がどういう、そういうものを受けながら、よりよい品川区の計画ができれば一番いいだろう。清掃工場は区ではないというところもあるし、いろんなところで連携が必要じゃないのかなと思うんですけれども、どうなんでしょうとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"連携、繰り返し言いますけれども、区の施策に拘束力を持ってかかっているものではありません。ここの考え方に出てくるような、基本的にはないというふうに、繰り返しましたけれども。","id":"exchange-014"},{"speaker":"北野委員","kind":"質問","question":"私たちの税金が使われていて、また自己の負担になれば、私たちのお金を無差別に払っていくという。市町村の判断になるということなんですけれども、今の現状を考えた上で、考え方とかをちょっとお伺いしておきたいんですけど。","respondent":"中山清掃リサイクル課長","answer":"有料化の検討というのは避けて通れない議題であると、論点であるというふうに、答弁申し上げていると思います。この前申し上げたように、ごみの減量は非常に下げどまっている傾向を考えると、再度認識しているということは申し上げたいと思います。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"今、検討中なんですか。その辺、ちょっとお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"制度の施策を考えていく中でコストの分析は重要だということでは、２３区を挙げて検討に入ろうということで、分析に入っているところです。客観的に説明できる材料をつくっていく必要があるという認識では、２３区、今動いているという状況です。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"条件が違うというんですか、それによって介護保険の料金の額が、区ごとによって違ってきているという場合。それはどうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"２３区がまさに基礎的自治体になった中では、あるいは区民の方の考えの中で決まっていくことですから、ということになるかと思います。各区の中で考えていくことということになりますので、その中でいろんな動きが出てくる、結果が出てくるというふうに認識しております。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"そういうものを例えば平成１２年度の決算が既に出ているんですから、例えばその中で、もう既に明らかにされている部分がある。その辺はどうなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"各区の考え等がある中で、これは当然示してまいりますし、ごみを出すときにこれだけコストがかかりますと。ですから、そのための、ごみ減量のための概数についてもぜひ公開していきたいというふうに思っております。","id":"exchange-018"},{"speaker":"船波副委員長","kind":"質問","question":"家電一般に関してはどうしたものかと、有害なものは、まず適正に処理されるような状態にうまくとらえて処理されるようなルートがつくられていく。そういったことも検討されているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"鋭意検討というのはいってないというのが実態なんですけど、売った人、そういうものの役割をもっと徹底していこうと。今その適正処理の考え方というのは、行政で処理が難しいですと。","id":"exchange-019"},{"speaker":"船波副委員長","kind":"意見","question":"どういうふうに取引するというか、どうやってチェックしたり、区はどう思っていますとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"区のほうで正確に答えるのは難しいんですが、言われているのは、いわゆるマニフェスト伝票制度というのがどうも十分機能していないと。きちんと追っかけられるような仕組みをつくるような整備を、今、都・国レベルで研究しているというふうに聞いています。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"一安心したんですけれども、今いろいろ質疑を伺っていて、個別のいろんな問題が出されたときに、例えば有料化の問題では、区も視野に入れていると。どういう基準で、そういう部分、具体的なことをちょっと知りたいんですけども。","respondent":"野本環境清掃事業部長","answer":"説明責任の果たすべき道具の最たるものですから、これはもう、そういうこととは関係なしにきちんとやっていく。できたものは、皆さん方にできるだけ広くご理解をいただきたいし、きちんと説明していく。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、法的な整備も改善していくという話ですから、私は軽々に議論すべきではない思うわけです。ですから、軽々に導入すべきじゃないということをちょっと要望させていただきたいのと、こことここと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"土井委員","kind":"質問","question":"要するに２３区清掃協議会なるものの性格そのものが何ぞやということが書いていない、この２３区の清掃協議会のパンフレットというのは、どうなったんですかな。","respondent":"中山清掃リサイクル課長","answer":"２３区で共通して表現できる内容のものを印刷物にしていくということと、これ、協議会の性格上異なっております。協議会そのもの、一部事務組合そのものの説明がないというのは、それぞれのリーフレットにゆだねているということで。","id":"exchange-023"},{"speaker":"土井委員","kind":"意見","question":"それは、どういう、要するに配布基準、どこに配布されて何に使うのというとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"配布部数が品川区、１,０００部送られてきました。今のところ、要望があった際に、それをお配りしているという活用の仕方になっています。","id":"exchange-024"},{"speaker":"土井委員","kind":"質問","question":"ですから、要するに何のためにつくるのという目的がないままにつくったんじゃ、廃棄物になっちゃう可能性があるわけですね。数量と予算と決算と、こうつながっていくようにお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/301337?Template=document&Id=5648#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":38862,"voices":60}},{"id":"h13-20010927-16","meetingId":"h13-cm09","date":"2001年9月27日","dateIso":"2001-09-27","committee":"街づくり特別委員会","time":"午前１０時０４分～午後４時３５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問","question":"その違いというのですか、あるいはするとかいうんですか、そういう考え方みたいなものがあるんでしょうか。ちょっと教えていただけませんか尋ねました。","respondent":"南雲都市開発課長","answer":"行政が補助金などを入れなければ土地の高度利用が進まず、地域の環境が向上しないというふうな地域について補助金を入れるというような考え方です。以上です。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"例えば以前の計画と大きく違った、あるいは変わらざるを得なかったというのがあれば、ちょっと教えていただけませんでしょうか。（「変わったのは工期の」と呼ぶ者あり）ええ、そうですかね。","respondent":"南雲都市開発課長","answer":"今年の７月のこの委員会でも報告していますが、それからあと１つは、当初よりもおくれているです。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと別のところでお伺いしたいんですけれども、今度のＢ－４地区の建物の関係でなんですが、そういう手法みたいなのを使うんでしょうか。もしそうでなければどういう設計になるのかということと、当初とまた違うのであれば、そこらも教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"区画整理を行った後も、各地区に再開発地区計画で容積を定めておりまして、通常の用途地域の容積率よりも深く設定しております。この地区は、現行は人口増で４００ですが、再開発地区計画によりまして７８０％までアップしております。","id":"exchange-003"},{"speaker":"本田委員","kind":"質問・要望","question":"Ｂ－１地区では１０メートル、今回の改正ではＢ－４で８メートル、これはどういう計算で距離というのは出てくるんですか。参考までに教えていただきたい。","respondent":"南雲都市開発課長","answer":"考え方としては、それから補助３１８号線、こちらに面するところについては１５メートルですとか１０メートルというような設定を行っております。それから、開発区域の中側については比較的短いセットバックで…","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"何となくごちゃごちゃといいますか、例えば８メートルが１０メートルであっても、また６メートルであってもいいわけなんでしょう。これを８メートルにしたというのは、今の話ではどうもちょっと、それによって決まってくるわけなんか尋ねました。","respondent":"南雲都市開発課長","answer":"壁面線の後退とは別に、空地をどれだけ確保するかということで、事業者のほうは建物の形状ですとか配置を考えるということになっております。３枚目のカラーのパースがついておりますが、このＢ－４地区といいますのは、建物の景観についても配慮したです。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"Ｂ－１地区の１０メートルと同じく並べて何でできないのかなと、単純にこれを見ていまして、感じるんですよ。低く抑え建物の面積を広くとったということなのかなというふうに思うんですけれども、そういうことなんか尋ねました。","respondent":"南雲都市開発課長","answer":"１０メートルのセットバックも十分に可能なんですが、Ｂ－４街区というのは規模が小さい区域ですので、これについては８メートルというふうに設定されております。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと今のところなんですけれども、高さと容積の関係なんですが、先ほどの質問で、この地域は人口で４００のところを再開発計画で７８０までふやしたということなんですけれども、まず、この高さ制限というのはどういうふうになっているんか尋ねました。","respondent":"南雲都市開発課長","answer":"ただ、空地を何％とるということなどで高さが定まっているということで、空地をたくさんとれば高い建物が建てられるという基準があります。それからもう１つ、そういうものを勘案して、各事業者のほうで建物の形状を設定するです。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの質問の何で８メートルなのかという、全体の景観だとか、この容積をとると８メートルだと。１０メートルはなくて８メートルになる、そういうことなのか尋ねました。","respondent":"南雲都市開発課長","answer":"８メートルといいますのは、周辺への影響ですとか景観を考慮して、最低限これだけは下がってくださいという数字です。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"そういう考えで５メートルとか８メートル、ほかのＢ－１地区ですと１０メートルというふうにおっしゃっていましたけれども、Ｂ－１とＢ－４の違いというのがそういうふうになってくるんですかと。","respondent":"南雲都市開発課長","answer":"このＢ－４地区の場合ですと、この建物全体の形状ですとか規模から、それぞれこの道路から何メートル下がってくださいというものを定めている。空地の利用ですとかそういうものを考えて建物の形を定めていくということで…","id":"exchange-009"},{"speaker":"宮崎委員","kind":"意見","question":"何となくわかりました。このＢ－４地区のところを合わせてでいいのですけれども、全体的に、ほかに緩和されているものというのは主にどんなものがありますかとの意見を述べました。","respondent":"南雲都市開発課長","answer":"この再開発地区計画で緩和されているというものは、容積率は緩和されております。個々に建てた場合には、この地区については一体的に建てるということで、隣り合っているの建物の制限については緩和されますというものです。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"住民の方々の一番の要望というのはやはり立体交差と思うんですけれども、全然変わらないというふうに思うんですよね。そこのところ、実際上、立体化するという話だったんですけれども、できなくなったその理由というのをちょっと改めて聞いていきたいと思うんです。","respondent":"南雲都市開発課長","answer":"ここの図面でいきますと補助１４９号線の下をトンネルでつくって第一京浜の……〔「踏切」と呼ぶ者あり〕踏切ですか。ちょうど深くなっているところでございまして、これを立体化するとなると莫大な費用がかかるということで、これについてはトンネルにする。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"こんなになっちゃったという話が余り見えてこないんですけれども、そこら辺の計算というのはされているのか、あったらちょっと聞かせていただきたい。具体的にどういう計算でなっているのか、これはもうちょっとわかりやすくお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"当時、当然発生交通量も相当なものが生まれてまいりますので、立体化に向けてどんな手法がとれるかという検討をしたことは事実あります。これが抜ければ、大幅に改良が見込めるということで、この区画整理事業をスタートさせたといういきさつです。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"その分はこっちのほうでやるからという、住民の方の要望というのは、やはりこの立体交差の解消ということだと思うんですよね。そういう意味では、もうちょっと何とかならないのかなというのは、この段に来てもやはり非常に強く感じております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"藤田委員","kind":"質問","question":"垣または柵の構造なんですけれども、今までは旧条文ではなかったものを新たに設けた、その理由はどういうものがあるのかということをお伺いします。","respondent":"田平建築課長","answer":"従来なかったわけじゃなくて、Ａ－１、Ｂ－１には条文があったわけです。今回、Ｂ－４地区という新たな地区がふえたので、そっくり同じに写しかえているということです。","id":"exchange-014"},{"speaker":"藤田委員","kind":"質問","question":"このＢ－４地区というのはオフィス地区になるということで、このパースを見てみますと、かなり高層ですね。ここで、何ゆえ透視可能なフェンスまたは鉄柵等が必要なのかということなんですけれども、それの理由をちょっと説明を求めました。","respondent":"田平建築課長","answer":"やはりこの品川駅東口再開発全体の景観だとか、それからこういうフェンスなんかつくる場合には統一感がもちろん望まれるわけで、つくる場合にあっては、そういう統一がとれたものにすべきであるという考え方からこういう条文になっております。","id":"exchange-015"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、どういう形で逃げられるかということを考えれば、障害になるんじゃないかと。むしろ生け垣とか、そういうもので周りをぐるっと固めるのであれば納得いくわけなんですけれども、その辺ちょっと聞かせていただきたい。","respondent":"田平建築課長、南雲都市開発課長","answer":"そこを利用する事務所だとかマンションの人たちから見れば、やはり防犯上の観点からは柵をつくりたいというのが、声としてあるわけです。都市開発課のほうで具体的な周囲の構築物について協議してまいりますが… 実際にこの東口でつくられている建物でも、空地の部分については一般の人が入れるものですとか、あとは緑地などが主体です。バックヤードのような場合も中にはありますので、あと全体の計画については…","id":"exchange-016"},{"speaker":"藤田委員","kind":"質問・要望","question":"女性が塀を飛び越えて、いくら見通しがいい鉄柵でも、飛び越えてくれといったらかなり難しいんじゃないというふうに思うんですね。その辺、ぜひ頭に入れてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"ちょっとお聞きをしたいんですが、この建物についての、帰属を教えていただきたいなと思いまして、通常ですと入り口という感じだけれども、これで見ると半分以上は建物も土地も持っているが、帰属は品川区ですか、港区になるんか尋ねました。","respondent":"岩田管理工事課長","answer":"２枚目で見ていただきますと、建物が品川区が約５０％強、港と半分ずつぐらいですが、ただ、残念ながら入り口が港区側にできておりまして、このビルの住所そのものは港区港南なという位置づけになる予定です、まだできておりませんので。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"そうしますと、確認だけさせていただきたいんですが、品川区に帰属するのは、このＶタワーの隣の低層階と公園の３というところが品川区で維持管理というか帰属をされて、一部道路がちょっとあるけれども、そういう考えでいいのかどうかだけ、ちょっと確認。","respondent":"南雲都市開発課長","answer":"品川区に帰属しますのは、Ｖタワーの前の半円状の低層のほうと公園ということになります。道路上にデッキといいますか、歩道橋はできています。","id":"exchange-019"},{"speaker":"石田委員","kind":"質問","question":"もう１点だけ。北品川１丁目、入居される方にどうやって説明をしていこうという準備がされているのか、そこだけちょっとお聞きします。","respondent":"南雲都市開発課長","answer":"１つの事業者が一括で販売をしておりますが、販売の時点で重要事項の説明の中で、販売時点で事前に購入希望者の方には十分周知していくというふうに聞いております。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"そこの確認を、港区は港南小学校になると思うけれども、そこら辺との話し合いをちゃんと詰めておいていただきたいという要望をします。重要事項の中の問題に突っ込んでいただいて、そこら辺までの話を詰めていただきたい、これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう１つは、さっきも質問したんですけれども、やはり一番の地域の方々の要望だというふうに思うんですよね。いろいろ考えましたけれども、やはり今回は賛成できないということを通告しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"上山委員","kind":"意見","question":"ちょっとお尋ねするだけなんですが、どのくらいおくれるのかわかりませんけれども、様子もうちょっとわかればと思うんですがとの意見を述べました。","respondent":"南雲都市開発課長","answer":"平成１３年１２月の臨海副都心線の開通というのは、当初は構築物も考えていたんですけれども、どうしても同時には無理ですということです。まだはっきりしてはございませんが、これについては…","id":"exchange-023"},{"speaker":"上山委員","kind":"質問・要望","question":"大変なことで、非常に何かここら辺の住民の方からすると大事なことであると思いますので、ぜひ方々に働きかけや要望を含めて、お願いしたい、この要望だけ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"三上委員","kind":"確認","question":"ある程度、ちょっと確認だけさせてください。これが逆になってるというのは、その逆のこの横のところが階段というところでいいんか尋ねました。","respondent":"南雲都市開発課長","answer":"この山手貨物線をまたぐ必要があるということですね。南側に２つということになると、この大崎駅の真ん中に山手貨物の線路が傾斜しているという物理的な状況で、最善な形での駅舎の整備は難しいです。","id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"形状に合わせて両方ともつくっているということじゃないですか。そう思いませんか。","respondent":"中谷まちづくり事業部長","answer":"この図面で南側の方面のほうに持ってこざるを得なかったという経過の技術的な部分と、ＪＲとの交渉経過がありますので、ご理解いただきたいと存じます。","id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"これはもう余りにも、ＪＲは勝手だけれども、こちら側が余りにも、そういった点に対しての強く主張していないということでないんじゃないんですか。私はそうだとしか思えない。","respondent":"中谷まちづくり事業部長","answer":"そういう技術的な問題がありますので、これしか方法がなかったということで聞いておりますので、ご理解いただきたいと思います。〔発言する者あり〕 先ほどちょっとご説明したんですが、ここのとこからこちらへつなげるわけですね。","id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"時代が変わってこようが、必ずあの広い土地ですから、何らかの形で行われるのは当然わかっているわけでしょう。今度はＪＲで駐輪場、どういう形で整備するんですか、今度はもうそういう運動起きてきざるを得ないじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"平成１０年ですとまだゲートシティがオープンしていないと思うんですけれども、先ほどの話でいいんですが、利用客がどのくらいになる見込みなのか。今までですと随分、どういうふうに組み立てられるのかなというのがよくわからないんですが、ちょっとそこのところで聞きたいと思います。","respondent":"南雲都市開発課長","answer":"７万人程度の計画で、その後、ゲートシティ完成後に約１０万人になったというふうに大崎駅のほうから聞いているところです。この１５メートルという幅員はつかめておりますので、ここの１５メートルの幅員がある通路であれば、こういう数字については算出をしています。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"これはＪＲがつくらない、こういうものはつくってほしいというところが金を出すべきなんだと、それが簡単に言うとＪＲのほうの理屈ですよね。だけれども、そういう法的なものがあるのかどうなのかというところをちょっと、わかったら教えていただければと思うんです。","respondent":"南雲都市開発課長","answer":"ＪＲの内部では、例えば乗降客数何人当たり改札口が幾つというような基準があると思うんですが、具体的に何人になったらこ線橋をつくらなきゃならないというような法的な基準はないと思います。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"意見","question":"向こう側の理屈というか、考え方もしっかり、もしかしてちゃんと持っておいたほうが話がしやすいかななんていうふうに思いました。ちょっとした感想ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"上山委員","kind":"質問","question":"賃貸などありますけれども、例えば住宅は大体どのくらいの戸数の予定、あるいは業務棟へのどれくらいのものになるのか。一般に例えば高さがどれくらいになるのか、もし概略がわかれば、ちょっと教えていただけませんか尋ねました。","respondent":"南雲都市開発課長","answer":"再開発事業につきます３棟の建物について、大まかな状況をご説明させていただきたいと思いますが、今後の数字については動くという可能性があります。これについても、１戸当たりの広さによって戸数が変わってきます。","id":"exchange-032"},{"speaker":"上山委員","kind":"質問・要望","question":"計画がまだ策定していないと思いますが、もう１つお伺いしたいんです。こちらもし何か情報があれば、どこがどのような感じになるのか教えていただければ、お伺いしたいんです。","respondent":"南雲都市開発課長","answer":"今後細かい内容については当事者同士で詰めるということで、この２社が将来は所有権を取得する予定で事業を進めていくという体制になっています。ただ、事業としては別個に、今後も都市計画などについては協議を続けるということになっております。","id":"exchange-033"},{"speaker":"上山委員","kind":"質問・要望","question":"何かそういういきさつでおりたかどうか、何かよくわかりませんけれども、何か情報があれば教えていただきたいのが１つ。それから２つ目なんですが、今のところどれくらい予定されているのか、今現在わかる範囲でちょっと教えていただければと思うんですが。","respondent":"南雲都市開発課長","answer":"組合員主導でつくれるという考え方を持っていくということで、参加組合員の予定者として大林組、企業中心の体制については一部変わっております。そのうちどのくらいの補助金が見込めるかというのは、これにつきましては、またこちらの委員会でご報告させていただきたいと思いま…","id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"このティクス棟というのは、今千代田グラビアのあるところかと思うんですけれども、千代田グラビアが名前が変わったということじゃないんですか。千代田グラビアはまた別なんか尋ねました。","respondent":"南雲都市開発課長","answer":"申しわけありません。この図面でいくと左側にあると、それで、千代田グラビアのほうは今の状態のままです。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、ここは金陽社があったところになるわけですか。金陽社がここには参加しないで独自に土地を売って、というそういう形になっているんか尋ねました。","respondent":"南雲都市開発課長","answer":"この３棟をつくるということで、自分のところだけで単独で行いたいということで、共同で街づくりを行っていくです。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"戸部工業ですね、わかりました。具体的にどういう、あるいは逆にいろいろ便宜を図ってもらえるみたいなものがあるとか、そこのところをちょっとあればお伺いしたいと思います。","respondent":"南雲都市開発課長","answer":"自分の土地だからといって、勝手に自分のとこだけで決められるというものではありませんで、できた後の管理についても共同していただくです。隣の組合との敷地境界のところには、単独で行いますと隣地の斜線制限がありますけれども、隣同士の建物も規制については緩くなるです。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどのビデオで、少しここの建物が低くなってたかなと思うんですけれども、これは何メートルぐらいなんか尋ねました。","respondent":"南雲都市開発課長","answer":"こちらの建物ですが、組合のほうは２２階で、このティクスのほうの建物は１７階ですので、５層ですから、１５メートルから２０メートルくらい低いという形になります。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"私質問したときに、たしか６００億円ぐらいの総事業費で１２８億円ぐらいの補助金になるんじゃないかと、それはそれであるわけですよね。そこから変化していないということ、そういう意味か尋ねました。","respondent":"南雲都市開発課長","answer":"その事業の資金計画などについて変化しておりまして、総事業費も変化が予定されておりまして、まだ確定的な数字は出ておりません。過去にご報告した金額、それからパーセントの率と、ちょっと数字は後半変わるということでご理解いただきたいと思います。","id":"exchange-039"},{"speaker":"本田委員","kind":"質問","question":"その図面で三つ目のシーサイド駅の入り口というのはどこのところになるんですか。その工事の進捗はどのくらいにできるわけか尋ねました。","respondent":"南雲都市開発課長","answer":"このシーサイド駅は、交通広場の近くですね。それとあと、これについては平成１４年１２月に、この下の部分にはこの駅もオープンする予定です。","id":"exchange-040"},{"speaker":"本田委員","kind":"質問","question":"交通広場と店舗棟のところ、この図面で何か白いようなコンマみたいなのがあるのが、これが出入り口の建物なんですか、今言ったのは。","respondent":"南雲都市開発課長","answer":"このパースの中で白い屋根のようなものがかかっているところがあります。交通広場の道路際のところと、店舗の道路際のところですが、これがこの駅から地上に出てくる出入り口の屋根です。","id":"exchange-041"},{"speaker":"築舘委員","kind":"質問","question":"そこの両側と、あと交通広場に入るところは信号がつくんですか。真ん中の入り口ができるじゃないですか、ここの地区幹線道路。","respondent":"南雲都市開発課長、岩田管理工事課長","answer":"この真ん中の道路から交通広場に入る部分と、それから海岸通り、補助１６０号線のところに３カ所、信号がつきます。 済みません。この東西海岸通りと１６０号線に通じます貫通道路に新たに設置する信号機は、交差部に１カ所、真ん中の交通広場の入り口には信号はつきません。 だから２カ所です。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問","question":"もっと少ない人で１筆というか、それぞれがあの形で登記できるのかどうかわからないのだけれども、土地権利者はどのくらいいるんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"越した方の、自分の隣のうちを買ってるというようなことがありますが、今のところはやはり４９名権利者さんがいらっしゃる。ですから、４９名の土地持ちの方がいらっしゃるというふうにつかんでおります。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"ですから、１歩２歩も踏み込んだ形で、やはりああいう状況というのは改善されていかないよね。だけれども、そういう状況ですから、それを本当に束ねるくらいの指導というか、行政上はどうお考えになるか。","respondent":"浜脇住環境整備課長","answer":"工事助成とか支援といったことはできるんですが、今度区のほうにそれが、なかなか今の仕組みの中では難しいというのが実情です。その辺を、何とかうまく負担がどんどんお互いが少なくなるような手法を検討していっても、基本としては中に入ってまいりたいという気持ちはあります。","id":"exchange-044"},{"speaker":"石田委員","kind":"意見","question":"どういうお話をされたかわかりませんが、２度目にゼロになってしまった、このゼロになってしまったという理由が何かと。１回目のときに、どこら辺にどういう理由があってゼロになっちゃったのかなと思ってらっしゃるかというのを、まず１点との意見を述べました。","respondent":"浜脇住環境整備課長","answer":"何かのローンみたいなのを持っていらっしゃって、それからさらに、そういったものを用意するのは難しい。借りかえたものがふえて返せる、あるいは利益が上がるということがやはりできないのではないか、そういう不安がやはり一番だと思います。","id":"exchange-045"},{"speaker":"石田委員","kind":"質問","question":"４組合の中でちょっと話たら、あれは大会社がつくったかどうかわかりませんが、イメージのものをつくってくれるんですね。何でもいいけれども、そういう資金化計画まで含んだものを持っていったことがあるのか、ないのかそれをお聞きします。","respondent":"浜脇住環境整備課長","answer":"私どもとしては、今考えられるプランとして、実を言うと２つの方式で提示してあります。全戸ごとにお渡しして、職員が一人一軒一軒に行って置いてきましたし、いらっしゃるときには説明させていただきました。","id":"exchange-046"},{"speaker":"石田委員","kind":"質問","question":"今２つのもの、じゃそれを民間でやったらどうなんですかというとこまで突っ込んで、建物の高さの問題も含めて保留床をつくっていけばいいわけですね。この貸す費用のものまで突っ込んで出しているのかどうかわからないけれども、そこまで突っ込んでやっていらっしゃるのかどうか、お答えください。","respondent":"浜脇住環境整備課長","answer":"それから、やはり地元の方が２０名もいらっしゃいますと、そういったものを行政側が一緒に配付するというのは非常に難しい状況に今はあります。以上です。","id":"exchange-047"},{"speaker":"横山委員","kind":"質問","question":"その人の利益も生まれてくるわけですから、そういった後押しがない限り、絶対私はだめだと思うんですね。そこら辺に根っこがあるんじゃないかなと思うので、それを外して幾ら論議を積み重ねても、到達点はないんだと私は思うんですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"世田谷は、正直言って、今から何年ぐらい前ですか、前にここへ行って勉強しているんですよね。ですから、そういうふうにちょっと感じるので。","respondent":"浜脇住環境整備課長","answer":"北沢３・４丁目というところを、北沢３・４丁目に行ったらどうですかということで、たしか世田谷区３・４丁目をご案内したと思います。浜脇君のところで３・４丁目に行ったほうがいいんじゃないと言っていましたもので、今ご提案のは、前回行ったところとは違います。","id":"exchange-049"},{"speaker":"横山委員","kind":"意見","question":"訪問の仕方で、品川区というのはまだ勉強かというような、そう言われないような形で行かないといけないなと。同じ区だし、同じ街の、地域が違っても、そこら辺のことがあるということだけとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"川西委員","kind":"意見","question":"一口で言うと、こんなのが品川でできんのかなという意見が多かったんです。そういう中でどうやって、１つずつ提示していかないと、理事者に応援をしたらいかがと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"石田委員","kind":"意見","question":"２回目に行くときとか、行くときにどうしてもやりたいという意思で行かれるんでしょうけれども、ここというときが必ずありますよね。じゃそれならかち合ったらどうなるか、議会から上げて、委員会から上げてとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"こういうところで読み取っていただこうというのがちょっとあったものですから、またこれができたらいいですよというのは、ちょっとなかなか次回に言えるというのはきついかなという状態なんです。","id":"exchange-052"},{"speaker":"本田委員","kind":"質問・要望","question":"都なり国に対する要望書なり、議会として委員会としてまとめて、バックアップをしていくという形をつくっていくのか。この問題をテーマに詰めてきて、最後の段階でご支援できるやり方というのを私は考えたほうがいいんじゃないかなと思ってはいるんですよね。","respondent":"山室住宅指導担当部長","answer":"そういうことを承知の上で一つのスキーム、いろいろ考えてありますので、またご説明できるというふうに思っております。きょうの意見をいろいろ我々も、貴重なご意見をいただきましたので、それを検討の中にはめていければと思います。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/506587?Template=document&Id=6216#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":55018,"voices":145}},{"id":"h13-20010928-14","meetingId":"h13-cm09","date":"2001年9月28日","dateIso":"2001-09-28","committee":"行財政改革特別委員会","time":"午前１０時０８分～午後０時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"これのように１４年度から廃止、手続というんでしょうか、そういうものを受けとめるルールづくりが私は必要だというふうに思っているんです。そうした区民の声もきちっと受けとめるという、そこの道路づくりが私は必要だなと思うんですけども、それはいかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"見直しにつきましても検討していく方向性が出ていますので、どういう方向性で見直していくのかという形で検討していただくという形で出ております。その部分でまた変わっていく可能性はないわけじゃないですけども、ほぼこの方向で実施できるだろうということで…","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"やはり、こういう時代ですから、意欲を持った住民の皆さんが、例えば図書館ボランティアなんていうのがありますよね。そういうところを二つ指摘をしておきたいんですけど、コメントがあれば。","respondent":"榎本行財政改革担当課長","answer":"最終的にその事業をどういう方向に進めたらいいのかという論議を踏まえて進めていくというような仕組みづくりかなというふうに事務事業評価はなって…そういう街路樹の管理…","id":"exchange-002"},{"speaker":"金高委員","kind":"意見","question":"その各課の職員の間でもって、それぞれ評価の基準でもってどうするかという方向づけが出たんですけど、今まではそういうことはなかったわけですね。その辺のところはどういう形でもって目に見えてきているのか、その辺、何かもしあればとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"各担当者もこの事務事業評価を何のために行うのかという部分につきましては、かなり論議や説明をした中での意識というのは高まっていると思います。ちょっとまだ、この通知を出してから、まだその部分というのは今これからやるところです。","id":"exchange-003"},{"speaker":"金高委員","kind":"質問","question":"それでちょっと、実際に９月でもって、とりあえず１回目は終わりましたということですので。要するに上半期というんですか、その辺の取り組みがどういう形になっているか、ちょっと説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"下半期の取り組みですけれども、実際にはこの事務事業評価を２１２本実施したところ、ある程度出てきています。それに対して対応できるように、来年度なかなか実施できない部分がありますので、この辺を下半期でやるような形で進めております。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"その辺の長期計画と違った評価がされてくる場合、その辺の修正というんでしょうか、係わりをどのように考えているのか聞きたいと思います。","respondent":"榎本行財政改革担当課長","answer":"実際には総合実施計画の各柱を各事務事業がどう支えているかという形での関連についてという形になっております。その総合実施計画の上に長期計画というのがありまして、実施計画、一つの施策を支えている実施計画の中身で支えている事務事業の評価が。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"助成する部分ですごく目立ったんですけども、この辺の違いというのはどのようにとらえているのか、ちょっと細かいことをお聞きします。","respondent":"中尾根企画部長","answer":"一つ一つの事業を検討したときに、そういう部分に非常に現場サイドの考え方としては、それが強かったというふうに受けとめてあります。かなりやり方なり、手法なりは再検討ということは当然していくわけなんですけれども、事業そのものについての廃止については。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"仕組みの中で２年目以降にこの評価の中にその結果が出てくるのかもしれないんですが、要は、結果の評価というのはどういう形で出ていくのか。９事業を廃止・中止にする事業として、まずできなかったわけですから、その仕組みの中ではどういう形で出ていくのかちょっとお伺いしたいんですけど。","respondent":"榎本行財政改革担当課長","answer":"検討の方向といたしましては、その中から幾つかピックアップして、来年も続けて評価してもらうものという形でのセレクトができると思います。３年間をかけますというような形での説明がございましたけれども、特にＤ事業であれば、数限られていますので。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望になりますけども、できていないだけではなくて、さらに一歩踏み込んだ結果があらわれるような仕組みにぜひしてほしいと求めました。これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"政策的には事業としてはＡだろうけど、内部に問題あり。今までの内部的疑問点、評価に出たところを直していく努力というのを今後どうやっていくのか、それをお聞きしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それについて、それを各課長の部分のレベルまで今後の実施方法とか、説明をきちんと明確にした形での評価の戻しはちょっとしていませんので。それをさらに重点的に実施しているけども、それが逆にＣからＢ…","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、課長がしっかり、私が見ているときは区民の代表で見ていますからね、区民の代表ですから。一次評価、全体をＡにするためにはどうしたらいいかというディスカッションなり、どう反映していくのかということを聞きたいんですけど。","respondent":"榎本行財政改革担当課長","answer":"それが事務事業評価の一番の目的でございまして、要はこの評価を今度区民の皆さんに公表していく段階で議論をしていかなくちゃいけない。その部分の、そういう意見をいただいた上でそういう議論すべき場所等を設けて事業を実際に進めていく形になるのかなというふうに考えており…","id":"exchange-010"},{"speaker":"辻副委員長","kind":"確認","question":"来年度の流れですね、１４年度になったときにも、やはり今ごろの時期に評価というか、その結果が出てやるのかどうか、ちょっと確認したい。そして、結果発表するというのは、大体同じスケジュールなの、どうなの。","respondent":"榎本行財政改革担当課長","answer":"９月下旬までには一定の結論を出すという大まかな流れというものは同じような形で事務事業評価につきましてはやらざるを得ないと考えております。最終的な終わり、９月下旬ごろに最終的な二次評価を出すという仕組み、日程的には同じような形になっております。","id":"exchange-011"},{"speaker":"辻副委員長","kind":"意見","question":"そういう書類というのは公開の対象になっているの。要するに、詳しく我々が知りたい、見たいとかといった場合に、どうだろうとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"ちょっとまだその部分というのはどういう取り扱いかという形で、どういう形で公表したらいいのかという部分を、これからちょっと検討する段階です。それを個別に、シートで見れるというふうな形でいきたいと考えていますけれども…","id":"exchange-012"},{"speaker":"辻副委員長","kind":"質問・要望","question":"でも、経営会議で行うということはどういうことを言ってきているのかというような、そのスケジュール的なことを確認させてほしいと求めました。新しいものをどう発想していくかという、ここをどういう仕組みで今後考えていらっしゃるのか、ちょっと伺いたいと思います。","respondent":"中尾根企画部長","answer":"それからもう一つの点で、モニタリングも随分出ましたけど、モニタリングも非常に重要だというのを、改めて私ども再認識しております。今回のこういう一連の事務事業評価そのものが来年度以降生きていくようにということでやってありますので、ご理解いただきたいと思います。","id":"exchange-013"},{"speaker":"辻副委員長","kind":"質問","question":"なお、我々ある議員という立場というのはさまざまな人の代表ですから、その見方。これは１回、２回、いろいろ我々もまだ勉強していきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"鶴委員","kind":"意見","question":"どう取り組んでいくのか、うちは品川区のほうが随分進んでいるから、あまり関係ないんだということになっていくのか。そうじゃなくて、ちょっとお尋ねしておきたいなというふうに思いましたとの意見を述べました。","respondent":"中尾根企画部長","answer":"やはりそこの住民の合意の中で進めるということですから、常にやっぱり国全体がどう考えているのか、上部団体である都道府県レベルではどうなのか。なおかつ全体の方針がそういうものと即応しているのかどうか、いつも毎年総合実施計画のローリングの中では…","id":"exchange-015"},{"speaker":"鶴委員","kind":"意見","question":"やっぱり皆さんがなぜそれを望んでいるのか、今後どういう手法で、あまり多くの人は語らないですね。今後どういうふうにして、多くの３２万人の区民の皆さんの動向というか、その点はどういうふうに考えていらっしゃいますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"その辺のＩＴ化の中で、そういう住民からの意見等を電子メールで取り入れるような仕組みも若干検討が進んでいるようです。そういう１０万の意見のうち、まとまりが幾つかに分かれていくだろうというような形でのシステムも検討しているというような話もございました。","id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"調理委託だって、例えば学校給食はどうですか。しかしながら、民間委託している施設だっていっぱいあるじゃないですか、社会福祉法人。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"そういうことについて、皆さんが騒然となるわけですけども、そういうことについての皆さんの意見の吸収というのは、どういう手法で、インターネットのあれで待っているわけか尋ねました。","respondent":"中尾根企画部長","answer":"まずはやっぱり考えているところをよく私たちは理解する、本を貸せばいいじゃないか、目的だ。そこの利用者のところにアンケートをとるなり何なりをして、そういう結果が来年以降にあらわれてくるんではないか、このように考えてあります。","id":"exchange-018"},{"speaker":"桜井委員","kind":"確認","question":"今の区民への公表の部分なんですけど、先ほど一応スケジュールだと３月ですよね。この２１２の事業を見直したものを全部評価していくという、そういう基本的な考え方でいいのかどうか、そこをもう一度確認したいんですけど。","respondent":"榎本行財政改革担当課長","answer":"それからホームページでそれよりもう少し細かい説明、それからさらに、このような形で公表するとかという形での検討をしております。今年につきましては、かなりホームページというものは費用がかさむ部分がありまして、最終的にそこの部分は検討していきたいと考えています。","id":"exchange-019"},{"speaker":"本多委員","kind":"質問・要望","question":"２、行政評価は、その改革が市民の期待に沿った方向に進んでいることの確認をどのようにして行っているかについて。３番目につきましては、透明性の向上による行政不信を抑えることに成功した事例などの内容について調査をしていただきたいという内容です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"桜井委員","kind":"意見","question":"行政評価をどういうふうにしているのかちょっとわかりませんで、こういうことでお願いというよりも、委員の方がこういう意見を出されたというその程度にとどめていただければありがたいというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"鶴委員","kind":"質問","question":"今、帰国されてからの報告事項というのは大変参考になるわけですから、海外視察というものを実効たらしめるための手段としてもこういうことは必要だ。この委員会として、まとめてしかるべき調査をしてきてもらうということが私は望ましいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"金高委員","kind":"提案","question":"１５年と、なおかつずっとやっているわけですから、先発としてやっている方向づけが見えてきていると思うんですね。ただ、それにつけ加えるようなことも持ってきていただきたいというふうに要望しておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"手続的に議長から委員長への問いかけですから、委員長が委員会を代表されますので、委員会としてよきお返事をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"桜井委員","kind":"意見","question":"でも、多数の皆さんが、いや、委員会としてせっかくだからというならば、それはそれとしてやむを得ないと思いますけど。賛否を問うというふうには思っていませんけどとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"辻副委員長","kind":"質問・要望","question":"要するに、例えば、市議会の役割、品川の区議会とまるっきり違う、その中の、そういうところの仕組みというのをよく調べていただきたい。評価の範囲は金高委員が言ったように、ちょっとそのところは持っていてほしい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"鶴委員","kind":"質問・要望","question":"今、辻委員が言いましたけど、特にそれぞれの訪れたところで結構ですから、議会の定数、人口と定数というのを。夜間、行政との話し合いで決めているのかとか、そういう人口に対する議会の定数というのをちょっと調べておいていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503251?Template=document&Id=5692#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":37384,"voices":77}}]);
